    \centering
    \includegraphics[width=\linewidth]{sae.pdf}
    \caption{Schematic representation of a deep symmetric autoencoder.}
    \label{fig:scheme}
\end{figure}

\subsection{About the activation function}
We highlight the fact that, differently from other works in the literature, we require the activation function to be invertible, so that we can use $\act$ for the encoder and $\invact$ for the decoder, respectively. The same construction can be found in \cite{otto2023learning}.
We argue that this requirement is fundamental to obtain a truly symmetric architecture, as it highlights the specular role of the encoding and decoding mechanisms.

Additionally, in order to guarantee a minimal form of stability, we also require $\act$ to be bilipschitz. It can be shown, in fact, that this is equivalent to having both $\act$ and $\invact$ to be Lipschitz continuous: see Lemma~\ref{lemma:bilipschitz} right below.

\begin{lemma}
    \label{lemma:bilipschitz}
    Let $\act:\mathbb{R}\to\mathbb{R}$ be bilipschitz, meaning that there exists two positive constants, $\eta>0$ and $L>0$, such that
    \begin{equation}
        \label{eq:bilipschitz}\eta|x-y|\le|\act(x)-\act(y)|\le L|x-y|\quad\forall x,y\in\mathbb{R}.
    \end{equation}
    Then, $\act$ is bijective and its inverse is also bilipschitz. Furthermore, Eq.~\eqref{eq:bilipschitz} holds with $\eta=1/\lip{\invact}$ and $L=\lip{\act}.$
\end{lemma}
\begin{proof}
    See Appendix~\ref{appendix:proofs}.
\end{proof}

\sloppy{
This bilipschitz control will be fundamental for our construction, as it ensures a stable behavior both during training and during inference. Indeed, it is straightforward to prove that, for any $\autoencoder = \{(\bVE_j, \bVD_j, \biasE_j, \biasD_j, \act)\}_{j=1}^{n_l}$, one has $\lip{\mathscr{R}(\autoencoder, \cdot)} \propto (\lip{\act}\lip{\invact})^{l-1}$.} In this respect, we take the chance to introduce the notion of \emph{sharpness}, a quantity that is specific of bilipschitz activations and that we define as
\begin{equation}
    \label{eq:sharpness}
    \angle(\act) = \lip{\act}\lip{\invact} - 1 \ge 0.
\end{equation}
Essentially, the sharpness provides a quantitative measure of the instability brought by $\act$, and also serves to quantify its degree of nonlinearity: notice, in fact, that $\angle(\act)\equiv0 $ whenever $\act$ is linear. 

Examples of bilipschitz activations include:\\

\begin{itemize}[itemsep = 4pt, leftmargin = 0.6cm]
    \item[{\em (i)}] the $(\alpha,\beta)$-LeakyReLU activation, already considered in \cite{teng2019invertible}. Given $\alpha,\beta>0$, with $\alpha\neq\beta$, the latter is defined as
    \begin{equation*}
        \operatorname{LeakyReLU}_{\alpha,\beta}(x) = \alpha x \mathbf{1}_{(-\infty,0)}(x) + \beta x \mathbf{1}_{[0,\infty)}(x),
    \end{equation*}
    where $\mathbf{1}_E$ denotes the characteristic function of the set $E$;

    \item[{\em (ii)}] the $\theta$-Hyperbolic activation, first proposed by Otto et al. \cite{otto2023learning}. Given $\theta\in(0,\pi/4)$, the latter reads
    \begin{equation*}
        \operatorname{HypAct}_{\theta}(x) = \frac{b_\theta}{a_\theta}x- \frac{\sqrt 2}{a_\theta \sin\theta}+ \frac{1}{a_\theta}\sqrt{\biggl(\frac{2x}{\sin\theta\cos\theta} - \frac{\sqrt 2}{\cos\theta}\biggr)^2 + 2a_\theta},
    \end{equation*}
    where $a_\theta = \csc^2(\theta) - \sec^2(\theta)$ and $b_\theta = \csc^2(\theta) + \sec^2(\theta).$\\
\end{itemize}

\begin{figure}
    \centering
    \includegraphics[width=\linewidth]{activations.pdf}
    \caption{Visualization of the $(\alpha,\beta)$-LeakyReLU and $\theta$-Hyperbolic activations for different values of their hyperparameters.}
    \label{fig:activations}
\end{figure}


We refer the reader to Fig.~\ref{fig:activations} for a visualization of how the hyperparameters $\alpha,\beta$ and $\theta$ affect the two activations.
It is worth mentioning that each activation function comes with its own strenghts and limitations. The $(\alpha,\beta)$-LeakyReLU activation, for instance, has the advantage of providing a direct control over the Lipschitz constant of the nonlinearity used for encoding and decoding, respectively. In fact, if $\act=\operatorname{LeakyReLU}_{\alpha,\beta}$, then $\lip{\act}=\max\{\alpha,\beta\}$ and $\lip{\invact}=\max\{1/\alpha,1/\beta\}$. This nonlinearity, however, is not as smooth as the $\theta$-Hyperbolic activation, which, in contrast, has the benefit of being infinitely differentiable. In turn, the latter does not distinguish as much between encoding and decoding, since
$\act = \operatorname{HypAct}_{\theta}\;\implies\;\lip{\act}=\lip{\invact}=\tan\left(\theta+\frac{\pi}{4}\right).$ 


\newcommand{\SAE}{\textnormal{\textsf{SAE}}_\act(n_0,\dots,n_l)}
\newcommand{\SBAE}{\textnormal{\textsf{SBAE}}_\act(n_0,\dots,n_l)}
\newcommand{\SOAE}{\textnormal{\textsf{SOAE}}_\act(n_0,\dots,n_l)}

\newcommand{\SAEz}{\textnormal{\textsf{SAE}}_\act}
\newcommand{\SBAEz}{\textnormal{\textsf{SBAE}}_\act}
\newcommand{\SOAEz}{\textnormal{\textsf{SOAE}}_\act}

\subsection{Classes of symmetric autoencoders} Given a decreasing sequence of integers, $\ndim > n_1\ge\dots\ge n_l>0$, and a bilipschitz map $\act:\mathbb{R}\to\mathbb{R}$, we shall write
$$\SAE=\prod_{j=1}^{n_l}\left[\mathbb{R}^{n_j\times n_{j-1}}\times \mathbb{R}^{n_{j-1}\times n_{j}} \times \mathbb{R}^{n_j}\times \mathbb{R}^{n_{j-1}}\times\{\act\}\right],$$
for the space of all symmetric autoencoders associated with the given architecture.


We also introduce two additional subclasses, obtained by requiring the above networks to satisfy additional constraints related to their weights and biases. Specifically, we consider the subclass of \emph{symmetric biorthogonal autoencoders}, already introduced in \cite{otto2023learning},
\begin{align*}
    \SBAE:=\{\autoencoder\in\SAE\;:&\;\bVE_j\bVD_j=\mathbf{I}_{n_j}\;\;\text{and}\\&\;\bVE_j\biasD_j=-\biasE_j\;\;\forall j=1,\dots,n_l\},
\end{align*}
and the one of \emph{symmetric orthogonal autoencoders},
$$\SOAE:=\{\autoencoder\in\SBAE\;:\;\bVE_j=\bVD_j^\top\}.$$
By definition,
$\SOAE\subseteq \SBAE\subseteq \SAE.$ Notice that, as one moves from the broader to the tighter class of autoencoders, the number of architecture parameters decreases. For instance, in the biorthogonal case, the encoding bias vectors $\biasE_j$ are univocally determined by $\bVE_j$ and $\biasD_j$. Similarly, in the orthogonal case, knowing the encoding matrix is enough to derive the decoding matrix and vice versa. 
In light of this, we shall use the following short-hand notation:
\begin{itemize}[itemsep=6pt, before=\vspace{4pt}, after=\vspace{4pt}]
    \item if $\autoencoder\in\SBAE$ we shall write $\{(\bVE_j,\bVD_j,\bias_j,\act)\}_{j=1}^{n_l}$ to intend the symmetric autoencoder $\{(\bVE_j,\bVD_j,-\bVE_j\bias_j,\bias_j,\act)\}_{j=1}^{n_l}$;
    \item if $\autoencoder\in\SOAE$ we shall write $\{(\bV_j,\bias_j,\act)\}_{j=1}^{n_l}$ to intend the symmetric autoencoder $\{(\bV_j^\top,\bV_j,-\bV_j^\top\bias_j,\bias_j,\act)\}_{j=1}^{n_l}$;
\end{itemize}
With this notation, the encoding layers read $e_j:\mathbf{h}\mapsto\act(\bVE_j(\mathbf{h}-\biasE_j))$ in the biorthogonal case, and $e_j:\mathbf{h}\mapsto\act(\bV_j^\top(\mathbf{h}-\biasE_j))$ in the orthogonal case. Notice, in particular, how the encoding formula used in the orthogonal case finds a natural connection to the one adopted in the context of linear reduction: cf. Eq. \eqref{eq:linear-encoding-decoding}. Similar considerations hold for the decoding phase as well. 

\sloppy{
Notwithstanding, it is worth emphasizing that the constraints fulfilled by $\SBAE$ and $\SOAE$, respectively,  give the two classes several remarkable properties. In particular, one can show that all biorthogonal symmetric autoencoders are representation consistent: a given object and its reconstruction both map onto the same latent representation. As an immediate  consequence, all $\autoencoder\in\SBAE$ act as nonlinear projectors.
Orthogonal symmetric autoencoders, in turn, have the additional benefit of providing a direct control over the Lipschitz constants of the encoder and the decoder modules, which can be extremely useful when model stability becomes a necessity. These facts are made rigorous in the Proposition below.
}
\begin{proposition}
    \label{prop:classes}
    Let $\ndim > n_1\ge\dots\ge n_l$ be positive integers and let $\act:\mathbb{R}\to\mathbb{R}$ be bilipschitz. The following hold true.

    \begin{itemize}[before=\vspace{5pt}, itemsep = 2pt, leftmargin=18pt]
        \item[(i)] $\autoencoder\in\SBAE\Rightarrow \mathscr{E}(\autoencoder,\mathscr{D}(\autoencoder,\mathbf{c}))=\mathbf{c}$ for all $\mathbf{c}\in\mathbb{R}^{n_l}.$

        \item[(ii)] $\autoencoder\in\SBAE\Rightarrow \mathscr{R}(\autoencoder,\mathbf{v})=\mathbf{v}$ for all $\mathbf{v}\in\mathscr{R}(\autoencoder,\mathbb{R}^{n_0}).$

        \item[(iii)] $\autoencoder\in\SOAE \Rightarrow\lip{\mathscr{E}(\autoencoder, \cdot)}\le \lip{\act}^l,\;\;\lip{\mathscr{D}(\autoencoder, \cdot)}\le \lip{\invact}^l$.
    \end{itemize}
\end{proposition}

\begin{proof}
    See Appendix~\ref{appendix:proofs}.
\end{proof}

\subsection{Training of symmetric autoencoders}
\label{subsec:training}
Given some $\bu\in L^2(\mathscr{P};\mathbb{R}^{n_0})$, and a corresponding training set $\bu_1,\dots,\bu_{S}\in\mathbb{R}^{n_0}$, consisting of $S$ independent random realizations of $\bu$, the practical implementation and training of a symmetric autoencoder consists in: \emph{(i)} choosing a suitable architecture, thus identifying a proper hypothesis class $\hypclass\subseteq\SAE$; \emph{(ii)} training the model by minimizing the empirical loss
\vspace{-0.2cm}
\begin{equation}
\label{eq:loss}
\mathscr{L}(\boldsymbol{\Psi})=\frac{1}{S}\sum_{i=1}^{S}\|\bu_i-\mathscr{R}(\boldsymbol{\Psi}, \bu_i)\|^2.
\vspace{-0.2cm}\end{equation}
In the case of unconstrained symmetric autoencoders, $\hypclass=\SAE$, such minimization problem can be addressed using classical optimization routines. Conversely, things become slightly more involved if we consider architectures with (bi-)orthogonality constraints, namely, if either $\hypclass=\SBAE$ or $\hypclass=\SOAE$. In those cases, in fact, one must guarantee that the optimization procedure does not exit the hypothesis manifold $\hypclass$, meaning the autoencoder must satisfy the (bi-)orthogonality constraints throughout the entire training phase.

One way to overcome this difficulty, and to make ensure that all orthogonality constrains are fulfilled \emph{by design}, is to introduce a suitable parametrization. To this end, let
$\orthparam: \mathbf{A} \mapsto \tilde{\mathbf{A}},$
be any (differentiable) algorithm that, given a rectangular matrix $\mathbf{A}\in\mathbb{R}^{m\times n}$ with $m\ge n$, returns an orthonormal matrix  $\tilde{\mathbf{A}}\in\mathscr{O}_{m,n}$ such that $\text{span}(\mathbf{A})\subseteq\text{span}(\tilde{\mathbf{A}})$, with equality when $\mathbf{A}$ has full rank. An example of such algorithm is the one used in the \texttt{pytorch} library \cite{pytorch}, which is based on the use of Householder reflections. 

\paragraph{SOAE}
Given $\act$ and $n_0,\dots,n_l$, let $\Theta:=\prod_{j=1}^{l}\left[\mathbb{R}^{n_{j-1}\times n_j}\times \mathbb{R}^{n_{j-1}}\right]$ denote our parametrization space. For any $\boldsymbol{\theta}=\{(\mathbf{A}_j,\mathbf{b}_j)\}_{j=1}^l\in\Theta$, we denote by $\boldsymbol{\Psi}_{\boldsymbol{\theta}}$ the symmetric orthogonal autoencoder obtained by setting $\boldsymbol{\Psi}_{\boldsymbol{\theta}}:=\{(\orthparam(\mathbf{A}_j),\mathbf{b}_j,\act)\}_{j=1}^l.$ It is straightforward to see that such parametrization is surjective, meaning that any $\boldsymbol{\Psi}\in\SOAE$ can be written as $\boldsymbol{\Psi}=\boldsymbol{\Psi}_{\boldsymbol{\theta}}$ for some $\boldsymbol{\theta}\in\Theta$. This allows us to reframe the learning problem in terms of the underlying parametrization, namely, using
$$\tilde{\mathscr{L}}(\boldsymbol{\theta}):=\mathscr{L}(\boldsymbol{\Psi}_{\boldsymbol{\theta}}).$$
The training phase will then consist in finding the optimal $\boldsymbol{\theta}_*\in\Theta$ that minimizes $\tilde{\mathscr{L}}$, and then assembling the corresponding autoencoder.

\paragraph{SBAE} A similar procedure can be carried out in the biorthogonal case, althought the parametrization is significantly more involved. For $q\ge r$, one can construct two matrices $\bVE\in\mathbb{R}^{r\times q}$ and $\bVD\in\mathbb{R}^{q\times r}$ satisfying $\mathbf{E}\mathbf{D}=\mathbf{I}_{r}$ by letting
\begin{equation}
\label{eq:biorthogonal-param}
\bVE^\top:=\mathbf{X}\left[\begin{array}{c}
     \mathbf{Y}\mathbf{S}\mathbf{Z}^\top\\
     \mathbf{0}
\end{array}\right]\quad\quad\text{and}\quad\quad\bVD:=\mathbf{X}\left[\begin{array}{c}
     \mathbf{Y}\mathbf{S}^{-1}\mathbf{Z}^\top\\
     \mathbf{Q}
\end{array}\right],
\end{equation}
where, having set $d:=\min\{r, q-r\}$, the matrices $\mathbf{X}\in\mathscr{O}_{q,r+d}$ and $\mathbf{Y},\mathbf{Z}\in\mathscr{O}_{r,r}$ are orthonormal, whereas $\mathbf{0}\in\mathbb{R}^{d\times r}$ is the zero matrix, $\mathbf{Q}\in\mathbb{R}^{d\times r}$ is arbitrary and $\mathbf{S}\in\mathbb{R}^{r\times r}$ is a diagonal matrix with strictly positive entries over the diagonal. Notably, this construction is surjective, in that one can easily show that any two biorthogonal matrices can be written as in \eqref{eq:biorthogonal-param}. Additionally, compared to other parametrizations seen in the literature, see, e.g., \cite{otto2023learning}, the one proposed here is fairly inexpensive as it only requires inverting a diagonal matrix with full rank.

In light of this fact, given $\act$ and $n_0,\dots,n_l$, we define the optimization space underlying a symmetric biorthogonal autoencoder architecture as $$\Theta:=\prod_{j=1}^{l}\left[\mathbb{R}^{n_{j-1}\times(n_j+d_j)}\times 
\mathbb{R}^{n_{j}\times n_j}\times \mathbb{R}^{n_{j}\times n_j}\times
\mathbb{R}^{d_{j}\times n_j}\times\mathbb{R}^{n_j}\times\mathbb{R}^{n_{j-1}}\right],$$
where $d_j:=\min\{n_j, n_{j-1}-n_j\}$. For any $\boldsymbol{\theta}=\{(\tilde{\mathbf{X}}_j,\tilde{\mathbf{Y}}_j, \tilde{\mathbf{Z}}_j, \mathbf{Q}_j,\mathbf{s}_j,\mathbf{b}_j)\}_{j=1}^{l}\in\Theta$ the corresponding autoencoder $\boldsymbol{\Psi}_{\boldsymbol{\theta}}\in\SBAE$ can be constructed as
$$\boldsymbol{\Psi}_{\boldsymbol{\theta}}=\{(\bVE_j,\bVD_j,\bias_j,\act)\}_{j=1}^l,$$
where each pair $(\bVE_j,\bVD_j)$ is assembled via \eqref{eq:biorthogonal-param} using the matrices $\mathbf{X}_j:=\orthparam(\tilde{\mathbf{X}}_j)$, $\mathbf{Y}_j:=\orthparam(\tilde{\mathbf{Y}}_j)$, $\mathbf{Z}_j:=\orthparam(\tilde{\mathbf{Z}}_j)$, $\mathbf{Q}_j$ and $\mathbf{S}_j:=\text{diag}(\mathbf{s}_j^2)$, where squaring is intended componentwise. Now, as in the orthogonal case, the optimization can be carried out in the unconstrained optimization space $\Theta$ rather than in $\SBAE$.

\begin{remark}
    Both in the case of orthogonal and biorthogonal constraints, the proposed parametrizations are surjective, thus ensuring a proper exploration of the hypothesis class during the training phase. Additionally, this approach guarantees that the constraints are satisfied \emph{by design}. This is in contrast to other strategies adopted in the literature, where the constraints are only \emph{weakly} imposed. For example, in \cite{otto2023learning}, the authors employ biorthogonal architectures, but the training is conducted over a broader hypothesis space, $\SBAE \subset \hypclass \subset \SAE$, with the biorthogonality requirement only being enforced indirectly by including an additional penalty term in the loss function \eqref{eq:loss}.  
\end{remark}



\section{Insights from the Eckart-Young-Schmidt perspective}
\label{sec:insights}
In this Section we shall derive some quantitative error bounds on the reconstruction error of symmetric autoencoders and use those to develop a new initialization strategy. We start by framing everything in an abstract setting, but later transition to a more practical perspective, focusing on the empirical case in which the autoencoder has to be constructed based on a finite amount of data.


\subsection{Theoretical considerations}
\label{subsec:theory}
Let $\bu\in L^{2}(\mathscr{P};\mathbb{R}^{n_0})$. Given $0<n_l\le\dots\le n_1\le n_0$ and $\act:\mathbb{R}\to\mathbb{R}$, we are interested in studying the reconstruction error
\begin{equation}
    \label{eq:reconstruction-error}
    \mathbb{E}\|\bu-\mathscr{R}(\autoencoder,\bu)\|^2,
\end{equation}
where $\autoencoder\in\SAE$. To start, we notice that one has the following chain of inequalities,
\begin{align}
\label{eq:ineq-chain}
\inf_{\autoencoder\in\SOAEz}\;
\mathbb{E}\|\bu-\mathscr{R}(\autoencoder,\bu)\|^2&\ge
\inf_{\autoencoder\in\SBAEz}\;
\mathbb{E}\|\bu-\mathscr{R}(\autoencoder,\bu)\|^2\\\nonumber&\ge
\inf_{\autoencoder\in\SAEz}\;
\mathbb{E}\|\bu-\mathscr{R}(\autoencoder,\bu)\|^2\ge \sum_{i=n_1+1}^{n_0}\lambda_i(\cmatrix[\bu]),
\end{align}
where we have dropped the dependency on $(n_0,\dots,n_l)$ to enhance readability.
The first two inequalities are obvious, as they stem from the fact that the autoencoder classes $\SAEz$, $\SBAEz$ and $\SOAEz$ are nested. The last inequality, instead, follows trivially by noting that, for each fixed $\autoencoder=\{(\bVE_j,\bVD_j,\biasE_j,\biasD_j,\act)\}_{j=1}^{l}\in\SAE$, the outputs of $\mathscr{R}(\autoencoder,\cdot)$ are contained in the $n_1$-dimensional affine subspace
$$V_{\autoencoder}:=\{\bVD_1\mathbf{c}+\biasD_1\;:\;\mathbf{c}\in\mathbb{R}^{n_1}\}\subset\mathbb{R}^{n_0}.$$
Then, as we discussed in Section~\ref{sec:linear-dim-reduction}, this immediately implies 
$\mathbb{E}\|\bu-\mathscr{R}(\Psi,\bu)\|^2\ge\mathbb{E}\left[\inf_{\mathbf{v}\in V_{\autoencoder}}\|\bu-\mathbf{v}\|^2\right]\ge \sum_{i=n_1+1}^{n_0}\lambda_i(\cmatrix[\bu])$, and thus \eqref{eq:ineq-chain}.

This highlights the fact that the first hidden dimension, $n_1$, plays a crucial role, as it directly affects the overall expressivity of the architecture. Since \eqref{eq:ineq-chain} already provides a lower-bound to \eqref{eq:reconstruction-error}, our purpose now is to gain some additional insights by deriving a suitable upper-bound. To this end, leveraging \eqref{eq:ineq-chain}, we shall focus for a moment on the smaller class of symmetric orthogonal autoencoders.

In this respect, we start by stating a very useful lemma, upon which the rest of our derivation is based.

\begin{lemma}
\label{lemma:deep}
Let $\boldsymbol{\Psi}=\{(\bV_j,\bias_j,\act)\}_{j=1}^{n_l}\in \SOAE$, where
$\ndim\ge n_{1}\ge n_2\ge\dots\ge n_{l}$ for some $l\ge2$, and $\act:\mathbb{R}\to\mathbb{R}$ is bilipschitz. Let $e_j=e_j(\autoencoder)$ and $d_j:=d_j(\autoencoder)$. Define $E_k := e_k \circ \ldots \circ e_1$ and $D_{k} := d_k \circ \ldots \circ d_l$. Let $E_0:=\mathsf{Id}_{\ndim}$ and $D_{l+1}:=\mathsf{Id}_{n_l}$ act as the identity. Then, for all $k=1,\ldots,l$, one has
\begin{align}
    \| E_{k-1}(\bv) - D_{k}(E_l(\bv))\|^2 \ge &\;\| E_{k-1}(\bv) - [\bV_{k} \bV_{k}^\top (E_{k-1}(\bv)-\bias_k)+\bias_k]\|^2\\&+\lip{\act}^{-2} \| E_{k}(\bv) - D_{k+1}(E_l(\bv))\|^2,\nonumber\\
    \| E_{k-1}(\bv) - D_{k}(E_l(\bv))\|^2 \le &\;\| E_{k-1}(\bv) - [\bV_{k} \bV_{k}^\top (E_{k-1}(\bv)-\bias_k)+\bias_k]\|^2\\&+\lip{\invact}^{2} \| E_{k}(\bv) - D_{k+1}(E_l(\bv))\|^2,\nonumber
\end{align}
for all $\bv\in\mathbb{R}^{\ndim}$.
\end{lemma}

\begin{proof}
    Notice that for all $\bv\in\mathbb{R}^{\ndim}$
\begin{align}
\label{eq:addenda-proof-lemma}
\nonumber
\| E_{k-1}(\bv) - D_{k}(E_l(\bv))\| \overset{def}{=} &\| E_{k-1}(\bv) - d_{k} (D_{k+1}(E_l(\bv)))\|^2 \\\nonumber
\overset{def}{=} &\| E_{k-1}(\bv) - \bV_{k}  \act^{-1} (D_{k+1}(E_l(\bv)))-\bias_k\|^2 \\\nonumber
\overset{orth}{=} &\| [E_{k-1}(\bv)-\bias_k] - \bV_{k}  \bV_{k}^{\top}[E_{k-1}(\bv)-\bias_k]\|^2 \\
&\hspace{0.cm} + \| \bV_{k}  \bV_{k}^{\top} [E_{k-1}(\bv)-\bias_k] - \bV_{k}  \act^{-1} (D_{k+1}(E_l(\bv)))\|^2,      
\end{align}
the first two equalities following by definition and the last one by orthogonality. Notice, in fact, that both $\bV_{k}  \bV_{k}^{\top}[E_{k-1}(\bv)-\bias_k]$ and $\bV_{k}  \act^{-1} (D_{k+1}(E_l(\bv)))$ belong to $\text{span}(\bV_k)$, to which $[E_{k-1}(\bv)-\bias_k] - \bV_{k}  \bV_{k}^{\top}[E_{k-1}(\bv)-\bias_k]$, the projection residual, is orthogonal. We now observe that the second term at the end of Eq. \eqref{eq:addenda-proof-lemma} can be re-written as
\begin{equation*}
\begin{aligned}
    &\| \bV_{k}  \bV_{k}^{\top} [E_{k-1}(\bv) -\bias_k]- \bV_{k}  \act^{-1}(D_{k+1}(E_l(\bv)))\|^2  = \\
    &\hspace{2cm} =\| \bV_{k}^{\top}[E_{k-1}(\bv)-\bias_k] -   \act^{-1}(D_{k+1}(E_l(\bv)))\|^2 \\
    & \hspace{2cm} = \| \invact(\act(\bV_{k}^{\top}[E_{k-1}(\bv)-\bias_k])) -   \act^{-1}(D_{k+1}(E_l(\bv)))\|^2\\
    & \hspace{2cm} = \| \invact (E_{k}(\bv)) - \act^{-1}(D_{k+1}(E_l(\bv)))\|^2.
\end{aligned}
\end{equation*}
Finally, thanks to the bilipschitzness of $\act$, cf. Lemma~\ref{lemma:bilipschitz}, we obtain the chain of inequalities
\begin{equation*}
\begin{aligned}
    \lip{\act}^{-2}\| E_{k}(\bv) - D_{k+1}(E_l(\bv))\|^2 &\le \| \invact (E_{k}(\bv)) - \act^{-1}(D_{k+1}(E_l(\bv)))\|^2 \\ &\le \lip{\invact}^2 \| E_{k}(\bv) - D_{k+1}(E_l(\bv))\|^2.
\end{aligned}
\end{equation*}
The above, combined with \eqref{eq:addenda-proof-lemma}, yields the desired bounds.
\end{proof}

Lemma~\ref{lemma:deep} takes advantage of the compositional structure of deep symmetric orthogonal autoencoders to derive suitable error bounds characterizing the projection error at each level $k=1,\dots,l$.
Leveraging Lemma~\ref{lemma:deep} in an iterative fashion, we can then easily prove the following general result. 

\begin{theorem}
\label{theorem:soae}
Let $\bu\in L^{2}(\mathscr{P};\mathbb{R}^{\ndim}).$
Let $\ndim\ge n_{1}\ge n_2\ge\dots\ge n_{l}$, $l\ge2,$ and let $\act:\mathbb{R}\to\mathbb{R}$ be bilipschitz. For all $\autoencoder=\{(\bV_j,\bias_j,\act)\}_{j=1}^{n_l}\in\SOAE$ one has{\small\begin{equation}
\label{eq:soae-lower}
\mathbb{E}\|\bu-\mathscr{R}(\boldsymbol{\Psi}, \bu)\|^2\ge\sum_{k=0}^{l-1} \lip{\act}^{-2k}  \mathbb{E}\| E_k(\bu) - [\bV_{k+1} \bV_{k+1}^\top (E_k(\bu)-\bias_{k+1})+\bias_{k+1}]\|^2,\vspace{-0.5cm}
\end{equation}}
{\small\begin{equation}
\label{eq:soae-upper}
\mathbb{E}\|\bu-\mathscr{R}(\boldsymbol{\Psi}, \bu)\|^2\le\sum_{k=0}^{l-1} \lip{\invact}^{2k}  \mathbb{E}\| E_k(\bu) - [\bV_{k+1} \bV_{k+1}^\top (E_k(\bu)-\bias_{k+1})+\bias_{k+1}]\|^2,
\end{equation}}
where $E_k:=(e_k\circ\dots\circ e_1)$, being $e_j:=e_j(\autoencoder)$ and $E_0:=\mathsf{Id}_{\ndim}$. 
\end{theorem}
\begin{proof}
We start by proving the lower bound \eqref{eq:soae-lower}. By Lemma~\ref{lemma:deep},
\begin{multline*}
   \mathbb{E}\|\bu-\mathscr{R}(\boldsymbol{\Psi}, \bu)\|^2 = \mathbb{E}\|E_0(\bu)-D_1(E_l(\bu))\|^2 \ge \mathbb{E}\| E_0(\bu) - [\bV_{1} \bV_{1}^\top (E_0(\bu)-\bias_1)+\bias_1]\|^2\\+\lip{\act}^{-2}\mathbb{E}\|E_1(\bu)-D_2(E_l(\bu))\|^2. 
\end{multline*}
Then, iteratively applying Lemma~\ref{lemma:deep} to the last term at the right-hand-side yields
\begin{align*}
   \mathbb{E}\|\bu-\mathscr{R}(\boldsymbol{\Psi}, \bu)\|^2&\ge\dots\\\dots&\ge\sum_{k=0}^{l-1} \lip{\act}^{-2k} \mathbb{E}\| E_k(\bu) - [\bV_{k+1} \bV_{k+1}^\top (E_k(\bu)-\bias_{k+1})+\bias_{k+1}]\|^2\\&\hspace{1.5cm}+\lip{\act}^{-2l}\mathbb{E}\|E_l(\bu)-D_{l+1}(E_l(\bu))\|^2.
\end{align*}
Notice, however, that the last term is actually zero as $D_{l+1}$ is the identity. This proves \eqref{eq:soae-lower}. Mirroring the above steps, but using the upper bound result in Lemma~\ref{lemma:deep}, yields \eqref{eq:soae-upper} and thus concludes the proof.
\end{proof}

What is most interesting about Theorem~\ref{theorem:soae} is that it bounds the reconstruction error in terms of $l$ terms, one per each layer, with the $k$th 
term connecting the $k$th hidden representation in the architecture, $E_{k}(\bu)$, with the trainable parameters at level $k+1$, $\bV_{k+1}$ and $\bias_{k+1}$. Furthermore, each term in Eqs. \eqref{eq:soae-lower}-\eqref{eq:soae-upper} can be interpreted as a linear reduction, happening at level $k$.

In particular, this suggests minimizing the upper-bound in \eqref{eq:soae-upper} by addressing each term alone, following a sort of greedy approach. These considerations lead to the following Corollary.

\begin{corollary}
\label{corollary:loose-bounds}
Let $\bu\in L^{2}(\mathscr{P};\mathbb{R}^{\ndim})$, $\ndim\ge n_{1}\ge n_2\ge\dots\ge n_{l}$ with $l\ge2,$ and let $\act:\mathbb{R}\to\mathbb{R}$ be bilipschitz. Set $E_0^*:=\mathsf{Id}_{n_0}.$ Starting with $k=0$, 

\begin{itemize}[itemsep = 4pt, before = \vspace{4pt}, after = \vspace{4pt}, leftmargin=15pt]
    \item[---] define $\bias_k^*:=\mathbb{E}[E^*_k(\bu)]$,
    \item[---] construct $\bV_{k+1}^*$ by extracting the $n_{k+1}$ eigenvectors of $\cmatrix[E_k^*(\bu)]$ associated to the $n_{k+1}$ largest eigenvalues,
    \item[---] define $E_{k+1}^*:\mathbb{R}^{n_0}\to\mathbb{R}^{n_{k+1}}$ by setting $E_{k+1}^*(\mathbf{v}):=\act(\bV_{k+1}^*E_k^*(\mathbf{v})+\bias_k^*)$. 
\end{itemize}
Iterate the previous steps for $k=1,\dots,l-1$. Then,
\begin{align}
\label{eq:ineq-chain2}
\inf_{\autoencoder\in\SAEz}\;
\mathbb{E}\|\bu-\mathscr{R}(\autoencoder,\bu)\|^2&\le
\inf_{\autoencoder\in\SBAEz}\;
\mathbb{E}\|\bu-\mathscr{R}(\autoencoder,\bu)\|^2\\\nonumber&\le
\inf_{\autoencoder\in\SOAEz}\;
\mathbb{E}\|\bu-\mathscr{R}(\autoencoder,\bu)\|^2\\\nonumber&\le \sum_{k=0}^{l-1}\lip{\invact}^{2k}\sum_{i=n_{k+1}+1}^{n_k}\lambda_i(\cmatrix[E_k^*(\bu)]).
\end{align}

\end{corollary}

We highlight that Eqs. \eqref{eq:ineq-chain} and \eqref{eq:ineq-chain2} are complementary, as they provide lower %bound 
and upper bounds for the reconstruction error of the optimal SAE, respectively. Despite being looser than the ones provided in Theorem \ref{theorem:soae}, such bounds have a practical implication on design and initialization of symmetric autoencoders, as we discuss below.
%Our idea, discussed in the next subsection, is to leverage these bounds to guide the design of symmetric autoencoders and to derive a tailored initialization routine.


%\subsection{Application to SAE design and initialization}
\subsection{From theory to practice: the EYS initialization}
Inspired by the considerations made in Section~\ref{subsec:theory}, particularly by Corollary~\ref{corollary:loose-bounds}, we propose a new initialization strategy for symmetric autoencoders hereon referred to as ``Eckart-Young-Schmidt (EYS) initialization". The idea is to mimic the greedy procedure described in Corollary~\ref{corollary:loose-bounds}, ultimately translating the latter to an empirical framework.

More precisely, let $\bu\in L^{2}(\mathscr{P},\mathbb{R}^{n_0})$, and assume we are given a collection of $S$ i.i.d. random realizations of $\bu$, denoted as $\bu_1,\dots,\bu_S.$ Fix any bilipschitz activation $\act$ and a suitable skeleton $n_0\ge n_1\ge\dots\ge n_l$ for a symmetric autoencoder. The idea is to leverage the data in order to come up with a suitable autoencoder $\autoencoder\in\hypclass\subseteq\SAE$ that constitutes a first initial guess to be used as a starting point for the training phase. As before, $\hypclass$ denotes the hypothesis class, which can be either the whole set of symmetric autoencoders, or may be limited to either orthogonal or biorthogonal architectures. Our proposed strategy, which is independent of $\hypclass$, is detailed in Algorithm~\ref{alg:eys}.

\begin{algorithm}[h!]
    \caption{EYS initialization (pseudo-code)}
    \label{alg:eys}
    \begin{algorithmic}[0]
    \STATE \textbf{Inputs:} %\begin{itemize}[noitemsep] \item[-] snapshot matrix $\mathbf{U} \in \mathbb{R}^{n_0 \times S}$ listing $S$ i.i.d. samples of $\bu$
    %\item[-] bilipschitz activation $\act$ 
    %\item[-] architecture skeleton $\{n_j\}_{j=1}^l$ \end{itemize}
    snapshot matrix $\mathbf{U} \in \mathbb{R}^{n_0 \times S}$ listing $S$ i.i.d. samples of $\bu$, bilipschitz activation $\act$, architecture skeleton $\{n_j\}_{j=1}^l$
    \vspace{0.15cm}
    \STATE $\mathbf{Z} \gets \mathbf{U}$ \hfill \texttt{\#initialize latent vector}
    \vspace{0.2cm}
    \FOR{$j = 1:l$}
    \STATE $\mathbf{b}_j \gets \overline{\mathbf{Z}}$ \hfill \texttt{\#compute sample mean}\vspace{2pt}
    \STATE $\mathbf{W}_j, \_, \_ = \texttt{SVD}(\mathbf{Z} - \mathbf{b}_j)$ \hfill \texttt{\#obtain left eigenvectors}\vspace{2pt}
    \STATE $\mathbf{V}_j \gets  \mathbf{W}_j[:,:n_j]$ \hfill \texttt{\#retain first $n_j$ vectors}\vspace{2pt}
    \STATE $\mathbf{Z} \gets \act(\mathbf{V}_j^\top(\mathbf{Z} - \mathbf{b}_j))$ \hfill \texttt{\#compute next latent vector}
    \ENDFOR
    \vspace{0.2cm}

    \STATE $\Psi_{\textsf{EYS}} \gets \{(\bV_j,\bias_j,\act)\}_{j=1}^{l}\in\SOAE$ \hfill \texttt{\#build autoencoder}

    \RETURN $\Psi_{\textsf{EYS}}$ %$\Psi_{\textsf{SOAE}} \in \SOAE$ param. by $\{(\tilde{\mathbf{V}}_j, \tilde{\mathbf{b}}_j, \act)\}_{j=1}^l$
    \end{algorithmic}
\end{algorithm} 

We highlight that Algorithm~\ref{alg:eys} follows the same construction seen in Corollary~\ref{corollary:loose-bounds}, but it leverages the empirical probability distribution
$\tilde{\mathbb{P}}:=\frac{1}{S}\sum_{i=1}^{S}\delta_{\bu_i},$
rather than the true law $\mathbb{P}$ of the random vector $\bu\sim\mathbb{P}.$ Here, $\delta_{\bu_i}$ denotes the Dirac delta distribution centered at $\bu_i$. Consequently, expected values appearing in Corollary~\ref{corollary:loose-bounds} are replaced by statistical averages, whereas the eigenvectors of the covariance matrices are approximated via empirical SVD (up to centering). In particular, we notice that the EYS initialization ultimately consists in an iterative application of the SVD, progressively going from $n_0$ to $n_l$.

We also point out that, regardless of the chosen hypothesis class $\hypclass$, the EYS initialization always returns a symmetric orthogonal autoencoder, $\autoencoder_{\textsf{EYS}}\in\SOAE$, coherently with the fact that
$$\SOAE\subseteq\hypclass\subseteq\SAE.$$
However, we also remark that during the training phase the autoencoder will be free to explore the whole hypothesis class, potentially exiting the submanifold of SOAE.

In this concern, it is worth spending a few words in order to clarify how the EYS initialization can be incorporated in the training procedure discussed in Section~\ref{subsec:training}. Let $\autoencoder_{\textsf{EYS}}=\{(\bV_j,\bias_j,\act)\}_{j=1}^{l}$. We distinguish between the three possible choices of the hypothesis class.\vspace{6pt}


\begin{itemize}
    \item[{\em (i)}] $\hypclass=\SAE$. Here, we just set $\bVE_j:=\bV_j^\top$, $\bVD_j=\bV_j$, $\biasE_j=-\bV_j^\top\bias_j,$ and $\biasD_j=\bias_j$. Then, we optimize $\{(\bVE_j,\bVD_j,\biasE_j,\biasD_j\}_j$ freely, as no constraints are involved.\vspace{6pt}

    \item[{\em (ii)}] $\hypclass=\SBAE$. In this case, one must first translate everything according to the parametrization discussed in Section~\ref{subsec:training}, which serves to reframe the training procedure as an unconstrained optimization problem. To this end, we set
    $$\tilde{\mathbf{X}}_j:=[\mathbf{V}_j,\mathbf{M}_j],\quad\tilde{\mathbf{Y}}_j=\tilde{\mathbf{Z}}_j=\mathbf{I}_{n_j},\quad\mathbf{Q}_j=\mathbf{0},\quad\mathbf{s}_j=[1,\dots,1]^\top,$$
    where $\mathbf{I}_{n_j}$ is the $n_j\times n_j$ identity matrix, whereas $\mathbf{M}_j$ is any $n_{j-1}\times d_j$ orthonormal matrix whose span is orthogonal to $\text{span}(\mathbf{V}_j)$. In practice, following the notation in Algorithm~\ref{alg:eys}, this can be constructed by extracting part of the remaning columns in the matrix $\mathbf{W}$, namely, $\mathbf{M}_j=\mathbf{W}_j[:,n_j+1:n_j+d_j]$.

    It is straightforward to prove that with such construction, if we let $$\boldsymbol{\theta}_{\textsf{EYS}}:=\{(\tilde{\mathbf{X}}_j,\tilde{\mathbf{Y}}_j,\tilde{\mathbf{Z}}_j,\mathbf{Q}_j,\mathbf{s}_j,\bias_j)\}_{j=1}^l$$
    then $\autoencoder_{\boldsymbol{\theta}_{\textsf{EYS}}}=\autoencoder_{\textsf{EYS}}$, meaning that the proposed parameter vector is consistent with the proposed initialization. Consequently, the training phase can now be carried out in the optimization space starting from $\boldsymbol{\theta}=\boldsymbol{\theta}_{\textsf{EYS}}$.
    \vspace{6pt}

    \item[{\em (iii)}] $\hypclass=\SOAE$. Here, as in the previous case, one needs to find a suitable $\boldsymbol{\theta}_{\textsf{EYS}}\in\Theta$ in the optimization space that realizes $\autoencoder_{\textsf{EYS}}$ --- this time according to the notation for SOAE architectures: see Section~\ref{subsec:training}. Here, however, this is much easier to do as one can simply set $\boldsymbol{\theta}_{\textsf{EYS}}:=\{(\bV_j,\bias_j)\}_{j=1}^{l}$.\vspace{6pt}
\end{itemize}

