\section{Technical proofs} 
\label{appendix:proofs}

\begin{proof}[\unskip\nopunct Proof of Theorem~\ref{theorem:pod}]
Recall that for a generic random vector $\mathbf{z}\in\mathbb{R}^{m}$ one has
$$\mathbb{E}\|\mathbf{z}-\mathbf{d}\|^2\ge \mathbb{E}\|\mathbf{z}-\mathbb{E}[\mathbf{z}]\|^2=\text{Tr}(\cmatrix[\mathbf{z}]),$$
for all deterministic vectors $\mathbf{d}\in\mathbb{R}^m$. Then, it is straightforward to prove that $\bq_*=\mathbb{E}[\bu]$ provides an optimal shifting. Indeed, for all  $\bV\in\mathcal{O}_{\ndim, n}$ and all $\bq\in\mathbb{R}^{n_0}$ one has
$$\mathbb{E}\|\bu-\left[\bV\bV^\top(\bu-\bq)+\bq\right]\|^2=\mathbb{E}\|(\mathbf{I}-\bV\bV^\top)\bu - (\mathbf{I}-\bV\bV^\top)\bq\|^2.$$
Since $\mathbb{E}\left[(\mathbf{I}-\bV\bV^\top)\bu\right]=(\mathbf{I}-\bV\bV^\top)\mathbb{E}\left[\bu\right]$, up to setting $\mathbf{z}:=(\mathbf{I}-\bV\bV^\top)\bu$, it is evident that $\bq_*=\mathbb{E}[\bu]$ is optimal, regardless of the matrix $\bV.$
%
Next, we notice that $\tilde{\bu}:=\bu-\mathbb{E}[\bu]$ and $\bu$ share the same covariance matrix, $\cmatrix[\tilde{\bu}]=\cmatrix[\bu].$ Therefore, without loss of generality, we shall continue the proof assuming that $\mathbb{E}[\bu]\equiv0$. 

Let now $T_\bu=\sum_{i=1}^{r}s_i\bv_i\langle\xi_i,\cdot\rangle_{L^{2}(\mathscr{P})}$ be the SVD decomposition of $T_\bu$, given as Theorem~\ref{theorem:EYS}.
%
Notice that, up to considering $\cmatrix[\bu]$ as an operator from $\mathbb{R}^{\ndim}\to\mathbb{R}^{\ndim}$, one has
$\cmatrix[\bu]=T_\bu T_\bu^*.$ In fact, for all $\mathbf{a},\mathbf{b}\in\mathbb{R}^{\ndim}$,
\begin{multline*}
\mathbf{a}^\top T_\bu T_\bu^*\mathbf{b}=\mathbf{a}^\top \mathbb{E}[\bu T_\bu^*\mathbf{b}]=\mathbb{E}[\mathbf{a}^\top\bu T_\bu^*\mathbf{b}]=\langle\mathbf{a}^\top\bu,T_\bu^*\mathbf{b}\rangle_{L^2(\mathscr{P})}=\\=\langle T_\bu\mathbf{a}^\top\bu,\mathbf{b}\rangle_{\mathbb{R}^{\ndim}}=\mathbb{E}[\bu\mathbf{a}^\top\bu]^\top\mathbf{b}=\mathbb{E}[(\bu^\top\mathbf{a})(\bu^\top\mathbf{b})]=
\mathbf{a}^\top\cmatrix[\bu]\mathbf{b}.\end{multline*}
It follows that, up to multiplicities, $s_i^2=\lambda_i(\cmatrix[\bu])$ and $\mathbf{X}=[\bv_1^*,\dots,\bv_r^*]$, as the eigenvalues and eigenvectors of $\cmatrix[\bu]$ are nothing but the squared singular values and left singular vectors of $T_\bu$.

As a next step, given any $\bV\in\mathscr{O}_{\ndim,n}$, let  $P_{\bV}:\mathbb{R}^{\ndim}\to\mathbb{R}^{\ndim}$ be the projector acting as $P_{\bV}:\boldsymbol{y}\mapsto\bV\bV^\top\boldsymbol{y}.$ Notice that, by linearity,
$T_{P_{\bV}\bu}=P_{\bV}T_\bu.$
In particular, $\rank(T_{P_{\bV}})\le n$, and, by Proposition~\ref{prop:isometry} and Theorem~\ref{theorem:EYS},
$$\mathbb{E}\|\bu-\bV\bV^\top\bu\|^2=\|T_\bu-T_{P_\bV\bu}\|_{\textnormal{HS}}^2\ge\sum_{i=n+1}^r\lambda_i(\cmatrix[u]).$$
At the same time, if $\bV=\bV_*$, we get
$
T_{P_{\bV_*\bu}}=P_{\bV_*}T_\bu = P_{\bV_*}\sum_{i=1}^{r}s_i\bv_i\langle\xi_i,\cdot\rangle_{L^2(\mathscr{P})}=\\=\sum_{i=1}^{r}s_iP_{\bV_*}\bv_i\langle\xi_i,\cdot\rangle_{L^2(\mathscr{P})}=\sum_{i=1}^{n}s_i\bv_i\langle\xi_i,\cdot\rangle_{L^2(\mathscr{P})},$
i.e.: $T_{P_{\bV_*\bu}}$ is %nothing but 
the $n$-rank truncated SVD of $T_\bu$. 
Thus,
$$
    %\tag*{\qedhere}
    \mathbb{E}\|\bu-\bV_*\bV_*^\top\bu\|^2 = \|T_\bu-T_{P_{\bV_*}\bu}\|_{\textnormal{HS}}^2=\sum_{i=n+1}^r\lambda_i(\cmatrix[u]).
$$
\end{proof}

