\begin{proof}[\unskip\nopunct Proof of Proposition~\ref{prop:classes}]\;

    \begin{itemize}[before=\vspace{5pt}, itemsep=6pt, leftmargin=16pt]
        \item [{\em (i)}] Let $\autoencoder=\{(\bVE_j,\bVD_j,\bias_j, \act)\}_{j=1}^{n_l}\in\SBAE$. Notice that for each $j=1,\dots,n_l$ one has $e_j\circ d_j=\textsf{Id}_{n_j}.$
        %results in the $\mathbb{R}^{n_j}\to\mathbb{R}^{n_j}$ identity. 
        In fact, given any $\mathbf{h}\in\mathbb{R}^{n_j}$,
        $$e_j(d_j(\mathbf{h}))=\act(\bVE_j((\bVD_j\invact(\mathbf{h})+\bias)-\bias))=\act(\bVE_j\bVD_j\invact(\mathbf{h}))=\act(\invact(\mathbf{h}))=\mathbf{h},$$
        due biorthogonality. Using associativity, it is follows that $\mathscr{E}(\autoencoder,\mathscr{D}(\autoencoder,\mathbf{c}))=(e_l\circ\dots\circ e_1\circ d_1\circ\dots\circ d_l)(\mathbf{c})=\mathbf{c}$ for all $\mathbf{c}\in\mathbb{R}^{n_l}$.

        \item[{\em (ii)}] This is a direct consequence of (i), as it can be obtained by setting $\mathbf{c}=\mathscr{E}(\autoencoder,\mathbf{v})$ and applying $\mathscr{D}(\autoencoder, \cdot)$ to both sides of the identity.

        \item [{\em (iii)}] Let $\autoencoder=\{(\bV_j,\bias_j, \act)\}_{j=1}^{n_l}\in\SOAE$. Notice that, for every $j=1,\dots,n_l$,  the maps $\mathbf{c}\mapsto\bV_j\mathbf{c}+\bias_j$ and $\mathbf{h}\mapsto\bV_j^\top(\mathbf{h}-\bias_j)$ are both affine and 1-Lipschitz. By composition, it follows that $\lip{e_j}\le \lip{\act}$ and $\lip{d_j}\le\lip{\invact}$. Since $\lip{\mathscr{E}(\autoencoder,\cdot)}\le\prod_{j=1}^{n_l}\lip{e_j}$ and $\lip{\mathscr{D}(\autoencoder,\cdot)}\le\prod_{j=1}^{n_l}\lip{d_j}$, the conclusion follows.
    \end{itemize}
\end{proof}


