\section{Complements on the He initialization}
\label{appendix:init}
Hereby, we derive an extension of the so-called \emph{He initialization} by generalizing the construction proposed in \cite{he2015delvingdeeprectifierssurpassing} to more complex bilipschitz activations. To this end, let $f$ be a bilipischitz function with $f(0) = 0$ and
\begin{equation}
    \label{eq:derivative at 0}
    \limsup_{z\mapsto0^{-}}f'(z)\le 1 \le \liminf_{z\mapsto0^{+}}f'(z).
\end{equation}
The generic forward pass of a layer mapping $\mathbb{R}^r\to\mathbb{R}^q$ reads $\bx = \bW f(\bz) + \bb$, with $\bx, \bb \in \mathbb{R}^q$, $\bW \in \mathbb{R}^{q \times r}$ and $\bz \in \mathbb{R}^r$. 
Following \cite{he2015delvingdeeprectifierssurpassing}, we shall set $\mathbf{b}\equiv\mathbf{0}$ and assume that
\begin{itemize}[itemsep=2pt,leftmargin=20pt,after=\vspace{6pt}]
    \item[\emph{(i)}] $\bz = [z_1,\dots,z_r]^\top$ is a random vector with i.i.d. components $z_j \overset{\text{i.i.d.}}{\sim} \omega$;
    \item[\emph{(ii)}] $\omega$ is symmetric and has finite second moment;
    \item[\emph{(iii)}] $\bW = (w_{ij})_{i,j}$ is drawn at random according to $w_{ij} \overset{\text{i.i.d.}}{\sim} \mathcal{N}(0,\sigma^2)$. 
\end{itemize}
The idea is to pick $\sigma$ such that the variance of $\mathbf{z}$ transfers to $\mathbf{x}$ in a controlled manner. In this respect, we notice that if $\mathbf{x}=[x_1,\dots,x_q]^\top$ then, for all $i=1,\dots,q$,
\begin{equation}
    \label{eq: var xi}
    \Var(x_i) = \Var\bigg(\sum_{j=1}^r w_{ij}f(z_j)\bigg) = \sum_{j=1}^{r}\Var(w_{ij}f(z_j)) = n\sigma^2\mathbb{E}|f(z_1)|^2,
\end{equation}
due independence and identical distribution. Indeed, 
\begin{multline*}
\Var(w_{ij}f(z_j)) =\mathbb{E}[w_{ij}^2f(z_j)^2]-\mathbb{E}[w_{ij}f(z_j)]^2=\\=\mathbb{E}|w_{ij}|^2\mathbb{E}|f(z_j)|^2-\mathbb{E}[w_{ij}]^2\mathbb{E}[f(z_j)]^2=\sigma^2\mathbb{E}|f(z_j)|^2,
\end{multline*}since $\mathbb{E}[w_{i,j}]=0$. Thus, we are left to study
\begin{equation*}
    \mathbb{E}|f(z_1)|^2 = \int_{-\infty}^0 |f(z)|^2\omega(z)dz +\int_0^{+\infty} |f(z)|^2\omega(z)dz,  
\end{equation*}
which can be bounded from above and below, using the stability properties of $f$. Specifically, using \eqref{eq:derivative at 0} and the fact that $f(0)=0$, it is straightforward to see that $\lip{f^{-1}}^{-1}|z|\le|f(z)|\le |z|$ for all $z<0$ and $|z|\le|f(z)|\le \lip{f}|z|$ for all $z>0.$ Thus,
\begin{align*}
    \small
    \frac{1}{2}\Var(z_1)\lip{f^{-1}}^{-2} &\le \int_{-\infty}^0 |f(z)|^2\omega(z)dz \le \frac{1}{2}\Var(z_1)\le\\&\small\le \int^{+\infty}_0 |f(z)|^2\omega(z)dz \le \frac{1}{2}\Var(z_1) \lip{f}^{2}. 
\end{align*}
Combining the above with \eqref{eq: var xi} yields
\begin{equation}
    \label{eq:sigma-bounds}
    \frac{n\sigma^2}{2}\Var(z_1)[\lip{f^{-1}}^{-2} +1] \le \Var(x_i) \le \frac{n\sigma^2}{2}\Var(z_1) [\lip{f}^{2} + 1]. 
\end{equation}
In the wake of \cite{he2015delvingdeeprectifierssurpassing}, we select $\sigma$ such that $\Var(x_i)\approx\Var(z_1)$. Heuristically, we achieve so by taking the harmonic mean between the lower and upper bound values of $\sigma$ derived from \eqref{eq:sigma-bounds}, which results in $\sigma = 4[n(2 + \lip{f^{-1}}^{-2} + \lip{f}^2)]^{-1}$. 

Note that, in the case of the LeakyReLU, this choice coincides exactly with the initialization proposed in \cite{he2015delvingdeeprectifierssurpassing}.\\\\

