\subsubsection{Finding a Relevant Direction}

First, we show that if there exists a sufficiently accurate approximation of our function within $V$, then a piecewise constant approximation over a sufficiently fine partition of $V$ yields comparable error.
\begin{lemma}[Piecewise constant approximation suffices]
\label{lem:piecewise-constant-suffices}
Let $\eps,L,M,\tau\in \R_+$, $k,d\in \Z_+$ with $\tau\leq M$
 and $c>0$ be a sufficiently small absolute constant.
Let $f:\R^d\to \R$ be an almost everywhere continuously differentiable function such that $\E_{\bx \sim \cN_d}[\norm{\nabla f(\bx)}^2]\leq L$ and $\E_{\bx \sim \cN_d}[f^2(\x)]\leq M$.
Moreover, assume that there exists a $B>0$ and $f_B:\R^d\to [-B,B]$ such that $\E[(f(\x)-f_B(\x))^2]\leq 
c\eps^2/M$.
Let $V$ be a $k$-dimensional subspace of $\R^d$ and let $\mathcal{S}$ be an $\eta$-approximating partition of $V$ with $\eta\leq c\eps^2/(MBLk)$.
If there exists a function $g:V \to \R$ such that $\E_{\bx \sim \cN_d}[(f(\bx)-g(\bx_V))^2]<\tau$, then we have that $\E_{\bx \sim \cN_d}[(f(\bx)-h_{\mathcal{S}}(\bx))^2]<\tau+\eps$, where $h_{\mathcal{S}}$ denotes any piecewise constant approximation of $f$.
\end{lemma}
\begin{proof}
Note that for any function $g:V\to \R$ the following holds 
\begin{align*}
    \E_{\bx \sim \cN_d}[(f(\bx)-\E_{\bz \sim \cN_d}[f(\bz)\mid \bz_V=\bx_V])^2]\leq \E_{\bx \sim \cN_d}[(f(\bx)-g(\bx_V))^2]\;.
\end{align*}
Therefore, we have that the function $s(\bx_V)\eqdef \E_{\bz \sim \cN_d}[f(\bz)\mid \bz_V=\bx_V]$ achieves squared error at most $\tau$.
Note that since $\x_V$ and $\x_{ V^\perp}$ are independent for $\x\sim \cN_d$,
we have that 
\[s(\bx_V)=\E_{\bz \sim \cN_d}[f(\bz)\mid \bz_V=\bx_V]=\E_{\bx_{ V^\perp}}[f(\bx_V+\bx_{ V^\perp})]\;.\]
Hence from the linearity of the derivative operator and Jensen's inequality we have that 
\(
\|\nabla s(\bx_V)\|^2 \leq \E_{\bx_{ V^\perp}}\Big[\left\|\nabla_{\x_V} f(\bx_V+\bx_{ V^\perp})\right\|^2 \Big]
\). Consequently
\[
\E_{\bx_V}\Big[\|\nabla s(\bx_V)\|^2\Big] \leq \E_{\bx\sim \cN_{d}}\Big[\left\|\nabla_{\x_V} f(\bx_V+\bx_{ V^\perp})\right\|^2 \Big] \leq \E_{\bx\sim \cN_{d}}\Big[\|\nabla f(\bx)\|^2\Big] \leq L.
\]

Moreover by Jensen's inequality we have that 
\begin{align*}
    \E_{\bx \sim \cN_d}[(s(\bx_V)- \E_{\x_{V^{\perp}}}[f_B(\x_V+\x_{V^{\perp}})])^2]&=
        \E_{\bx \sim \cN_d}[( \E_{\x_{V^{\perp}}}[f(\x_V+\x_{V^{\perp}}) -f_B(\x_V+\x_{V^{\perp}})])^2]\\
&\leq         \E_{\bx \sim \cN_d}[( f(\x) -f_B(\x))^2]\leq\rho\;.
\end{align*}
Therefore, $s$ is close to a bounded function.
Let $h$ be an approximation to $s$
that 
achieves squared error $\alpha$.
We have that the function $h(\x)\Ind(\x\in A^c)$
achieves squared error $2B^2\eps+2\rho+\alpha$
,where $A$ is any region of $\R^d$ with mass less than $\eps$.

As a result we can apply 
\Cref{fact:piecewiseconstantfromboundedgradientnorm}
for the function $s$
have that the piecewise constant function 
$h_{\mathcal{S}}(\bx_V){\eqdef} \E[ s(\bx_V) {\mid} \bx \in S]{=}\E[f(\bx){\mid} \bx\in S]$ for all $\bx \in S$ and $S\in \mathcal{S}$
and $h_{\mathcal{S}}(\bx_V)=0$ otherwise 
achieves error $\E_{\x\sim \cN_d}[( s(\bx_V)- h_{\mathcal{S}}(\bx_V))^2]\leq 4\rho+\eta+2\eta B^2$. 



Finally, we have that $\E_{\x\sim \cN_d}[(f(\x)-h_{\mathcal{S}}(\x))^2]=\tau+\eps$, which concludes the proof of \Cref{lem:piecewise-constant-suffices}. 
\end{proof}
Moreover, under the conditions defined in \Cref{def:agnosticMIMs},
we show that there exists a non-negligible fraction of finite-width
cubes over $\bx_V$ and intervals over $y$ where distinguishing moments
can be observed. Furthermore, we demonstrate that if a direction of the
target model is learned to  accuracy $\epsilon$, then there exists an 
observable moment that depends only on the remaining directions.

Intuitively, the proof proceeds as follows.  Since $f$ is a well-behaved MIM, we can round $y$ to some small accuracy  while maintaining distinguishing moments.  This discretizes the label space into intervals, and so with non-trivial probability over~$\x_V$ there is a degree-$m$  moment that correlates with the rounded label.  Next, because $f$ has bounded variation, $f(\x)$ and $f(\x')$—where $\x'$ is obtained by averaging $\x_V$ within $\x$'s cube in~$\cS$—remain close in mean-squared error.  This insensitivity lets us discretize over $V$ as well. Finally, for any direction with small projection onto $W$, bounded variation and the well‐behaved MIM condition imply that averaging along that direction preserves the distinguishing moment, yielding a moment independent of these directions.
\begin{lemma}[Cube-interval Discretization Suffices]\label{lem:agnostic-partition}
There exists a sufficiently large constant $C>0$ such that the following holds.
Let $d,k,m\in \Z_+$, and $L,M,\zeta, \alpha, \tau, \sigma, \eps>0$ with $\zeta\leq M$. Let $f:\R^d\to \R$ be in $\mathcal{F}(m,\zeta+C\eps,\alpha,K,M,L,B,\eps^2/(CM),\tau,\sigma)$ and let $W$ be a $K$-dimensional subspace such that $f(\x)=f(\x_W)$. Let $D$ be a distribution over $\R^d\times \R$ such that $D_\x=\cN_d$ and $\E_{(\bx,y)\sim D}[(f(\bx)-y)^2]\leq \zeta$.
Let $V$ be a $k$-dimensional subspace, $k\geq 1$ and denote by $U=W_{V^{\perp}}$.
Let $(\cS,\cI)$ be an $(\eps_1,\eps_2,B)$-approximating discretization of $V\times \R$,
with $\eps_1\leq \eps^2/(2LM^2\sqrt{k})$ and $\eps_2\leq \eps^2/(CM)$.
Moreover, let $E\subseteq{V^{\perp}}$ be a subspace such that  $\|\bv_{W}\|\leq \eps/(CKLM)$ for every unit vector $\bv\in E$.

If $\E[(f(\bx)-g(\bx_V))^2]> \tau$ for all $g:V\to \R$, then there exists $\mathcal{T}\subseteq \mathcal{S}$ with $\sum_{S\in \mathcal{T}}\pr[S]\geq \alpha$ such that for all $S\in \mathcal{T}$ there exist  $I\in \mathcal{I}$ and zero mean variance one polynomial $p:U\to \R$ of degree at most $m$ such that the following hold:
\begin{enumerate}[leftmargin=*]
    \item[i)] $\E[p(\bx_U)\Ind(y\in I)\mid \bx_V\in S]\ge\poly(\sigma\eps/(MB3^m))$.
    \item[ii)]  $\nabla p(\bx_{U})\cdot \bv=0$ for all $\bv \in E$ and $\bx\in \R^d$.
\end{enumerate}

\end{lemma}
\begin{proof}[Proof of \Cref{lem:agnostic-partition}]
We prove the two items in order.
Specifically, we first show that there exists a sufficiently fine discretization $(\cS, \cI)$ of $V \times \R$ such that, for a fraction of cubes $S \in \cS$, there exists a degree-$m$ polynomial that correlates nontrivially with the boolean function $\Ind(y \in I)$ conditioned on $\x \in S$.
Then, we show that averaging each such polynomial over the subspace $E$ preserves its correlation on $S$ while forcing all directional derivatives along $E$ to vanish.

\paragraph{Existence of correlating polynomials}
Without loss of generality, 
we can 
let \(y\) be the random variable obtained by truncating the original random variable $y$ to $[-B,B]$ 
(meaning that we assign the value $B\sign(y)$ 
if $\abs{y}\geq B$) and rounding 
to the nearest multiple of \(\eps_2\).
Indeed, let $y_B\eqdef\sign(y)\min(\abs{y},B)$ be the truncation of the original random variable $y$, 
 by expanding the square and applying \CS
$\E[(f_B(\x)-y)^2]\leq \zeta+O(\eps)$.
Hence,  $\E[(f_B(\x)-y_B)^2]\leq \E[(f_B(\x)-y)^2]\leq \zeta+O(\eps)$, which by a similar argument implies that 
$\E[(f(\x)-y_B)^2]\leq \zeta+O(\eps)$.
Similarly, rounding $y_B$ to multiples of $\eps_2\leq \eps^2/(CM)$
also keeps the random variable $(\zeta+O(\eps))$-close to $f$ in squared error.
Therefore, for the new random variable $y$ it holds that 
$\E[(f(\bx)-y)^2]= \zeta +O(\eps)$.

For any $\bx\in \R^d$, denote by $\mathcal{S}_\bx$ the set $S\in \mathcal{S}$ such $\bx\in S$.
We define a random vector $\bx'$ such that $\bx'_{V^{\perp}} = \bx_{V^{\perp}}$ and $\bx'_V$ is the sampled from the standard Gaussian over $V$ conditioned on $\mathcal{S}_{\bx}$, i.e., $\mathcal{N}_d\mid \mathcal{S}_\bx$.
Note that \(\bx'\) also follows the standard normal distribution over \(\R^d\) because its \(V\)-component is resampled from \(\mathcal{N}_d\).
Define $y'$ such that for all $\bz\in \R^d$, the distribution of $y'$ given $\bx'=\bz$ is the same as the distribution of $y$ given $\bx=\bz$. 
Notice that $y'$ and $y$ have the same support, i.e., $y'$ is also a multiple of $\eps$.
Denote by $D'$ the joint distribution of $(\bx,y')$.

By applying \Cref{fact:subspaceApprox} we have that $\E[(f(\bx)-f(\bx'))^2]\le \eps^2/M$. Moreover, it holds that $\E[(f(\bx)-y')^2]=\E[(f(\bx')-y)^2]$. Therefore, by expanding the square  we obtain
\begin{align*}
\E[(f(\bx)-y')^2]&=
\E[(f^2(\x)-y)^2]-2\E[(f(\x)-y)(f(\x)-f(\x'))]+\E[(f(\x)-f(\x'))^2]\\ 
&=\zeta+O(\eps)\;,
\end{align*}
where in the last inequality we used Cauchy-Schwarz and the assumption that $\zeta\leq M$.
Consequently, by Condition (4) of \Cref{def:agnosticMIMs} we have that with probability $\alpha$ over $\z\sim \cN_d$ there exist a zero mean, variance one polynomial $p:U\to \R$ such that 
$\E_{y_0 \sim (D'_{y'} \mid \bx_V = \z_V)}\left[\E_{(\x,y')\sim D'}[p(\bx_U ){\mid} \bx_V=\z_V{,} y'=y_0]^2 \right]\geq \sigma$.



Fix a $\z$ such that the aforementioned statement is satisfied.
Note that $\E[y'^2]=O(M)$. 
Recall that by the Gaussian hypercontractivity inequality (\Cref{fact:fourthmoment}), we have that 
\(
\E[q^4(\mathbf{x})] \le 3^{2m},
\)
for any zero-mean, 
unit-variance polynomial \(q: \R^d \to \R\) of degree at most \(m\).
Let $\eta\in(0,1)$ be a parameter to be quantified later
and denote by $\mathcal{Y}_{\eta}$ the set of all $y_0$ in the support of $y'$ such that $\pr_{y' \sim (D'_{y'} \mid \bx_V = \z_V)}[y'=y_0]\leq \eta$.
For a label $a\in \mathcal{Y}_{\eta}$ we have that
\begin{align*}
&\E_{y_0 \sim (D'_{y'} \mid \bx_V = \z_V)}[\Ind(y_0=a)\E_{(\x,y')\sim D'}[p(\bx_U ){\mid} \bx_V=\z_V{,} y'=y_0]^2 ]\\
&\leq \E_{y_0 \sim (D'_{y'} \mid \bx_V = \z_V)}[\Ind(y_0=a)\E_{(\x,y')\sim D'}[p^2(\bx_U ){\mid} \bx_V=\z_V{,} y'=y_0] ]\\
&\leq \sqrt{\eta}\sqrt{\E_{\x\sim \cN_d}[p^2(\bx_U ){\mid} \bx_V=\z_V] ]}\\
&\leq \sqrt{\eta 3^{2m}}\;,
\end{align*}
where in the first inequality we used Jensen and in the second inequality \CS and in the last inequality the hypercontractivity bound along with the fact that $U\subseteq V^{\perp}$. 

Note that the number of different values 
in the support of $y'$ are at most $O(B/\eps_2)$.
As a result, we have that 
\begin{align*}
  &\E_{y_0 \sim (D'_{y'} \mid \bx_V = \z_V)}\left[\E_{\bx\sim \cN_d}[p(\bx_U ){\mid} \bx_V=\z_V{,} y'=y_0]^2 \right]\\
&\leq  \E_{y_0 \sim (D'_{y'} \mid \bx_V = \z_V)}\left[\Ind(y_0\not\in \mathcal{Y}_{\eta})\E_{(\x,y')\sim D'}[p(\bx_U ){\mid} \bx_V=\z_V{,} y'=y_0]^2\right] +O(B/\eps_2)\sqrt{\eta3^{2m}}\;.
\end{align*}
Setting the parameter 
$\eta=(\eps^2\sigma/(2BM3^{m}))^2$ 
results to $O(B/\eps_2)\sqrt{\eta3^{2m}}\leq \sigma/2$, and thus 
$\E_{y_0 \sim (D'_{y'} \mid \bx_V = \z_V)}\left[\Ind(y_0\not \in \mathcal{Y}_{\eta})\E_{(\x,y')\sim D'}[p(\bx_U ){\mid} \bx_V=\z_V{,} y'=y_0]^2\right]\geq \sigma/2$. 
Therefore, there exists a $y_0$ with  $\pr_{y' \sim (D'_{y'} \mid \bx_V = \z_V)}[y'=y_0]> \eta$ such that ${
\E_{(\x,y')\sim D'}[p(\bx_U ){\mid} \bx_V=\z_V{,} y'=y_0]\geq \sqrt{\sigma/2}}$.
Hence, for the aforementioned $y_0$ it holds that 
$\E_{(\x,y')\sim D'}[p(\bx_U ) \Ind(y'=y_0) {\mid} \bx_V=\z_V]\geq \poly(\sigma\eps/(BM3^m))$.




Finally, since $y'$ is independent of $\z_V$ when conditioned on its cube $S_{\z_V}$ we have that $\E_{(\bx,y')\sim D'}[p(\bx_U)\Ind(y'=y_0)\mid \bx_V\in S]\geq \poly(\sigma\eps/(BM3^m))$. 
Noticing that the moments with respect to $U$ on each $S \in \mathcal{S}$ are the same for $y$ and $y'$ we have that also $\E_{(\bx,y)\sim D}[p(\bx_U)\Ind(y=y_0)\mid \bx_V\in S]\geq \poly(\sigma\eps/(BM3^m))$.
Therefore we have that the first part of the statement follows as conditioning on the truncated and rounded label to equal $i\eps_2$ is the equivalent as conditioning on the intervals $[i\eps_2-\eps_2/2,i\eps_2+\eps_2/2]$ for $\abs{i}\leq B/\eps-1$ and $[-\infty,-B],[B,\infty]$.

Using a similar strategy, we show that there exists a polynomial satisfying the second part of the statement also.
\paragraph{Averaging over $E$}Define the parameter $\delta \eqdef {\eps}/{(CLKM)}$. Recall that for all unit vectors $\vec{v} \in E$, it holds that $|\vec{v}_W| \leq \delta$.
Let $\x'=\z_{E}+\x_{ E^\perp}$, where $\z\sim \cN_d$ independent of $\x$.

In the following claim we show that $f(\x)$ is very close to $f(\x')$, to do this we simply 
integrate  the change of $f$ across a path from $\x$ to $\x'$.
Since $f$ is a function of bounded variation and $\|\Pi_W(\x-\x')\|$ this change is small.
\begin{claim}\label{cl:nabla2smallchange}
It holds that $\E[(f(\x)-f(\x'))^2]\lesssim L(K\delta)^2$.
\end{claim}
\begin{proof}[Proof \Cref{cl:nabla2smallchange}]
Note that since we want to utilize the fact that  $\E[\|\nabla f(\x) \|^2]\leq L$ we want integrate at along a rotation from $\x$ to $\x'$ to preserve the all intermediate points in the path to be standard Gaussian.

For that purpose let
$\vec u(\theta)=(\x_E\cos(\theta)+\z_E\sin(\theta)) +\x_{E^{\perp}}$.
Note $\vec u(0)=\x$ and $\vec u(\pi/2)=\x'$.
Now by the Fundamental Theorem of Calculus
\begin{align*}
f(\x')-f(\x)&= \int_0^{\pi/2}  \nabla f(\vec u(\theta))\cdot \frac{d}{d\theta }\Pi_{W}\vec u(\theta)d\theta\\
&= \int_0^{\pi/2}  \nabla f(\vec u(\theta))\cdot\Pi_{W}(\z_E\cos(\theta)-\x_E\sin(\theta) ) d\theta\\
&\leq \int_0^{\pi/2} \|\nabla f(\vec u(\theta))\|\|\Pi_{W}(\z_E\cos(\theta)-\x_E\sin(\theta) )\| d\theta\;,
\end{align*}
where in the last inequality we used \CS. Hence,
\begin{align*}
(f(\x')-f(\x))^2&\leq \left(\int_0^{\pi/2} \|\nabla f(\vec u(\theta))\|\|\Pi_{W}(\z_E\cos(\theta)-\x_E\sin(\theta) )\| d\theta\right)^2\\
&=(\pi/2)^2\left(\int_0^{\pi/2} (2/\pi) \|\nabla f(\vec u(\theta))\|\|\Pi_{W}(\z_E\cos(\theta)-\x_E\sin(\theta) )\| d\theta\right)^2\\
&\leq (\pi/2)\int_0^{\pi/2}  \|\nabla f(\vec u(\theta))\|^2\|\Pi_{W}(\z_E\cos(\theta)-\x_E\sin(\theta) )\|^2 d\theta\;,
\end{align*}
where in the last inequality we used Jensen.
Taking the expectation and noticing that $\vec u(\theta)$ and $\z_E\cos(\theta)-\x_E\sin(\theta)$ are independent (since they are jointly normally distributed and uncorrelated), we get
\begin{align*}
    \E[(f(\x')-f(\x))^2]&\lesssim \int_0^{\pi/2} \E[ \|\nabla f(\vec u(\theta))\|^2\|\Pi_{W}(\z_E\cos(\theta)-\x_E\sin(\theta) )\|^2]\\
    &\leq \int_0^{\pi/2} \E[ \|\nabla f(\vec u(\theta))\|^2]\E[\|\Pi_{W}(\z_E\cos(\theta)-\x_E\sin(\theta) )\|^2]\\
    &\lesssim L \E_{\x\sim \cN_d}[\|\Pi_W\Pi_E\x\|^2]\;,
\end{align*}
Noticing that $\E_{\x\sim \cN_d}[\|\Pi_W\Pi_E\x\|^2]=
\|\Pi_W\Pi_E\|_F^2\leq (\mathrm{rank}(\Pi_W\Pi_E)\|\Pi_W\Pi_E\|_{2})^2\leq (K\delta)^2$ completes the proof of \Cref{cl:nabla2smallchange}.
\end{proof}
Hence, by \Cref{cl:nabla2smallchange}, we have that $\E[(f(\x)-f(\x'))^2]\lesssim (\eps/(CM))^2$.
Consider the random variable $y'$ supported on $\R$ that is distributed like $y$ for $\x'$, i.e., $D(y'=p\mid \x'=\z)=D(y=p\mid \x=\z)$, for all $\z\in \R^d,p\in\R$.

Note that $\E[(f(\x) - y')^2] = \E[(f(\x') - y)^2]$, which, similarly to before, can be shown—by expanding the square and applying Cauchy–Schwarz—to be less than $\zeta + \eps$ for a sufficiently large constant $C$.
As a result, we have that by applying part (i) of the statement to $y'$ there exists $\mathcal{T}\subseteq \mathcal{S}$ with $\sum_{S\in \mathcal{T}} \pr[S]\ge\alpha$ such that for each $S\in \mathcal{T}$ there exists a zero-mean, variance-one polynomial $p:U\to \R$ of degree at most $m$ along with an interval $I\in\mathcal{I}$ such that $\E_{\x,y'}[p(\x_U)\Ind(y'\in I)\mid \x \in S]>\sigma $, where $U=(V+W)\cap V^\perp$. However, we have that for all $S\in \mathcal{T}$ 
\begin{align*}
\E_{\x,y'}[p(\x_U)\Ind(y'\in I)\mid \x \in S]= \E[\E_{\x_{E} }[p(\x_U)\mid \x_{ E^\perp}]\E_{\x_{E}}[\Ind(y\in I)\mid \x_{ E^\perp}] \mid \x \in S]]\;. 
\end{align*}
Notice that $p'(\x_U)\eqdef \E_{\x_{E} }[p(\x_U)\mid \x_{ E^{\perp}}]$ is a mean-zero polynomial of degree at most $m$ with variance at most one by Jensen's inequality. 
Furthermore, as $p'$ is independent of $\x_{E}$ we have that $\nabla p'(\x_U)\cdot\bv=0$ for any $\bv\in E$ and $\x\in \R^d$.
\end{proof}

Before proceeding with the proof of \Cref{thm:MetaTheorem-Agnostic}, we establish the following proposition, which states that in each iteration, as long as the current subspace $V$ yields an insufficient approximation of the labels, it is possible to extract a direction that is correlated with the remaining subspace.

\begin{proposition}[Finding a Relevant Direction]\label{prop:MetaAlg2}
Let $d,k,m,K\in \Z_+$, $\delta,\alpha\in (0,1)$, $\eta,\eps,M,L>0$
and let $C>0$ be a sufficiently large universal constant.
Let $f:\R^d\to \R$ be a function from the class $\mathcal{F}(m,\zeta,\alpha,K,M,L,B,\eps^2/(CM),\tau,\sigma)$ and denote by $W\subseteq \R^d$ with $\dim(W)=K$ the hidden subspace of $f$.
Let  $D$ be a distribution over $\R^d\times \R$ whose $\x$-marginal is $\cN_d$ and let $\opt \eqdef \E_{(\x,y)\sim D}[(f(\x)-y)^2]$ with $\zeta\ge \opt +O(\eps)$.
Let $V\subseteq \R^d$ be a $k$-dimensional subspace and let $(\mathcal{S},\mathcal{I})$ be an $(\eps_1,\eps_2,B)$-approximating discretization of $V\times\R$,
with $\eps_1\leq \eps^2/(CLM^2\sqrt{k})$ and $\eps_2\leq \eps^2/(CM)$.
Additionally, let $h_{\mathcal{S}}$ be a piecewise constant approximation of $D$, with respect to $\mathcal{S}$. There exists $N=(dm)^{O(m)}(k/\eps_1)^{O(k)}\log(B/(\delta\eps_2))/\eta^{O(1)}$ such that, if  $\E_{(\bx,y)\sim D}[(h_{\mathcal{S}}(\bx)- y)^2]>(\sqrt{\tau+\eps}+\sqrt{\opt})^2$, then \Cref{alg:MetaAlg2} {given $N$} i.i.d.\ samples from $D$ and parameters 
$\eta\leq (\sigma\eps/(MB2^m))^C,\eps_1,\eps_2, \lambda=(\alpha\sigma\eps/(MBK2^m))^C$, runs in $\poly(N)$ time, and with probability at least $1-\delta$, returns a list of unit vectors $\mathcal E$ of size $|\mathcal E|=\poly(2^mKMB/(\alpha\sigma\eps\eps_2))$, such that: For some $\bv\in \mathcal E$ and unit vector $\bw\in W$ it holds that
    $
        \bw_{V^{\perp}} \cdot \bv\ge \poly(\eps\sigma\eps_2\alpha/(KLMB2^m))\;.
    $
\end{proposition}

\begin{proof}[Proof of \Cref{prop:MetaAlg2}]
Let $\vec{w}^{(1)}, \dots, \vec{w}^{(K)}$ be an orthonormal basis for the subspace $W$. For each pair $S \in \mathcal{S}$ and $I \in \mathcal{I}$, let $p_{S,I}$ denote the regression polynomial of degree at most $m$ computed at Line~\ref{line:regression} of \Cref{alg:MetaAlg2}. Further, let $\widehat{\vec{U}}$ be the matrix computed at Line~\ref{line:matrixMeta} of \Cref{alg:MetaAlg2}, and let $\eta^2$ denote the $L_2^2$ error chosen in the polynomial regression step (see Line~\ref{line:regression} of \Cref{alg:MetaAlg2}).


We begin by proving the following general lemma, which states that if a fraction of the discretization cubes exhibit non-trivial moments, then—with a sufficiently large number of samples—the output set $\mathcal{E}$ will be non-empty and will contain only a small number of vectors.
\begin{lemma}[Existence of Correlating Vectors]\label{lem:cEnonempty}
Let $(\mathcal{S},\mathcal{I})$ be an $(\eps_1,\eps_2,B)$-approximating discretization of $V\times\R$.
    Assume that there exists a subset $\mathcal{T}\subseteq \mathcal{S}$ with $\sum_{S\in \mathcal{T}}\pr[S]\ge \alpha$, such that for each $S\in \mathcal{T}$ there exists an interval $I\in \mathcal{I}$ and a zero-mean, variance-one  polynomial $q_S:U\to \R$ of degree at most $m$  such that $\E_{(\bx,y)\sim D}[q_S(\bx_U)\Ind(y\in I)\mid \bx \in S]>\sigma\geq 2\eta $ for some subspace $U$ of $V^{\perp}$.
    Furthermore, assume that the eigenvalue threshold $\lambda=(\alpha\sigma/K)^C$, for some sufficiently large universal constant $C>0$.
    Then, there exists $N=(dm)^{O(m)}{(k/\eps_1)^{O(k)}}\log(\abs{\cI}/\delta)/{\eta^{O(1)}} $ such that with probability at least $1-\delta$ the output set $\mathcal{E}$  has cardinality at most $|\mathcal E|=\poly(mK/(\alpha\sigma\abs{\cI}))$ and contains at least one vector $\vec v\in \mathcal{E}$ such that $\vec u\cdot \vec v\geq \poly(\alpha\sigma\abs{\cI}/(mK)$ for some $\vec u\in U$.
\end{lemma}
\begin{proof}[Proof of \Cref{lem:cEnonempty}]
    Let $\bu^{(1)}, \dots, \bu^{(k')}$ denote an orthonormal basis of the subspace $U$. We prove the lemma in two stages. First, we analyze each cube $S$ that exhibits non-trivial moments by evaluating the quadratic forms of its influence matrix
$
\bM_{S,I} \eqdef \E_{\bx \sim D_{\bx}} \left[ \nabla p_{S,I}(\bx_{V^{\perp}}) \nabla p_{S,I}(\bx_{V^{\perp}})^\top \mid \bx \in S \right] $
    on the vectors $\bu^{(i)}$. 
    Then, we extend the analysis by averaging over all such cubes and examining the eigenvectors of the aggregated influence matrix, $\widehat{\vec U}$.

In the following claim, we leverage the existence of non-trivial  moments over $U$ for the regions  $S\in \mathcal{T}$, to show that if the sample size is sufficiently large then for each region $S\in \mathcal{T}$, there exists an interval $I\in \mathcal{I}$, such that the associated influence matrix, $\bM_{S,I}$,  has large quadratic form  for at least one of the  $\bu^{(i)}$'s.

\begin{claim}[Quadratic form of the Influence Matrix]
\label{it:corr-vec-existance} 
Let $C>0$ be  a sufficiently large universal constant.
Fix, $S\in \mathcal{T}$. 
If the number of samples that fall in $S$ is $N_S\ge (dm)^{Cm}\log(1/(\delta\eps_2))/\eta^{C}$,  then with probability at least $1-\delta$ there exists $i\in [k'] $ and $ I\in \mathcal{I}$ such that 
$(\bu^{(i)})^{\top}\bM_{S,I}\bu^{(i)}\ge \sigma^2/(2K)\;.$
\end{claim} 
\begin{proof}[Proof of \Cref{it:corr-vec-existance}]
Notice that membership of a point $\x$ in a cube $S$ depends solely on its projection onto $V$, i.e., on $\x_V$. Therefore, the error guarantee obtained in the polynomial regression step  $\E_{(\bx, y)\sim D}[(\Ind(y\in I) -p_{S,I}(\bx_{V^{\perp}}))^2{\mid} \bx \in S]{\le} \min_{p'\in \mathcal{P}_m} \E_{(\bx, y)\sim D}[(\Ind(y\in I) -p'(\bx_{V^{\perp}}))^2{\mid} \bx \in S]+\eta^2$ is equivalent to  
$\E_{(\bx, y)\sim D^S_{V^{\perp}}}[(\Ind(y\in I) -p_{S,I}(\bx))^2]{\le} \min_{p'\in \mathcal{P}_m} \E_{(\bx, y)\sim D^S_{V^{\perp}}}[(\Ind(y\in I) -p'(\bx))^2 ]+\eta^2$, where $D_{V^\perp}^S$ is  the marginal obtained by averaging $D$ over $V$ conditioned on  $S$, i.e., $D^S_{V^{\perp}}(\x_{V^{\perp}},y)=\E_{\x_V}[D(\x,y)\mid \x \in S]$.

Moreover, by the properties of the Gaussian distribution, we have that the $\x$-marginal of $D^S_{V^\perp}$ is a standard Gaussian.
Therefore, since $\abs{\mathcal{I}}=\poly(1/\eps_2)$ if $N_S\ge (dm)^{Cm}\log(1/(\delta\eps_2))/\eta^{C}$ for a sufficiently large universal constant $C>0$, then by applying the union bound and \Cref{fact:regressionAlg}, we have that with probability at least $1-\delta$:
\[\E_{(\x, y)\sim D^S_{V^{\perp}}}[(\Ind(y\in I) -p_{S,I}(\x))^2]\le \min_{p'\in \mathcal{P}_m} \E_{(\x, y)\sim D^S_{V^{\perp}}}[(\Ind(y\in I) -p'(\x))^2 ]+\eta^2\;,\]
for all $I\in \mathcal{I}$.
Furthermore, by the orthogonality of Hermite polynomials, we have that 
\begin{align*}
  &\E_{(\x, y)\sim D^S_{V^{\perp}}}[(\Ind(y\in I) -p_{S,I}(\x))^2]\\
  &=\sum_{\beta \subseteq \N^d} ( \E_{(\x,y)\sim D^S_{V^{\perp}}}[H_{\beta}( \x)\Ind(y\in I)] - \E_{(\x,y)\sim D^S_{V^{\perp}}}[H_{\beta}( \x)p_{S,I}(\x)])^2\;.
\end{align*} 
In particular, if we decompose the error into its Hermite polynomial components of degree $t$, we have that $\sum_{t=1}^m\E_{(\x, y)\sim D^S_{V^{\perp}}}[(\Ind(y\in I)^{[t]} -p_{S,I}^{[t]}(\x))^2]  \le \eta^2$.


{From the rotational invariance of the Gaussian without loss of generality,  we can denote by $\e_1,\dots,\e_{k'}$ the orthonormal vectors $\bu^{(1)},\dots,\bu^{(k')}$.}
Furthermore, since $U$ is a subset of $V^\perp$ we similarly have that  $\E_{(\bx,y)\sim D^S_{V^{\perp}}}[q_S(\bx_U)\Ind(y\in I)]>\sigma$ for some $I\in\mathcal{I}$.
Decomposing $q_S(\bx_{U})$ to the basis of Hermite polynomials we have that $q_S(\bx_{U})= \sum_{\beta \in \N^{d'}, 1\le \norm{\beta}_1\le m}\hat{q}_S(\beta)H_\beta(\bx_U)$ where $d'=\dim(U)$.
Moreover, note that since $q_S$ has no component outside $\e_1,\dots, \e_{k'}$ we have that $q_S(\bx_{U})=\sum_{\beta \in J}\hat{q}_S(\beta)H_\beta(\bx_U)$, where $J$ denotes the set of $\beta \in \N^{d'}$ such that $\beta_i\ge 1$ for some $i\in [k']$.
Considering the correlation of $q_S$ with the label interval $I$, we have that 
\begin{align*}
    \E_{(\bx,y)\sim D^S_{V^{\perp}}}[q_S(\bx_U)\Ind(y\in I)]&= \sum_{\beta\in J}\hat{q}_S(\beta)\E_{(\bx,y)\sim D^S_{V^{\perp}}}[H_\beta(\bx_U)\Ind(y\in I)]\\&\le \left(\sum_{\beta\in J}\E_{(\bx,y)\sim D^S_{V^{\perp}}}[H_\beta(\bx_U)\Ind(y\in I)]^2\right)^{1/2}\;,
\end{align*}
where we used the fact that $\|q_S\|_2=1$ and the Cauchy-Schwarz inequality. Hence, we have that the sum of the squares of the Hermite coefficients for of the degree $m$ restriction the random variable $\Ind(y\in I)$ is at least $\sigma^2$. 



Now evaluating the quadratic form of {$\bM_{S,I}$}  using \Cref{fact:gradientNorm} gives us
\begin{align*}
\sum_{i=1}^{k'}\e_i^\top{\bM_{S,I}} \e_i&= \sum_{i=1}^{k'}\E_{(\bx,y)\sim D^S_{V^{\perp}}}[(\nabla p_{S,z}(\bx)\cdot\e_i )^2]\ge \sum_{\beta \in \N^d} (\sum_{i=1}^{k'} \beta_i) (\hat{p}_{S,z}(\beta))^2\\
&\ge \sum_{\beta \in J} \E_{(\bx,y)\sim D^S_{V^{\perp}}}[H_\beta(\bx_U)\Ind(y\in I)]^2- 2\eta  \\
&\ge \sigma^2- 2\eta \ge \sigma^2/2
\end{align*}
for $\eta\le \sigma/2$. Thus, since $\dim(U)\le K$ we have that $\e_j^{\top} {\bM_{S,I}}\e_j\ge \sigma^2/(2K)$ for some $j \in [k']$. This concludes the proof of \Cref{it:corr-vec-existance}.
\end{proof}

Now note that by the definition of an approximating partition (see \Cref{def:approximatingPartition}) and \Cref{fact:gaussianfacts}, for all $S\in \mathcal{S}$ we have that   $\pr_{D}[S ]{= (\eps_1/k)^{\Omega(k)}}$, hence $\abs{\mathcal{S}}{= ( k/\eps_1)^{O(k)}}$.
Therefore, by union bound and Hoeffding's inequality, it holds that if $N\ge {(k/\eps_1)^{Ck}}\log(\abs{\mathcal{S}}/\delta)= {(k/\eps_1)^{O(k)}}\log(1/\delta) $ for a sufficiently large constant $C>0$, then with probability at least $1-\delta$  we have that  $\abs{\pr_{\widehat{D}}[S]-\pr_{D}[S]}\le \pr_{D}[S]/2$ for all $S\in \mathcal{S}$.
Hence, it is  true that  $\pr_{\widehat{D}}[S]\ge \pr_{D}[S]/2$, i.e., the number of samples that fall in each set $S\in \mathcal{S}$ is at least $N\pr_{D}[S]/2= N{(\eps_1/k)^{\Omega(k)}}$.  


Therefore, for $N\geq (dm)^{Cm}{(k/\eps_1)^{Ck}}\log(\abs{\cI}/\delta)/{\eta^{C}}$ for a sufficiently large universal constant $C>0$, by applying \Cref{it:corr-vec-existance}, we have that  for all $S\in \mathcal{T}$ it holds that ${(\bu^{(i)})^{\top}\bM_{S,I}\bu^{(i)}\ge \sigma^2/(2K)}$ for some {$i\in [k'], I\in\mathcal{I}$}.
Hence, {since $k'\le K$,} we have that there exists a subset $\mathcal{T}'\subseteq \mathcal{T}$ and $i\in [k']$ with $\sum_{S\in \mathcal{T'}}\pr_{\widehat{D}}[S]\ge \sum_{S\in \mathcal{T'}}\pr_{D}[S]/2= \Omega(\alpha/K)$ such that for all $S\in \mathcal{T'}$ we have that  {${(\bu^{(i)})^{\top}\bM_{S,I}\bu^{(i)}\ge \sigma^2/(2K)}$ for some $I \in \mathcal{I}$}.

Thus, for some $i \in [K]$ we have that 
\[(\bu^{(i)})^{\top}\widehat{\bU}\bu^{(i)} \gtrsim \frac{\alpha}{K}{\sigma^2/(2K)}\ge{\poly(\alpha\sigma/K)}\;,\]
where we used the fact that $\widehat{\bU}$ is PSD.







{Moreover, note that from \Cref{fact:regressionSubspaceBound} we have that $\tr(\bM_{S,I})=O(m)$. Therefore, we have that $\norm{\bM_{S,I}}_{F}\le \E[\norm{\nabla p_{S,i}}^2 ]=\tr(\bM_{S,I})$. As a result, by the triangle inequality we can see that 
\[\norm{\widehat{\bU}}_{F}\le \sum_{ S\in \mathcal{S},I\in\mathcal{I}}\norm{\bM_{S,I}}_F\pr_{\widehat{D}}[S] \le O(m)\sum_{ S\in \mathcal{S},I\in\mathcal{I}}\pr_{\widehat{D}}[S]\le m\abs{\mathcal{I}} \;.\]
} 

Hence, by \Cref{cl:coorelationofeigenvalues}, 
we have that there exists a unit eigenvector $\bv$ of $\widehat{\bU}$ with eigenvalue at least ${\poly(\alpha\sigma/K)}$ for a sufficiently small polynomial, such that  
$\bu^{(i)}\cdot \bv\ge {\poly(\alpha\sigma/(mK\abs{\cI})}$
for some $i\in [K]$. 
Moreover, the number of such eigenvectors, $\abs{\mathcal{E}}$, is at most {$\poly(mK\abs{\cI}/(\alpha\sigma))$}. Which concludes the proof of \Cref{lem:cEnonempty}.
\end{proof}

We now leverage the assumption that $h_{\mathcal{S}}$ exhibits large error,
along with the previously established lemmata, to complete the proof.

Define the subspace 
$E\eqdef \mathrm{span}(\{\bv\in \mathcal{E}:\norm{\bv_{W}}\le \rho/\sqrt{\abs{\mathcal{E}}}\})$, where $\rho\eqdef \eps^2/(CKLM)$.
Notice that $\norm{\bv_{W}}\le \rho$ holds for every unit vector $\bv\in E$.
Also denote by $U\eqdef W_{V^{\perp}}$.

Since $\E_{(\bx,y)\sim D}[(h_{\mathcal{S}}(\bx)-y)^2]>(\sqrt{\tau+\eps}+\sqrt{\opt})^2$ and $f$ is assumed to be in the class 
$\mathcal{F}(m,\opt +\eps,\alpha,K,M,L,B,\eps^2/(CM),\tau,\sigma)$ we 
have that \Cref{lem:piecewise-constant-suffices,lem:agnostic-partition} 
together imply that 
there exists a subset $\mathcal{T}\subseteq \mathcal{S}$ with
$\sum_{S\in \mathcal{T}}\pr[S]\ge \alpha$, such that for each
$S\in \mathcal{T}$ there exists an interval $I\in \mathcal{I}$
and a zero-mean, variance-one  polynomial $q_S:U\to \R$ of degree
at most $m$  such that 
$\E_{(\bx,y)\sim D}[q_S(\bx_U)\Ind(y\in I)\mid \bx \in S]>t$ for some $t=\poly(\sigma\eps/(MB2^m))$ and $\nabla_{E} q_S(\bx_{U})=0$.



Denote by $\bu^{(1)},\dots,\bu^{(k')}$ an orthonormal basis of the space   $U$ projected onto $E^{\perp}$. We have that $k'\ge 1$, otherwise we would not have the existence of $q_S$ that is defined over this space. 

Finally, note that for $C$ a sufficiently large constant $\eta \leq t/2$ 
and also $\lambda=(t\alpha/K)^C$.
Therefore, since  $N=(dm)^{O(m)}(k/\eps_1)^{O(k)}\log(B/(\delta\eps_2))/\eta^{O(1)}$ applying \Cref{lem:cEnonempty} for the space $U$ projected onto $E^{\perp}$, we have that $|\mathcal E|=\poly(2^mKMB/(\alpha\sigma\eps\eps_2))$ and 
there exists at least one vector $\vec v\in \mathcal{E}$ such that $\bu^{(i)}\cdot \vec v\neq 0$
for some $i\in [K]$.
However, note that since $\bu^{(i)}\cdot \bv\neq 0$, we have that $\bv$ can not belong in  $E$. Thus there exists a unit vector $\bw\in W$ such that $\abs{\bv\cdot \bw}\ge \rho/\sqrt{\mathcal{E}}\ge  \poly(\eps\sigma\eps_2\alpha/(KLMB2^m))$
which completes the proof of \Cref{prop:MetaAlg2}.
\end{proof}




\subsubsection{Proof of \Cref{thm:MetaTheorem-Agnostic}} \label{sec:meta-thm-proof}
In this section, given \Cref{prop:MetaAlg2}, we proceed to the proof of  \Cref{thm:MetaTheorem-Agnostic}. {Recall that, in \Cref{prop:MetaAlg2}, we have shown that if our current approximation to the hidden subspace is not accurate enough to produce a function that has sufficiently small error, then \Cref{alg:MetaAlg2} efficiently finds a direction that has non-trivial correlation to the hidden subspace. In the proof that follows, we iteratively apply this argument to show that, after a moderate number of iterations, \Cref{alg:MetaAlg1} outputs a function with sufficiently small error. }
\begin{proof}[Proof of \Cref{thm:MetaTheorem-Agnostic}]
Denote by $W^*$ the $K$-dimensional subspace defining $f$. 
We show that \Cref{alg:MetaAlg1}, with high probability, returns a hypothesis $h$ with $L_2^2$ error at most $(\sqrt{\tau+\eps}+\sqrt{\opt})^2+\eps$. Denote by $\bw^{*(1)},\ldots,\bw^{*(K)} \in \mathbb{R}^d$ an orthonormal basis of $W^*$.
Let $L_t$ be the list of vectors updated by the algorithm (Line \ref{line:updateMeta} of \Cref{alg:MetaAlg1}) and $V_t=\mathrm{span}(L_t)$, $\dim(V_t)=k_t$.
Also,  let $\mathcal{S}_t$ for $t\in [T]$ be arbitrary $\eps_1$-approximating partitions of $V_t$ where $\eps_1$ the value set at Line \ref{line:initMeta}.
Let $h_t:\mathbb{R}^d\to [K]$ be a piecewise constant functions, defined as $h_t= h_{\mathcal{S}_{t}}$ according to \Cref{def:h} for the distribution $D$.

To prove the correctness of \Cref{alg:MetaAlg1}, we need to show that if $h_t$ has significant error, then the algorithm improves its approximation $V_t$ to $W^*$.
For quantifying the improvement at every step, we consider the following potential function
$
\Phi_t = \sum_{i=1}^{K}\norm{\bw^{*(i)}_{ V_t^\perp}}^2\;.
$

We will use the following fact that quantifies how much adding a correlating direction decreases $\Phi_t$.
\begin{fact}
    [Potential Decrease, e.g., see Claim 2.16 \cite{diakonikolas2025robustlearningmultiindexmodels} ]\label{it:potentialDecrease}Let $\beta \ge 0$. If there exists a unit vectors $\bv^{(t)}\in   V_{t+1}$ and $\bw\in W^*$ such that
    $\bw\cdot \bv^{(t)}_{ V_t^\perp}\ge   \beta\;,$ 
    then $\Phi_{t+1}\le \Phi_t-\beta^2$.
\end{fact}
We next prove the following claim which shows that the error of the functions $h_t$ decreases as we add more vectors.
\begin{claim}[Error Decrease]\label{it:ErrorDecrease} For each $t\in[T]$, it holds  $\E[(h_{t+1}(\bx) - y)^2]\le  \E[(h_{t}(\bx)- y)^2]$. 
\end{claim}
\begin{proof}
{Since the statement of \Cref{prop:MetaAlg2} holds for any $\eps_1$-partitions $\mathcal{S}_t$, $t\in [T]$, independent of the choice of basis and threshold points,}
{we can assume that all the approximations $h_t$} are computed with respect to extensions of a common orthonormal basis and that all threshold points are aligned.
Hence, $\mathcal{S}_{t+1}$ is a subdivision of $\mathcal{S}_t$.
Thus, each set $S\in \mathcal{S}_t$ can be written as a union of sets $S_1,\dots,S_l\in \mathcal{S}_{t+1}$, i.e., $S=\cup_{i=1}^l S_i$. 

By definition, for any set $S\in \mathcal{S}_t$ we have 
\(
h_t(\bx)= \E_{(\bx,y)\sim D}[y\mid \bx\in S] \quad \text{for } \bx\in S,
\)
and similarly, for any $S_i\in \mathcal{S}_{t+1}$,
\(
h_{t+1}(\bx)= \E_{(\bx,y)\sim D}[y\mid \bx\in S_i] \quad \text{for } \bx\in S_i.
\)
Thus, for any $S\in \mathcal{S}_t$,
\begin{align*}
\E_{(\bx,y)\sim D}[(h_{t+1}(\bx)-y)^2,\,\bx\in S] 
&=\sum_{i=1}^l \Pr[S_i]\,\E_{(\bx,y)\sim D}[(h_{t+1}(\bx)-y)^2 \mid \bx\in S_i]\\[1mm]
&=\sum_{i=1}^l \Pr[S_i]\,\E_{(\bx,y)\sim D}\Bigl[\Bigl(\E_{(\bx,y)\sim D}[y\mid \bx\in S_i]-y\Bigr)^2 \,\Big|\, \bx\in S_i\Bigr]\\
&\leq \sum_{i=1}^l \Pr[S_i]\,\E_{(\bx,y)\sim D}\Bigl[\Bigl(\E_{(\bx,y)\sim D}[y\mid \bx\in S]-y\Bigr)^2 \,\Big|\, \bx\in S_i\Bigr]\\
&=\E_{(\bx,y)\sim D}[(h_{t}(\bx)-y)^2,\,\bx\in S]\;,
\end{align*}
where we used the fact that $\E_{x\sim P}[(x-\E[x])^2]\leq \E_{x\sim P}[(x-z)^2]$ for any $z\in \R$ and distribution $P$ supported on $\R$.
Summing over all $S\in \mathcal{S}_t$, completes the proof of \Cref{it:ErrorDecrease}.
\end{proof}

Finally, we prove the following claim which 
shows that the population piecewise constant 
functions are close to the corresponding 
empirical ones.
\begin{claim}[Concentration of Piecewise Constant Approximation]\label{cl:hConcetration}
Let $\eps, \eps', \delta\in (0,1)$ and $k,K\in \Z_+$ with $\eps' \le \eps/2$. Let $V\subseteq \R^d$ be a $k$-dimensional subspace, and consider a piecewise constant {approximation}  $h:\R^d\to [K]$ {of $D$,}
with respect to an $\eps'$-approximating 
partition of $V$. Let $\widehat{D}$ be the empirical distribution obtained from $N$ i.i.d.\ samples drawn from $D$, and let $\widehat{h}$ be a piecewise constant {approximation of $\widehat{D}$} defined with respect to the same partition.
If $\widehat{h}$ is computed using the median of means estimator (\Cref{fact:medianofmeans}) 
for each $S\in \mathcal{S}$,
then there exists $N= (k/\eps')^{O(k)}(M/\eps)^{O(1)}\log(1/\delta)$ 
such that, with probability at least $1-\delta$, we have
$\E[(\widehat{h}(\bx)- y)^2]\le \E[(h(\bx)- y)^2]+\eps \;.$
\end{claim}

\begin{proof}
Denote  by $\mathcal{S}$ the approximating partition for the functions $h,\widehat{h}$. 
First, note that by the definition of an approximating partition (\Cref{def:approximatingPartition}) and  by \Cref{fact:gaussianfacts}, we have that $\pr_{D}[S ]= (\eps'/k)^{\Omega(k)}$ and hence $\abs{\mathcal{S}}= (k/\eps')^{O(k)}$. 

Fix $S\in \mathcal{S}$. Note that since $\pr_D[S]$ is lower bounded we have that the second moment of $y$ conditioned on $S$ can not be arbitrarily large. Specifically,  $\E[y^2\mid \bx\in S]=\E[y^2\Ind(\bx\in S)]/\pr_{D}[S]= M(k/\eps')^{O(k)}$.
 Therefore, for any $S\in \mathcal{S}$ by applying \Cref{fact:medianofmeans} we have that, if the number of samples that fall in $S$ is $N_{S}=C(k/\eps')^{Ck} M^2/\eps^2\log(1/\delta)$ for a sufficiently large constant $C>0$, then with probability $1-\delta$ it holds $\abs{\widehat{h}(\bx)-\E[y\mid \bx \in S]}\leq \eps$ for all $\bx\in S$. Noting that by definition $h(\bx)=\E[y\mid \bx \in S]$ for all $\bx\in S$, we have that $\abs{\widehat{h}(\bx)-h(\bx)}\leq \eps$ for all $\bx\in S$.

Hence, by union bound and Hoeffding's inequality, if $N\ge {(k/\eps')^{Ck}}\log(\abs{\mathcal{S}}/\delta)= {(k/\eps')^{O(k)}}\log(1/\delta) $ for a sufficiently large constant $C$, then with probability $1-\delta$  we have that  $\abs{\pr_{\widehat{D}}[S]-\pr_{D}[S]}\le \pr_{D}[S]/2$ for all $S\in \mathcal{S}$.
Hence, it is  true that  $\pr_{\widehat{D}}[S]\ge \pr_{D}[S]/2$, i.e., the number of samples that fall in each set $S\in \mathcal{S}$ is at least $N\pr_{D}[S]/2= N{(\eps'/k)^{\Omega(k)}}$.  Therefore, if $N\geq C(k/\eps')^{Ck} M^2/\eps^2\log(1/\delta)$ for a sufficiently large constant $C$, then with probability at least $1-\delta$ for all $S\in \mathcal{S}$ it holds that $\abs{\widehat{h}(\bx)-h(\bx)}\leq \eps$ for all $\bx\in \R^d$.

As a result, by  Cauchy-Schwarz  $\E[(\widehat{h}(\bx)- y)^2]\leq \E[(h(\bx)- y)^2] +\eps^2+\eps \sqrt{\E[(h(\bx)- y)^2]}$.
Moreover,   by Jensen's inequality $\E[y^2],\E[h^2(\bx)]\leq M$, hence  $\sqrt{\E[(h(\bx)- y)^2]}\leq \sqrt{2M}$. Therefore, if $N\geq C(k/\eps')^{Ck} M^3/\eps^2\log(1/\delta)$, with probability at least $1-\delta$ it holds that  $\E[(\widehat{h}(\bx)- y)^2]\leq \E[(h(\bx)- y)^2] +\eps $.   Which completes the proof of \Cref{cl:hConcetration}.
\end{proof}


Note that from Lines \ref{line:initMeta} and \ref{line:loopMeta} of \Cref{alg:MetaAlg1}, we perform at most $\poly(BKLM2^m/(\eps\alpha\sigma))$ iterations. Furthermore, in each iteration, we update the vector set with at most  $\poly(BKM2^m/(\eps\alpha\sigma))$ vectors. 
Hence, it follows that $k_t\le \poly(BKLM2^m/(\eps\alpha\sigma))$, for all $t=1,\dots, T$.

 Assume that $\E_{(\bx, y)\sim D}[(h_t(\bx)- y)^2]>(\sqrt{\tau+\eps}+\sqrt{\opt})^2$ for all $t=1,\dots, T$.  
 Using the fact that $N=d^{Cm}2^{(BKLM2^m/(\eps\alpha\sigma))^C}\log(1/\delta)$ for a sufficiently large universal constant $C>0$ (Line \ref{line:initMetaParams} of \Cref{alg:MetaAlg1}), we can apply \Cref{prop:MetaAlg2} and conclude that, with probability $1-\delta$, there exists unit vectors $\bv^{(t)}\in  V_{t+1}$ and unit vectors $\w^{(t)}\in W^*$ for $ t=[T]$ such that 
 $\bw^{(t)}\cdot \bv^{(t)}_{ V_t^{\perp}}\ge \poly(\eps\sigma\alpha/(BMKL2^m))$.
 Thus, by \Cref{it:potentialDecrease}, we have that with probability $1-\delta$, for all $t\in [T]$,  $\Phi_t\le \Phi_{t-1}- \poly(\eps\sigma\alpha/(BMKL2^m))$. 
 After $T$ iterations, it follows that $\Phi_T\le \Phi_{0}- T\poly(\eps\sigma\alpha/(BMKL2^m))=
 K-T\poly(\eps\sigma\alpha/(BMKL2^m))$.
 However, since $T$ is set to be a sufficiently large polynomial of $2^m,B,M,L,K,1/\eps, 1/\alpha$, and $1/\sigma$ we would arrive at a contradiction, since $\Phi_T\ge 0$.
 Hence, we have that $\E_{(\bx, y)\sim D}[(h_t(\bx)- y)^2]\leq (\sqrt{\tau+\eps}+\sqrt{\opt})^2$, for some $t\in \{1,\dots, T\}$. 
 Since the error of $h_t$ can only be decreasing by \Cref{it:ErrorDecrease} and  $h_t$ is close to its sample variant by \Cref{cl:hConcetration}, we have that $\E_{(\bx, y)\sim D}[(h(\bx)- y)^2]\le (\sqrt{\tau+\eps}+\sqrt{\opt})^2+\eps$.


\item \textbf{Sample and Computational Complexity:} From the analysis above we have that the algorithm terminates in $\poly(BKLM2^m/(\eps\alpha\sigma))$ iterations and at each iteration we draw of the order of $d^{O(m)}2^{\poly(BKLM2^m/(\eps\alpha\sigma))}\log(1/\delta)$ samples. 
Hence, we have that the total number of samples is  $d^{O(m)}2^{\poly(BKLM2^m/(\eps\alpha\sigma))}\log(1/\delta)$. 
Moreover, we use at most $\poly(N)$ time as all operations can be implemented in polynomial time.
\end{proof}



\begin{remark} \label{rem:sc-alg}
{\em While our algorithm is sufficient to obtain 
a polynomial dependence on $d$ for any constant values 
of $m$ and the other parameters, 
it is worth looking closer at the exponent of this polynomial. 
The algorithm that we have presented 
requires $d^m$ samples in order to accurately estimate 
the degree-$m$ parts of the relevant indicator functions 
in Line \ref{line:regression} of \Cref{alg:MetaAlg2}. Observe that there is a quadratic 
gap between this bound and our SQ lower bound. Recall that
our SQ lower bound requires either exponentially many queries 
or a query of accuracy 
$d^{-m/4}$, which in turn requires
roughly $d^{m/2}$ samples to simulate.

We believe that this gap can be closed 
with a slightly different algorithm. 
In particular, instead of finding the polynomial approximation $p_{S,I}$ for each $S$ and $I$ in our discretizing 
approximation, and combining them into a matrix $\vec U$ to find directions that are often influential, 
we instead merely sample $(S,I)$ pairs 
and find the influential directions for each sampled pair (and note that with high probability we should find one which correlates with $W$). Then instead of estimating $p_{S,I}$ 
in $L_2$-norm (which requires roughly $d^m$ samples), 
we can treat it as an $m$-tensor $\vec T$, which in turn 
we flatten into a 
$d^{\lfloor m/2 \rfloor)} \times d^{\lceil m/2 \rceil}$ 
matrix $\vec M$. Since by assumption $\vec T$ has a large component 
in the $W$-directions, $\vec M$ must have some singular vectors 
with relatively large singular values 
that themselves correspond to polynomials in which the $W$-directions are influential.
We can again find these if we estimate a suitable approximation to $\vec M$, 
but importantly for our purposes, 
we only need to estimate $\vec M$ to small error in operator norm rather than small error in Frobenius norm. 
This allows the algorithm to succeed with only around 
$d^{\lceil m/2 \rceil}$ samples.}
\end{remark}





\subsection{Learning Real-Valued MIMs: Realizable and Random Label Noise} \label{sec:low-dim-y}

In this section, we demonstrate that our algorithmic approach becomes more 
efficient when the label \( y \) depends only on the projection of $\x$ to a low-dimensional subspace.

Specifically, we assume that there exists 
a $K$-dimensional subspace \( W \) such that \( y \) depends on \( \x \) only through its projection onto \( W \); that is,
\(
\pr[y = z \mid \x = \vec u] = \Pr[y = z \mid \x_W = \vec u_W]
\)
for all \( \vec u\in \R^d,z\in \R \). 
This is a setting that captures both the realizable and the independent noise settings.
We refer to this as the \emph{MIM distribution} setting, indicating that the random variable \( y \) is a MIM, i.e.,  it depends only on a low-dimensional subspace.

This structural assumption implies that all non-zero moments of 
the joint distribution are entirely within \( W \). 
Consequently, our algorithm achieves a constant correlation gain 
in each iteration (unlike the agnostic setting analyzed in 
\Cref{prop:MetaAlg2}), resulting in only \( O(K) \) iterations 
overall.
This leads to significant improvements in 
sample and computational complexities.

We begin by formally defining the class of distributions for which our algorithm guarantees a satisfactory solution. In \Cref{sec:applications}, we will demonstrate that for several MIM function classes, their distribution of examples belongs to this class. 
\begin{definition}[Well-Behaved MIM Distributions]\label{def:well-behaved-realizable}
Fix $d, K, m\in \Z_+$, $\alpha\in (0,1)$ and  $M,\tau,\sigma,\eps_1,\eps_2>0$. 
We say that a distribution $D$ over $\R^d\times \R$ whose marginal is $\cN_d$ is a 
$(m,\alpha,K,M,\tau,\sigma,\eps_1,\eps_2)$-well-behaved MIM distribution, if the following conditions hold:
\begin{enumerate}[leftmargin=*]
    \item There exists a subspace $W\subseteq\R^d$ of dimension at most $K$ such that $y$ depends on $\x$ only through the projection onto $W$, i.e., \(\pr_{(\x,y)\sim D}[y = z \mid \x = \vec u] = \Pr_{(\x,y)\sim D}[y = z \mid \x_W = \vec u_W]\), for all \( \vec u\in \R^d,z\in \R \). 
    \item The label has bounded variance, i.e.,  $\E_{(\bx,y)\sim D}[y^2]\leq M$.
    \item For any subspace \(V\subseteq \R^d\) with $\dim(V)\leq K$ and for any \((\eta_1,\eta_2)\)-approximating discretization \((\mathcal{S},\cI)\) with $\eta_1 \leq \eps_1$, $\eta_2 \leq \eps_2$
\begin{enumerate}[leftmargin=*]
    \item either $\E_{(\bx,y)\sim D}[(h_{\mathcal{S}}(\bx_{V})- y )^2]\le \tau$, where $h_{\mathcal{S}}$ denotes the piecewise constant approximation of $D$ according to \Cref{def:h}.

  \item  or there is a subset $\mathcal{T}\subseteq \mathcal{S}$ such that $\sum_{S\in \mathcal{T}}\pr[S]\geq \alpha$ and
 for $U=W_{V^\perp}$, there exists a polynomial $p:U\to \R$ of degree at most $m$ and an interval $I\in \mathcal{I}$  such that $\E_{(\bx,y)\sim D}[p(\bx_U)\Ind(y\in I)\mid \bx \in S]>\sigma \|p(\bx_U)\|_2 $ and $\E_{\bx}[p(\bx_{U})]=0$.
\end{enumerate}
\end{enumerate}

\end{definition}


\begin{algorithm}[h] 

    \centering
    \fbox{\parbox{5.45in}{
            { \textbf{Learn-MIM-Distributions}}: Learning Well-Behaved MIM distributions\\
            {\bf Input:}  Accuracy $\eps \in(0,1)$, failure probability $\delta\in(0,1)$,  sample access to a distribution $D$ over $\mathbb{R}^d\times \R$, and parameters $\theta=(m,\alpha,K,M,\tau,\sigma,\eps_1,\eps_2)$ for which $D$ is a $\theta$-well-behaved MIM distribution.\\
            {\bf Output:} A hypothesis $h$ such that, with probability at least $1-\delta$, $\E_{(\bx,y)\sim D}[(h(\bx)- y)^2]\leq \tau+\eps$.

            \smallskip

            \begin{enumerate}[leftmargin=*]
            \item Let $C$ be a sufficiently large universal constant.\label{line:initMeta-realizable}
             \item Let $L_1=\emptyset$,  $N\gets{(dm)}^{C m}(m K/(\eps_1\eps_2 \alpha ))^{CK}(M/(\eps\sigma))^{C}\log(1/\delta)$.\label{line:initMetaParams-realizable}
                \item For $t=1,\dots,T$
             \label{line:loopMeta-realizable}
             \begin{enumerate}
             \item  Draw a set $S_t$ of $N$ i.i.d.\ samples from $D$.
             \item  $\mathcal{E}_t\gets$ \Cref{alg:MetaAlg2}($(K \abs{\cI} /(\sigma\eps\alpha))^{C},\eps_1/K^4,\eps_2,1/\eps_2^2, (\sigma\alpha/K)^C, \spaning(L_t), S_t,\theta$).
            \item Construct $L_{t+1}$ by adding one vector of $\mathcal{E}_t$ to $L_t$.\label{line:updateMeta-realizable}
            \end{enumerate}
            \item Construct $\mathcal{S}$, an $\eps_1$-approximating partition with respect to $\spaning(L_t)$ (see \Cref{def:approximatingPartition}).
             \item Draw $N$ i.i.d.\ samples from $D$ and construct the piecewise constant function $h_{\mathcal{S}}$ as follows: For each $S \in \mathcal{S}$, assign the median of $O(\log(1/\delta))$ means of the labels from the samples falling in $S$.
   \item  Return $h_{\mathcal{S}}$.  
            \end{enumerate}
    }}
         \vspace{0.2cm}

  \caption{Learning Well-Behaved MIM distributions.}
  \label{alg:MetaAlgRealizable}
\end{algorithm}



    We now present the main theorem of this section, which shows that \Cref{alg:MetaAlg1} achieves improved complexity in this setting.

\begin{theorem}[Learning Well-Behaved MIM Distributions]\label{thm:MetaTheorem-realizable}
Let $D$ be a $(m,\alpha,K,M,\tau,\sigma,\eps_1,\eps_2)$-well-behaved MIM distribution supported on $ \mathbb{R}^d \times \R$. 
Then, \Cref{alg:MetaAlg1} draws $N ={(dm)}^{O(m)}2^{\poly(K)}(m/(\eps_1\eps_2 \alpha ))^{O(K)}(M/(\eps\sigma))^{O(1)}\log(1/\delta)
$ i.i.d.\ samples from $D$,
runs in time $\poly(N)$, and returns a  hypothesis $h$ such that, with probability at least $1 - \delta$, 
   $$\E_{(\bx,y)\sim D}[(h(\bx)-y)^2] \leq\tau+\eps\;.$$
\end{theorem}

We now prove the following proposition, which demonstrates that—compared to the agnostic setting (see \Cref{prop:MetaAlg2})—improved correlation can be achieved in the MIM distribution setting.
\begin{proposition}[Correctness of Learning Well-Behaved MIM Distributions]\label{prop:inprovedCorrelation}
There exists a sufficiently large universal constant $C>0$ such that the following holds.
Let $D$ be a $(m,\alpha,K,M,\tau,\sigma,\eps_1,\eps_2)$-well-behaved MIM 
distribution supported on $ \mathbb{R}^d \times \R$ 
and let $W\subseteq \R^d$ with $\dim(W)=K$ be the hidden subspace of $D$.
Let $V\subseteq \R^d$ be a $k$-dimensional subspace
 with $k\leq K$ such that $\norm{\vec v_{W^{\perp}}}\leq \eps'\leq \eps(\eps_1\eps_2\alpha\sigma/K)^C$, for all unit vectors $\vec v\in V$.
Also, let 
$(\mathcal{S},\mathcal{I})$ be an $(\eps_1/K^4,\eps_2)$-approximating dicretization of $V\times \R$.
Additionally, let $h_{\mathcal{S}}$ be a piecewise constant approximation of $D$, with respect to $\mathcal{S}$.
There exists  
$N=(dm)^{O(m)}(K/\eps_1)^{O(k)}\log(\abs{\cI}/\delta) /\eta^{O(1)}$ 
such that if $\E_{(\bx,y)\sim D}[(h_{\mathcal{S}}(\bx)- y)^2]>\tau +\eps$, 
then \Cref{alg:MetaAlg2}, when given $N$ i.i.d.\ samples 
from $D$ and parameters  $\eta\leq (\eps\sigma\eps_2\alpha/(mK))^C,\eps_1/K^4,\eps_2, \lambda= (\sigma\alpha/K)^C$, runs in time
$\poly(N)$ and, with probability at least $1-\delta$, 
returns a list of unit vectors $\mathcal E$ of size 
$|\mathcal E|=\poly(mK/(\eps_2\alpha\sigma))$, 
such that for every vector $\vec v\in \mathcal E$, 
there exists a unit vector $\w\in W$ with $\w \cdot \vec v\ge 1- \eps\;.$
\end{proposition}
\begin{proof}
Let $\widehat{\vec U}$ be the matrix computed in Line \ref{line:matrixMeta} of \Cref{alg:MetaAlg2} and let $\eta^2$  be the $L_2^2$ error chosen in the polynomial-regression step, i.e., Line \ref{line:regression} of \Cref{alg:MetaAlg2}.

In the next claim, we show that if the sample size 
for a cubic region $S\in \mathcal{S}$ is sufficiently large, 
then for every  $I\in \mathcal{I}$  the  influence matrix, $\bM_{S,I}\eqdef \E_{\bx\sim D_{\bx}}[\nabla p_{S,I}(\bx_{V^{\perp}}) \nabla p_{S,I}(\bx_{V^{\perp}})^\top\mid \bx \in S]$, 
(see Line \ref{line:matrixMeta} of \Cref{alg:MetaAlg2}) 
has small quadratic form when evaluated 
for any  unit vector in $W^{\perp}+V$.


\begin{lemma}[No Bad Vector]\label{cl:Nobadvector2}
Fix $S\in \mathcal{S}$. Suppose that the number of samples falling in $S$ is $N_S\ge(dm)^{Cm}\log(1/(\delta\eps_2))/\eta^{C}$ for a sufficiently large universal constant $C>0$. 
Then, for any   unit vector $\vec v\in  (V+W^{\perp} )\cap V^{\perp}$ we have that $ \vec v^{\top }\bM_{S,I}\vec v \lesssim {\sqrt{K} K^4\eps'}/{\eps_1}+m\eta^2 $.
\end{lemma}
\begin{proof}[Proof of \Cref{cl:Nobadvector2}]
Let $N_S, S\in \mathcal{S}$, be the number of samples that land in the set $S$.
First, observe that the guarantee obtained at the regression step 
\[\E_{(\x, y)\sim D}[(\Ind(y\in I) -p_{S,I}(\x_{V^{\perp}}))^2\mid \x\in S]\le \min_{p'\in \mathcal{P}_m} \E_{(\x, y)\sim D}[(\Ind(y\in I) -p'(\x_{V^{\perp}}))^2\mid \x\in S]+\eta^2\;\]
is equivalent to
\[\E_{(\x, y)\sim D^S_{V^{\perp}}}[(\Ind(y\in I) -p_{S,I}(\x))^2]\le \min_{p'\in \mathcal{P}_m} \E_{(\x, y)\sim D^S_{V^{\perp}}}[(\Ind(y\in I) -p'(\x))^2]+\eta^2\;,\] 
where $D^S_{V^\perp}$ is defined to be the marginal obtained by averaging $D$ over $V$ conditioned on  $S$, i.e., $D^S_{V^{\perp}}(\x_{V^{\perp}},y)=\E_{\x_V}[D(\x,y)\mid \x \in S]$.
Moreover, by the properties of the Gaussian distribution, we have that the $\x$-marginal of $D^S_{V^\perp}$ is a standard Gaussian.
Hence, by applying \Cref{fact:regressionAlg} and the union bound, we have that with $N_S=(dm)^{O(m)}\log(1/(\delta\eps_2))/\eta^{O(1)}$ i.i.d.\ samples and runtime $\poly(N_S,d)$, we can compute polynomials 
$p_{S,I}$ that satisfy the aforementioned condition with probability at least $1-\delta$.


For $\beta\in\N^d$, 
the Hermite coefficients of $p_{S,I}$ and $\Ind(y\in I)$ are defined 
by $\widehat{p}_{S,I}(\beta)\eqdef \E_{(\x,y)\sim D^S_{V^{\perp}}}[H_{\beta}( \x)p_{S,I}(\x)]$ and 
$ \widehat{g}_I(\beta)\eqdef \E_{(\x,y)\sim D^S_{V^{\perp}}}[H_{\beta}( \x)\Ind(y\in I)] $.
By the orthogonality of Hermite polynomials, we have 
\[\E_{(\x, y)\sim D^S_{V^{\perp}}}[(\Ind(y\in I) -p_{S,I}(\x))^2]=\sum_{\beta \in \N^d} (\widehat{p}_{S,I}(\beta)- \widehat{g}_I(\beta) )^2\;.\] 
Thus, restricting the sum to multi-indices $\beta$ with $1\le \|\beta\|_1\le m$, it follows that $\sum_{\beta\in \N^d,1\le \|\beta\|_1\le m }(\widehat{p}_{S,I}(\beta)- \widehat{g}_I(\beta))^2 \le \eta^2$.

Note that $\widehat{g}_I(\beta)= \E_{\z\sim \cN_d}[H_{\beta}( \z_{V^{\perp}} )\pr_{(\x,y)\sim D}[ y\in I\mid \x_V\in S,\z_{V^{\perp}}=\x_{V^{\perp} }]] $. For $z\in V^{\perp}$ define the function  $\widetilde{g}(\z)\eqdef\pr_{(\x,y)\sim D }[ y\in I\mid \x_V\in S,\z=\x_{V^{\perp} }]$. 

In the following claim, we show that the directional derivative of the function $\widetilde{g}$ in directions within $V + W^\perp$ is small. This implies that the quadratic form of $\vec M_{S,I}$ in these directions is also small, since $\widetilde{g}$ and $p_{S,I}$  match Hermite coefficients.


\begin{claim}[Directional‐derivative bound on the averaged indicator]\label{cl:der-bound}
Fix an interval $I\in \mathcal{I}$ and cube $S\in \cS$.
Let
$\vec u\in(V+W^\perp)\cap V^\perp$ be a  unit vector.
Then for all $\x\in V^{\perp}$ it holds that 
\begin{align*}
\left| \frac{d}{dt}\widetilde{g}(\x+t\vec u)\right|\leq \frac{K^5\eps'}{\eps_1}.    
\end{align*}
\end{claim}

\begin{proof}[Proof of \Cref{cl:der-bound}]
Define the function $g(\z)= \pr_{(\x,y)\sim D}[y\in I\mid \x=\z]$ and note that for all $\z\in \R^d$ it holds that 
$\widetilde{g}(\z_{V^{\perp}})=\E_{\x\sim \cN_d}[g(\x_V+\z_{V^\perp})\mid \x_V\in S,\x_{V^{\perp}}=\z_{V^{\perp}}]$.

Let $\vec u= \vec a+ \vec b$, where $\vec a\in V$ and $\vec b\in W^{\perp}$.
Since $\vec u\in V^{\perp}$, 
it holds that 
$\|\vec a\|^2+ \vec a\cdot \vec b= \vec u\cdot \vec a= 0$.
Note that by assumption $\norm{\vec a- \vec a_W}\leq \eps' \norm{\vec a}$, thus $\vec a=\vec a_W+ \eps' \norm{\vec a}\vec v$,  for some unit vector $\vec v\in \R^d$.
Hence, we have that $\|\vec a\|^2+ \vec a\cdot \vec b=\|\vec a\|^2+\eps' \norm{\vec a}(\vec v\cdot \vec b)$ which implies that $\norm{\vec a}\leq \eps'\norm{\vec b}$.
Therefore, by triangle inequality $\norm{\vec b}\leq\norm{\vec a}+1$ 
as a result $\norm{\vec a}=O(\eps')$.

Since $y$ depends on $\x$ only through the projection onto $W$, 
we have that $g(\x+t\vec u)= g(\x+t \vec a)$. 
Thus, shifting $\x$ by $t\vec u$ is equivalent 
to shifting by $t\vec a$.

Denote by $\y$ a standard normal random variable over $V$ and by $\x$ a standard normal random variable over $V^{\perp}$. From the fact that $g$ is invariant in changes in $W$ we have that
\begin{align*}
  \widetilde{g}(\x+t\vec u)=\frac{\E_{\vec y}[g(\x+\y+t\vec u)\Ind(\y\in S)]}{\pr[\y\in S]}&=\frac{\E_{\y}[g(\x+\y+t\vec a) \Ind(\y\in S)]}{\pr[\y\in S]}\;.
\end{align*}
Now define the new random variable $\z \eqdef \y+t\vec a$. By a change of variables we have that
\begin{align*}
 \widetilde{g}(\x+t\vec u) &=\frac{\E_{\z}[g(\x+\z) \Ind(\z-t\vec a\in S)]}{\pr[\y\in S]}
\end{align*}
Therefore, shifting the argument by $t\vec u$ 
results to shifting the box by $-t\vec a$.
Thus, in order to bound the derivative, 
it suffices to bound $\pr[S\Delta(S-t\vec a)]$, 
where $\Delta$ denotes the symmetric difference of the two sets.

Recall that the edge width of each cube is $\eps_1/K^4$, as defined in the statement of the proposition.
Denote by $\phi:V\to \R$ the density function of a standard Gaussian random variable in $V$ and by $\vec v^{(1)},\dots,\vec v^{(k)}$ the orthonormal basis of $V$ used to define $S$.
Note that from the anti-concentration of the Gaussian distribution, 
it suffices to bound the volume of the symmetric difference. 
To this end define the following sequence of sets $S=S_0,S_1,\dots,S_k=S-t\vec a$, where $S_i$ is equal to $S-t(\sum_{l=1}^{i}(\vec a\cdot \vec v^{(l)}) \vec v^{(l)})$.
By the triangle inequality and a simple volume calculation we have that
\begin{align*}
    \pr[S\Delta(S-t\vec a)]&=  \pr[\Ind(\x\in S)\neq \Ind(\x\in(S-t\vec a))] \\
    &\leq \sum_{i=1}^k \pr[\Ind(\x\in S_{i-1})\neq \Ind(\x\in S_{i})]\\
    &\leq (2/K^{4(k-1)})   \sum_{i\in [k]} \eps_1^{k-1}\abs{t(\vec a \cdot \vec v^{(i)})} \sup_{\x\in S\cup (S-t\vec a)}\phi(\x)\\&\leq (2/K^{4(k-1)}) \sqrt{k}\norm{t\vec a}\eps_1^{k-1} \sup_{\x\in S\cup (S-t\vec a)}\phi(\x)\;,
\end{align*}
where in the last inequality we used the \CS inequality.
Define the following ratio   
\begin{align*}
\rho_{S}(t)\eqdef \frac{\sup_{\x\in S\cup (S-t\vec a)}\phi(\x)}{\inf_{\x\in S}\phi(\x)}\;.
\end{align*}
Therefore, we have that 
\begin{align*}
    \abs{\widetilde{g}(\x+t\vec u)-\widetilde{g}(\x)}\leq \frac{\pr[S\Delta(S-t\vec a) ]}{\pr[\x\in S]}
    &\leq \frac{K^{4k}\inf_{\x\in S}\phi(\x)}{\eps_1^k}\pr[S\Delta(S-t\vec a) ]\\&
    \lesssim K^4\frac{\eps_1^{k-1}\sqrt{k}\norm{t\vec a}}{\eps_1^k}\rho_{S}(t)
    \\&\lesssim K^4\frac{\sqrt{k}\abs{t}\eps'}{\eps_1}\rho_{S}(t)\;,
\end{align*}
where in the second equation we used the fact that $\pr[\x\in S]\ge \inf_{\x\in S}\phi(\x)\eps_1/K^{4k}$ and in the third one we substituted our prederived upper bound for  $\pr[S\Delta(S-t\vec a)]$.
Finally, note that $\rho_S(t)=\exp((\x-\y)\cdot (\x+\y)/2)$ for some $\x\in S$ and $\y\in S\cup (S-t\vec a)$.
Hence,   $\lim_{t\to 0}\rho_{S}(t)\leq \exp(\eps_1 K^{-4}k^{3/2} \sqrt{\log(k^5/\eps_1)})$ which is bounded by a constant since $k\leq K$.
This concludes the proof of \Cref{cl:der-bound}.
\end{proof}


Let a unit vector $\vec u\in (V+W^\perp)\cap V^\perp$, from \Cref{cl:der-bound} we have that $\abs{\vec u\cdot \nabla\widetilde{g}(\x_{V^{\perp}})}\lesssim {K^5\eps'}/{\eps_1}$ for all $\x\in \R^d$.
From the rotational invariance of the standard gaussian, 
let us for simplicity denote $\vec u$ by $\e_1$.
By applying \Cref{fact:gradientNorm}, we have that  
\begin{align*}
 \sum_{\beta \in \N^d} \beta_1 \widehat{g}_I(\beta)^2\lesssim \frac{K^5\eps'}{\eps_1}\;.
\end{align*}
Consequently,
\begin{align*}
  \vec e_1^{\top}\E_{(\x,y)\sim D^S_{V^{\perp}}}[\nabla p_{S,I}(\x)\nabla p_{S,I}(\x)^{\top}]\vec e_1=  \sum_{\beta \in \N^d} \beta_1\widehat{p}_{S,I}(\beta)^2\lesssim \frac{K^5\eps'}{\eps_1}+m\eta^2\;.
\end{align*}
This completes the proof of~\Cref{cl:Nobadvector2}. 
\end{proof}

First note that by the definition of an approximating partition (\Cref{def:approximatingPartition}) and \Cref{fact:gaussianfacts}, for all $S\in \mathcal{S}$ we have that   $\pr_{D}[S ]= (\eps_1/(Kk))^{\Omega(k)}$ and $\abs{\mathcal{S}}= ( kK/\eps_1)^{O(k)}$.
Therefore, by the union bound and Hoeffding's inequality, it holds that if $N\ge (kK/\eps_1)^{Ck}\log(\abs{\mathcal{S}}/\delta)= (kK/\eps_1)^{O(k)}\log(1/\delta) $ for a sufficiently large constant $C>0$, then with probability at least $1-\delta$  we have that  $\abs{\pr_{\widehat{D}}[S]-\pr_{D}[S]}\le \pr_{D}[S]/2$ for all $S\in \mathcal{S}$.
Hence,  $\pr_{\widehat{D}}[S]\ge \pr_{D}[S]/2$, i.e., the number of samples that fall in each set $S\in \mathcal{S}$ is at least $N\pr_{D}[S]/2= N(\eps_1/(Kk))^{\Omega(k)}$.  


Therefore, 
{if $N\ge (dm)^{Cm}(kK/\eps_1)^{Ck}\log(1/(\delta\eps_2))/\eta^{C}$ for a sufficiently large universal constant $C>0$, then} 
by applying \Cref{cl:Nobadvector2} we have 
the following: with probability $1-\delta$, 
for any unit vector $\vec v\in (W^{\perp}+V)\cap V^{\perp}$ 
\begin{align*}
    \vec v^{\top} \widehat{\vec U} \vec v\le \sum_{S\in \mathcal{S}, I\in \mathcal{U}} m\eta^2\pr_{\widehat{D}}[S] \le \abs{\cI}\left(m\eta^2 +\frac{K^5\eps'}{\eps_1}\right)\;.
\end{align*}
Hence, since $\widehat{\vec U}$ is a symmetric PSD matrix, applying \Cref{cl:smallQuadraticFormNotLargeEigProj} we have that for all $\vec u\in \mathcal{E}$ and  unit vectors $\vec v\in W^{\perp}$ it holds that $\abs{\vec u\cdot \vec v}\le (m\eta^2+K^5\eps'/\eps_1)/\sqrt{\poly(\sigma\eps_2\alpha/K})$. 
As a result, 
since $C$ is sufficiently large, 
substituting $\eps'$ and $\eta$ we have that 
for all $\vec u^{(i)}\in \mathcal{E}$ and any 
$\vec v\in W^{\perp}$ it holds 
$\abs{\vec u^{(i)}\cdot \vec v}\le \eps$.


Consequently, by applying \Cref{lem:cEnonempty}, 
we have that if 
$N\ge (dm)^{Cm}(kK/\eps_1)^{Ck}\log(1/(\delta\eps_2))/\eta^{C}$ 
{ for a sufficiently large universal constant $C>0$}, 
the set $\mathcal{E}$ in non-empty. 
Thus, as $\vec v$ is a unit vector and 
$\norm{\vec v_{W^{\perp}}}\le \eps$, 
we have $\norm{\vec v_{W}}\ge \sqrt{1-\eps^2}\ge 1-\eps$.  
This completes the proof of \Cref{prop:inprovedCorrelation}.
\end{proof}

Now we are ready to prove \Cref{thm:MetaTheorem-realizable}. Our proof is similar to the proof of \Cref{thm:MetaTheorem-Agnostic}. The difference is that we are going to use \Cref{prop:inprovedCorrelation} which provides improved correlation when compared to \Cref{prop:MetaAlg2}.

\begin{proof}[Proof of \Cref{thm:MetaTheorem-realizable}]
We show that \Cref{alg:MetaAlgRealizable}, with high probability, returns a hypothesis $h$ with $L_2^2$ error at most $\tau+\eps$.
Let $W$ be the $K$-dimensional subspace that $y$ depends on. 
Let $L_t$ be the set of vectors maintained by the algorithm (Line \ref{line:updateMeta-realizable}) and $V_t=\mathrm{span}(L_t)$, $\dim(V_t)=k_t$. 
Also let $\eps_1$ be the partition width parameter (see \Cref{def:well-behaved-realizable}), and for $t\in [T]$ let $\mathcal{S}_t$ be arbitrary $\eps_1/K^4$-approximating
partitions with respect to $V_t$ (see \Cref{def:approximatingPartition}).
Let $h_t:\mathbb{R}^d\to [K]$ be  piecewise constant functions, defined as $h_t= h_{\mathcal{S}_{t}}$ according to \Cref{def:h} for the distribution $D$. 


Note that from Lines \ref{line:initMeta-realizable}, \ref{line:loopMeta-realizable} of \Cref{alg:MetaAlgRealizable}, we perform  $T\eqdef K$ iterations. Furthermore, in each iteration, we update the vector set by adding one vector. Hence, 
$k_t\leq K$ for all $t\in [T]$.

 Assume that $\E_{(\bx, y)\sim D}[(h_t(\bx)- y)^2]> \tau+\eps/2$ for all $t=[T]$.
 Denote by $\vec v^{(t)}\in V_{t+1}\cap V_{t}^{\perp}, t\in [T]$ the unit vectors added at each iteration and let $C$ be a sufficiently large universal constant.
 Note that in order to add a new vector $\vec v^{(t)}\in V_{t+t}\cap V_{t}^{\perp}$ with $\norm{(\vec v^{(t)})^W}\geq 1-\rho$ by applying \Cref{prop:inprovedCorrelation}, 
 we need to already have that every unit vector 
 $\vec v\in V_{t-1}$ satisfies 
 $\norm{\vec v^W}\geq 1-\rho(\eps_1\eps_2\alpha/(mK))^{C}$.
Moreover, since $\vec v^{(t)}$ are orthonormal in this case, 
for all unit vectors  
$\vec v\in V_{t}$ it holds that ${\norm{\vec v^W}\geq 1-\rho(\eps_1\eps_2\alpha/(mK))^{C}}$.
Thus, if the number of samples is sufficiently large, 
for all iterations $t\in [T]$ 
applying the proposition for $\rho=(1/(2K))(\eps_1\eps_2\alpha/(mK))^{CK}$ (in place of $\eps$) 
would result to orthonormal vectors $\vec v^{(t)}$ 
with 
$\norm{(\vec v^{(t)})^W}\geq 1-1/2K$ for all $t\in [K]$.

 Therefore, using the fact that $N={(dm)}^{C m}(m K/(\eps_1\eps_2 \alpha ))^{CK}(M/(\eps\sigma))^{C}\log(1/\delta)$  (Line \ref{line:initMeta-realizable} of \Cref{alg:MetaAlgRealizable}),
 we can iteratively apply \Cref{prop:inprovedCorrelation} 
  and conclude that, with probability $1-\delta$, there exist unit vectors $\vec v^{(t)}\in  V_{t+1}$ and unit vectors $\w^{(t)}\in W$ for $ t\in[T]$ such that $\w^{(t)}\cdot \vec v^{(t)}_{ V_t^{\perp}}\ge  1-1/(2K)$.
 Thus, from \Cref{it:potentialDecrease}, we have that with probability $1-\delta$, for all $t\in [T]$,  $\Phi_t\le \Phi_{t-1}- 1+1/(2K)$. 
 After $T$ iterations, it follows that $\Phi_T\le \Phi_{0}- T +T/(2K)$.
 However, if $T$ is set to be $K+1$ we would arrive at a contradiction, since $\Phi_T\ge 0$.
 Hence, we have that $\E_{(\bx, y)\sim D}[(h_t(\bx)- y)^2]\leq \tau+\eps/2$, for some $t\in \{1,\dots, T\}$. 
 Since the error of $h_t$ can only be decreasing  (see \Cref{it:ErrorDecrease}), and  $h_t$ is close to its sample variant by \Cref{cl:hConcetration}, we have that $\E_{(\bx, y)\sim D}[(h(\bx)- y)^2]\le \tau+\eps$.

\vspace{-0.1cm}

\item \textbf{Sample and Computational Complexity:} Note that the algorithm terminates in $O(K)$ iterations 
and at each iteration we draw $N={(dm)}^{O(m)}2^{\poly(K)}(m/(\eps_1\eps_2 \alpha ))^{O(K)}(M/(\eps\sigma))^{O(1)}\log(1/\delta)$ samples.
Hence, the total sample size is  
${(dm)}^{O(m)}2^{\poly(K)}(m/(\eps_1\eps_2 \alpha ))^{O(K)}(M/(\eps\sigma))^{O(1)}\log(1/\delta)$. 
Moreover we use at most $\poly(N)$ time, 
as all operations can be implemented in polynomial time.
\end{proof}



\subsection{Algorithmic Applications to Structured Multi-Index Model Classes}\label{sec:applications}
In this section, we show that our general algorithm 
can be leveraged to obtain  state-of-the-art 
guarantees for learning positive-homogeneous 
Lipschitz MIMs and polynomials in a few relevant directions.  
The former result is new and subsumes prior work on homogeneous 
ReLU networks. 




\subsubsection{Learning Positive-Homogeneous Lipschitz MIMs}\label{sec:hom}
For each application, we show that the resulting distribution \( D \) over examples \( (\mathbf{x}, y) \)
is a well-behaved MIM distribution with favorable parameters, and we consequently apply \Cref{thm:MetaTheorem-realizable}.

First, we recall the target class definition.
\begin{definition}[Positive-Homogeneous Lipschitz MIMs]
For $K \in \Z_+$ and $L > 0$, we define $\mathcal{H}_{K,L}$ to be the class of all $L$-Lipschitz $K$-MIMs $f : \R^d \to \R$ such that $f$ is positive-homogeneous, meaning $f(t\x) = t f(\x)$ for all $t > 0$ and $\x \in \R^d$, and $f$ has unit $L_2^2$ norm under the Gaussian distribution, that is, $\E_{\x \sim \cN_d}[f^2(\x)] = 1$.
\end{definition}
This class generalizes the class of Lipschitz and homogeneous ReLU networks of arbitrary depth, since the ReLU activation is itself positive-homogeneous.
We prove that by applying our algorithm we can learn the aforementioned class efficiently. 
Specifically, note the following theorem.
\begin{theorem}[PAC Learning $\mathcal{H}_{K,L}$]\label{thm:learninghom}
Let $f:\R^d\to \R$ be a function in $ \mathcal{H}_{K,L}$ and let 
 $D$ be the joint distribution of $(\x,f(\x))$, where $\x\sim \cN_d$. 
Then, \Cref{alg:MetaAlgRealizable} draws $N =d^22^{O(K^3L^2/\eps^2)}\log(1/\delta)$ i.i.d.\ samples from $D$, runs in time $\poly(N)$, and returns a  hypothesis $h$ such that, with probability at least $1 - \delta$, it holds 
   $\E_{(\bx,y)\sim D}[(h(\bx)-y)^2] \leq \eps\;.$
\end{theorem}
Moreover, consider the following class of bounded depth ReLU Networks.
\begin{definition}[Lipschitz and Homogeneous ReLU Networks]\label{def:relus}
Let $\mathcal{F}_{S,K,L}$ denote the concept class of $L$-Lipschitz, homogeneous (feedforward) ReLU networks over $\R^d$ of size $S$ that depend only on the projection onto a subspace of dimension at most $K$.
Specifically, $f \in \mathcal{F}_{S,K,L}$ if $f$ is $L$-Lipschitz, $\E_{\x\sim \cN_d}[f^2(\x)]=1$ and  there exist weight matrices
$\vec W_i \in \mathbb{R}^{k_{i+1} \times k_{i}}$, $i\in [D-1]$
with $k_1=d$ and $k_D=1$, $\mathrm{rank}(\vec W_1) \leq K$,
for which
$f(\x) = \vec W_D \phi(\vec W_{D-1}(\cdots \phi(\vec W_1\x)\cdots)),$
where $\phi(z) = \max\{z, 0\}$ is the ReLU activation applied entrywise, and $k_1 + \cdots + k_{D-1} = S$.
\end{definition}

Since the class of ReLU Networks we defined is positive homogeneous we can apply \Cref{thm:learninghom} and obtain the following implication. 

\begin{corollary}[Learning Homogeneous ReLU Networks]\label{thm:learningRelus}
Let $f:\mathbb{R}^d\to\mathbb{R}$ be a ReLU network in the class $\mathcal{F}_{S,L,K}$ and let $D$ be the joint distribution of $(\x,f(\x))$, where $\x\sim \cN_d$. 
Then, \Cref{alg:MetaAlgRealizable} draws $N =d^22^{O(K^3L^2/\eps^2)}\log(1/\delta)$ i.i.d.\ samples from $D$, runs in time $\poly(N)$, and returns a  hypothesis $h$ such that, with probability at least $1 - \delta$, it holds 
$\E_{(\bx,y)\sim D}[(h(\bx)-y)^2] \leq \eps\;.$
\end{corollary}
We remark that our primary result about learning general positive-homogeneous Lipschitz functions is not achievable
by the algorithm of \cite{chen2022FPT}, as it is a proper algorithm that always outputs a homogeneous ReLU network.
The fact that we use a general approximation of Lipschitz functions by piecewise constant ones (\Cref{def:h}) makes this result possible.
Furthermore, the complexity of \cite{chen2022FPT} depends exponentially on the size of the network $S$,
which can be significantly larger than the rank $K$ of the first layer.

Before we prove \Cref{thm:learninghom},
we first present a key structural result for the class $\mathcal{H}_{K,L}$.
For a distribution \( D \) over \( \mathbb{R}^d \times \mathbb{R} \), a function
\( f: \mathbb{R}^d \to \mathbb{R} \), a scalar \( \tau > 0 \), and a subspace
\( V \subseteq \mathbb{R}^d \), define the following matrix:
\begin{align}\label{eq:relus-transformation}
\vec M_\tau^V \eqdef 
\mathbb{E}_{(\x,y)\sim D}
\Bigl[
T(\x_V,y)
\bigl(\x_{V^{\perp}}(\x_{V^{\perp}})^\top - \Pi_{V^{\perp}}\bigr)
\Bigr],\; T(\x_V,y)=\Ind(\abs{y - f\bigl(\x_V\bigr)} >\tau).   
\end{align}

The following lemma states that this filtered second moment matrix has large correlation with some direction in $W^{\perp V}$. 
\begin{lemma}[Generalization of Lemma 5.5 in \cite{chen2022FPT}]\label{lem:structRelus}
Let $V,W$ be subspaces of $\R^d$ with $\dim(W)=K,\dim(V)=k$ and  $V\subseteq W$. 
Let $f:\R^d\to \R$ be a function in $\mathcal{H}_{K,L}$ such that $f(\x_W)=f(\x)$. 
Suppose that 
$
\mathbb{E}_{\x \sim \cN_d}
\bigl[
\bigl(f(\x) - f\bigl(\x_V\bigr)\bigr)^2
\bigr]
\ge \eps^2$ 
for some $\eps > 0.$
For \( \tau > 2\sqrt{K - k}\,L \), and \( \vec{M}_\tau^V \in \mathbb{R}^{d \times d} \) the matrix defined in \Cref{eq:relus-transformation}, we have that there exists a unit vector \( \mathbf{w} \in W \) such that
$
\w^{\top}\vec M_\tau^V \w
\gtrsim
e^{-3K\tau^2/\eps^2}
\;\frac{\tau\eps}{\sqrt{K}L^2}.
$
\end{lemma}
\begin{proof}[Proof of \Cref{lem:structRelus}]
Let $U$ denote the projection of the subspace $W$ onto $V^{\perp}$.
 Note that since $f$ is $L$-Lipschitz the condition $\abs{f(\x)-f(\x_V)}\geq 2\sqrt{K-k}L$ implies that $\norm{\x_{U}}^2\geq 2(K-k)$.
 As a result, by taking the trace inner product with the projection matrix onto \( W \), we have that there exists a unit vector \( \mathbf{w} \in W \) such that
\begin{align*}
\w^{\top}\vec M_\tau^V \w\geq (K-k)\pr[\abs{f(\x)-f(\x_V)}\geq 2\sqrt{K-k}L]\;.
 \end{align*}
 Note that since $f$ is a positive-homogeneous function we have that $f(\x)-f(\x_V)$ is positive-homogeneous.
 Moreover, because $f$ depends only on the projection of $\x$ onto $W$ and $V$ is a subspace of $W$, the function $f(\x)-f(\x_V)$
 depends also only on the projection of $\x$ onto $W$.
 Thus in order to complete the proof it suffices to prove an anticoncetration result about positive-homogeneous functions:

\begin{claim}[Anticoncetration of Positive-Homogeneous Functions]\label{lem:anti1}
If $G: \R^K\to\R$ is positive-homogeneous and $L$-Lipschitz and $\E[G^2] \ge \sigma^2$, then for any $s \ge 0$, \begin{equation*}
\pr_{\x\sim \cN_K}[|G(\x)| > s] \gtrsim  \exp(-3Ks^2/\sigma^2) \frac{s \sigma}{\sqrt{K}L^2}\;.
\end{equation*}
\end{claim}

\begin{proof}[Proof of \Cref{lem:anti1}]
Note that if $\x\sim \cN_K$ then it can be decomposed as $\x=\sqrt{r}\vec v$ where $r\sim\chi^2_m$ and $\vec v$ is drawn uniformly from $\mathbb{S}^{K-1}$ independent of $r$. 
First note that by independence of $r$ and $\vec v$ we have that 
\begin{align*}
 \sigma^2=\E_{\x\sim \cN_K}[G^2(\x)]=\E[r]\E[G^2(\vec v)]=K\E[G^2(\vec v)]\;.   
\end{align*}
Thus, $\E[G^2(\vec v)]=\sigma^2/K$.
Hence, by elementary anticoncetration \Cref{fact:basicanti} we have that 
\begin{align*}
 \pr_{\x\sim \cN_K}[\abs{G(\x)}\geq s]\geq \pr[rG^2(\vec v)\geq s^2]&\geq \pr[r\geq2Ks^2/\sigma^2] \pr[\abs{G(\vec v)}\geq \sigma/\sqrt{2K}\; ] \\
 &\geq  \pr[r\geq2Ks^2/\sigma^2]\frac{\sigma^2}{2KL^2}\\
 &\gtrsim  \exp(-3Ks^2/\sigma^2) \frac{s \sigma}{\sqrt{K}L^2}\;,
\end{align*}
where  we used the well-known fact that $\pr_{r\sim \chi_{m}^2}[r\geq x]\ge \mathrm{erfc}(1/\sqrt{x})$ and  $\mathrm{erfc}(x)\ge\sqrt{2/\pi}\frac{xe^{-x^2/2}}{x^2+1} $, for all $x\ge 0$.
Which concludes the proof of \Cref{lem:anti1}.
\end{proof}
 Therefore, we can apply \Cref{lem:anti1} for the function $f(\x)-f(\x_V)$,  which concludes the proof of \Cref{lem:structRelus}.
\end{proof}

Now following this structural result, in order to show that the class $\mathcal{H}_{K,L}$ leads to well-behaved
 MIM distributions and allows the application of \Cref{thm:MetaTheorem-realizable},
 it suffices to establish the existence of non-trivial moments for a cube-interval pair.

We prove this result in two stages. First, we show that if it is possible to obtain
 distinguishing moments by conditioning on a region of \( V \times \mathbb{R} \)
 that is well-approximated by cubes and intervals, then there exists a specific
 cube-interval pair exhibiting distinguishing moments. 
Consequently, we prove that the region \( T \) defined
 in \Cref{eq:relus-transformation} can indeed be well-approximated
 by such cube-interval pairs.

\begin{lemma}[Label Transformation Approximation]\label{lem:approxTransform}
Let $D$ be a distribution supported on $\mathbb{R}^d \times \mathbb{R}$, whose $\x$-marginal is $\cN_d$, and let $V$ be a subspace of $\mathbb{R}^d$. Suppose that $T(\x_V, y): V \times \mathbb{R} \to \{0,1\}$ is a label transformation function and that $p: \mathbb{R}^d \to \mathbb{R}$ is a  zero mean,  variance one polynomial such that $\E_{(\x,y)\sim D}[p(\x) T(\x_V, y)] \geq \sigma$. Let $P$ be a partition of $V \times \mathbb{R}$, and let $P' \subseteq P$. 
Define the approximation $\widehat{T}(\x_V, y) \eqdef \sum_{R \in P'} \Ind((\x_V, y) \in R)$.
If $\pr_{(\x,y)\sim D}[T(\x_V, y) \neq \widehat{T}(\x_V, y)]\leq \frac{\sigma^2}{4}$, then there exists some $R \in P'$ such that $\E\big[p(\x) \Ind((\x_V, y) \in R)\big] \geq \frac{\sigma}{2 \lvert P' \rvert}$. \end{lemma}
\begin{proof}
First we can write
\[
\E_{(\x,y)\sim D}\bigl[p(\x)T(\x_V,y)\bigr] 
=\E_{(\x,y)\sim D}\bigl[p(\x)\widehat{T}(\x_V,y)\bigr] + \E_{(\x,y)\sim D}\bigl[p(\x)(T(\x_V,y)-\widehat{T}(\x_V,y))\bigr].
\]
Therefore, we have that
\[
\E_{(\x,y)\sim D}\bigl[p(\x)\widehat{T}(\x_V,y)\bigr] 
\ge \sigma - \Bigl|\E_{(\x,y)\sim D}\bigl[p(\x)(T(\x_V,y)-\widehat{T}(\x_V,y))\bigr]\Bigr|.
\]
Since $p(\x)$ has variance one, by Cauchy–Schwarz,
\[
\Bigl|\E_{(\x,y)\sim D}\bigl[p(\x)(T(\x_V,y)-\widehat{T}(\x_V,y))\bigr]\Bigr|
\le \sqrt{\E[p(\x)^2]\E[(T(\x_V,y)-\widehat{T}(\x_V,y))^2]}
\le \sqrt{\sigma/2}\,.
\]
Thus,
\[
\E_{(\x,y)\sim D}\bigl[p(\x)\widehat{T}(\x_V,y)\bigr] \ge \sigma/2.
\]
We can write
\[
\E_{(\x,y)\sim D}\bigl[p(\x)\widehat{T}(\x_V,y)\bigr]
=\sum_{R\in P'} \E_{(\x,y)\sim D}\bigl[p(\x)\Ind((\x_V,y)\in R)\bigr].
\]
Hence, by the pigeonhole principle, there exists some $R\in P'$ such that
\[
\E_{(\x,y)\sim D}\bigl[p(\x)\Ind((\x_V,y)\in R)\bigr]
\ge \frac{1}{\abs{P'}}\,\E_{(\x,y)\sim D}\bigl[p(\x)\widehat{T}(\x_V,y)\bigr]
\ge \frac{\sigma}{2\abs{P'}}.
\]
This completes the proof of \Cref{lem:approxTransform}.
\end{proof}



In the following lemma we show that the label transformation defined in \Cref{eq:relus-transformation} can be approximated arbitrary well by a piecewise constant function over a discretization of $V\times \R$ in cubes and intervals.


\begin{lemma}[Cube-Interval Approximation of $T$]\label{lem:transformationRelus}
Let $d,k\in \Z_+,\eps,\eta\in (0,1)$, $\tau,L\in \R_+$ with $\tau\geq L\geq \eps$.
Let $V,W$ be  subspaces of $\R^d$ with $V\subseteq W$, $\dim(V)=k$ and $\dim(W)=K$.
Let $f:\R^d\to \R$ be function in $\mathcal{H}_{K,L}$ such that  $f(\x)=f(\x_W)$, and let $D$ be the joint distribution of $(\x,f(\x))$ where $\x\sim \cN_d$. 
Denote by $T:V\times \R\to \{0,1\}$ the function defined in \Cref{eq:relus-transformation}.
Let $(\mathcal{S},\mathcal{I})$ be an $\eta$-approximating discretization of $V\times \R$, with $\eta\leq\eps^4/(L\sqrt{k}K)$.

There exists  a subset of the discretization $P\subseteq \mathcal{S}\times \mathcal{I}$ such that for the function $\widehat{T}(\x_V,y)=\sum_{(S,I)\in P}\Ind(\x_V\in S,y\in I)$ it holds that 
$
    \pr_{(\x,y)\sim D}[T(\x_V,y)\neq \widehat{T}(\x_V,y)]\lesssim \eps\;.$
\end{lemma}
\begin{proof}
Without loss of generality, we can assume that the discretizations \( \mathcal{S} \) and \( \mathcal{I} \) of the spaces \( V \) and \( \mathbb{R} \),  extend to their entire respective domains (see \Cref{def:approximatingDiscretization}).
This is justified because the partition $\mathcal{S}$ is defined over the subset of $\R^d$ whose coordinates, in an orthonormal basis of $V$, are at most $\sqrt{\log(k/\eta)}$. By the union bound, the probability mass outside this region is at most $\eta$. 
Similarly, the same holds for $\mathcal{I}$, since $\E_{\x \sim \mathcal{N}_d}[f^2(\x)] = 1$, there is at most an $\eps$ fraction of the probability mass outside the relevant interval when $\abs{y} \geq 1/\eps^2$. 
As a result, by the union bound, we have
\[
\Pr\left[T(\x_V, y) \neq \widehat{T}(\x_V, y), \ \x \notin \bigcup_{S \in \mathcal{S}} S \ \lor \ y \notin \bigcup_{I \in \mathcal{I}} I \right] \leq 2\eps.
\]



Define the set $A=\{(\x_V,y):\abs{y-f(\x_V)}=\tau\}$ to be the boundary set of boolean function $T$. 
We set $P$ to be the subset of the discretization regions $(S,I)$ with $S\in \mathcal{S}$ and $I\in \mathcal{I}$ such that for all points in $(\x_V,y)\in (S,I)$ it holds that $\abs{y-f(\x_V)}>\tau$. 
Note the diameters of the sets $S$ and $I$ are $\sqrt{k}\eta $ and $\eta$ for all regions $(S,I)$ with $S\in \mathcal{S}$ and $I\in \mathcal{I}$ respectively. 
Hence, we have that $\pr_{(\x,y)\sim D}[T(\x_V,y)\neq \widehat{T}(\x_V,y)]\leq \pr_{(\x,y)\sim D}[(\x_V,y)\in E]$, where we define 
$E\eqdef\{(\x_V,y)\mid \exists (\x'_V,y')\in A :\norm{\x_V-x'_V }\leq \sqrt{k}\eta,\abs{y-y'}\leq \eta \}$.

Note that for every $(\x_V,y)\in E$ since $f$ is $L$-Lipschitz we have that $\abs{y-f(\x_V)}=\tau \pm 2 L\sqrt{k}\eta$. Therefore, it suffices to upper bound $\pr_{(\x,y)\sim D}[\abs{y-f(\x_V)}= \tau \pm 2 L\sqrt{k}\eta]$ or in other words to show anticoncetration of the random variable $y-f(\x_V)=f(\x)-f(\x_V)$.

Define the parameter $\delta= 2L\sqrt{k}\eta$.
Since \(f\) depends only on the projection onto the \(K\)-dimensional subspace \(W\), the function \(g(\x_V)=f(\x)-f(\x_V)\) also depends only on \(\x_W\).  
Moreover, because \(f\) is positive-homogeneous, so is \(g\).  Hence we may define an induced function \(\widetilde{g}:\R^K\to\R\) by \(\widetilde{g}(\z)=f(\z)-f(\z_{V})\), which is likewise positive-homogeneous, and observe that \(g(\x)=\widetilde{g}(\x_W )\).
Under \(\x\sim\mathcal N_d\), the projected vector \(\x_W\) is distributed as \(\mathcal N_K\).  
Therefore 
\(\Pr_{\x\sim\mathcal N_d}[\,g(\x)=\tau\pm \delta\,]
=\Pr_{\z\sim\mathcal N_K}[\,\widetilde{g}(\z)=\tau\pm \delta\,]\),
and one can carry out the anticoncentration analysis on the positive-homogeneous function \(\widetilde{g}:\R^K\to\R\).


We show anticoncetration of the function $\widetilde{g}$. We do this in two stages. First we show anticoncetration over fibers, i.e. fixed lines that go through the origin, and then we take the expectation over fibers. 



We can rewrite a gaussian vector $\x$ as $r \vec v$, where $\vec v$ as a uniform unit random vector and $r$ a scalar random variable independent of $\vec v$ such that $r^2\sim \chi_K$. Note that for any fixed direction $\vec v$ it holds that 
\begin{align*}
    \pr[\widetilde{g}(\x)=\tau\pm\delta \mid \vec v=\z]&= \pr[r\widetilde{g}(\z)=\tau\pm\delta]\;.
\end{align*}
Let $\alpha>0$ be a parameter to be quantified later.
First, consider the case where $\abs{\widetilde{g}(\z)}\geq \alpha$ in this case by the Carbery-Wright inequality (see \Cref{fact:CW}) we have that 
\begin{align*}
\pr[r\widetilde{g}(\z)=\tau\pm\delta\mid \vec v=\z]\leq\pr\left[r=\frac{1}{\alpha}( \tau\pm \delta)\right]\lesssim  \frac{1}{\alpha}\frac{\sqrt{\tau\delta}}{ K^{1/4}}\;.    
\end{align*}
Second, we consider the case where $\abs{\widetilde{g}(\z)}< \alpha$. We have that 
\begin{align*}
\pr[r\widetilde{g}(\z)=\tau\pm\delta\mid \vec v=\z]\leq \pr[r\geq \tau/(2\alpha)]\;,    
\end{align*}
since $\tau-\delta\geq \tau/2$. Note that setting $\alpha=\delta^{1/4}\tau/(2\sqrt{K})$  by the Gaussian Annulus theorem (\Cref{fact:Annulus}) we have that $
\pr[r\widetilde{g}(\z)=\tau\pm\delta\mid \vec v=\z]\leq e^{-\sqrt{K/\delta}}\leq \sqrt{\delta/K}$. 


Thus in both cases we have that $\pr[r\widetilde{g}(\z)=\tau\pm\delta]\leq (K\delta)^{1/4}$. Taking the expectation over $\vec v$ completes the proof of \Cref{lem:transformationRelus}.
\end{proof}


Moreover, we can also show that $f$ is very close in squared error to a bounded function.
This is needed in order for us to be able to approximate $f$ using a finite collection of cubes.
\begin{lemma}[Functions in $\mathcal{H}_{K,L}$ are almost bounded]\label{nn:almost-bounded}
Let $f:\R^d\to \R$ be a function in $\mathcal{H}_{K,L}$ then for any $B\geq C\sqrt{K}L\ln(LK/\eps)$, for a sufficiently large constant $C>0$,
there exists a function $f_B:\R^d\to [-B,B]$ such that 
$\E_{\x\sim \cN_d}[(f(\x)-f_B(\x))^2]\leq \eps$.
\end{lemma}
\begin{proof}
Define the function $f_B(\x)=\sgn(f(\x))\min(|f(\x)|,B)$. 
Note that since $f\in \mathcal{H}_{K,L}$ from \Cref{fact:Annulus} we have that for $t\geq L\sqrt{K}$ and some universal constant $C'>0$
\begin{align*}
\pr[\abs{f(\x)}\geq t]\leq \pr[\norm{\x_W}\geq t/L]\leq e^{-C't/(L\sqrt{K})}\;.
\end{align*}
Therefore, by applying this tail bound, we have
\begin{align*}
\E\bigl[(f(\x)-f_B(\x))^2\bigr]\leq
\E[f^2(\x)\Ind(\abs{f(\x)}>B]
&=B^2\pr[\abs{f(\x)}\geq B]+ \int_{B^2}^{\infty}\Pr[\abs{f(\x)}^2\geq t]dt\\    
&=B^2e^{-C'B/(L\sqrt{K})}+ 2\int_{B}^{\infty}t\Pr[\abs{f(\x)}\geq t]dt\\
&=e^{-C'B/(L\sqrt{K})}(B^2+BL\sqrt{K}/C'+L\sqrt{K}/C') \;.
\end{align*}
Choosing $B$ to be $C\sqrt{K}L\ln(LK/\eps)$, for a sufficiently large constant $C>0$, completes the proof.
\end{proof}



Finally, before proceeding to the proof of our theorem, we make the following remark concerning the precise dependence of our algorithm's sample complexity on the dimension.
\begin{remark}\label{rem:samplecomplexity}
{\em We remark that the sample complexity bound in \Cref{thm:MetaTheorem-realizable} is $O(d^{O(m)})$, since at each step we perform polynomial regression of degree $m$ (see \Cref{fact:regressionAlg}).
In the special case $m=2$, we can reduce this to $O(d^2)$  by noticing that the polynomial regression task is directly reducible to covariance estimation in the Frobenius norm.
Furthermore, achieving $O(d)$ sample complexity is possible by replacing the regression in Line \ref{line:regression} with a simple covariance‐estimation step since covariance estimation in the operator norm requires $O(d)$ samples.
Concretely, for each interval $I\in\mathcal I$ and region $S\in\mathcal S$, define $\vec M_{S,I} = \E_{(\x,y)\sim D}[\Ind(y\in I)(\x\x^\top - I)\mid \vec x\in S]$, and let $\vec u_{I,S}$ be its top eigenvector. Then, following the filtering in Line \ref{line:matrixMeta}, set
$\widehat{ \vec U} = \sum_{I\in\mathcal I,S\in\mathcal S}\Pi_{V^{\perp}} \vec u_{I,S}\,\vec u_{I,S}^\top\,\Pi_{V^{\perp}}\,\Pr[S]$.
By essentially the same argument as in the proof of \Cref{prop:inprovedCorrelation}, $\widehat{\vec U}$ provides an arbitrarily accurate projection onto $W$, while it requires only $O(d)$ samples.}
\end{remark}

Given \Cref{lem:transformationRelus}, we  now prove the main theorem of this section, which shows that the class $\mathcal{H}_{K,L}$ can be learned efficiently using our algorithmic approach.

\begin{proof}[Proof of \Cref{thm:learninghom}]
Let \( V \subseteq \mathbb{R}^d \) be a subspace of $W$, and let \( (\mathcal{S}, \mathcal{I}) \) denote an \( \eta \)-approximating discretization of \( V \times \mathbb{R} \), where \( \eta \eqdef e^{-CK^2L^2/\eps^2} \) (see \Cref{def:approximatingDiscretization}).

    The proof consists of showing that $D$ is a $(2,e^{-CK^3L^2/\eps^2},K,1,\eps,e^{-CK^3L^2/\eps^2}, e^{-CK^2L^2/\eps^2},  e^{-CK^2L^2/\eps^2})$-well-behaved MIM distribution, as in \Cref{def:well-behaved-realizable}, 
    for a sufficiently large constant $C>0$, and then simply applying \Cref{thm:MetaTheorem-realizable}. 

    First, observe that for the distribution \( D \) Conditions (1) and (2) are satisfied with parameters $\E_{(\x,y)\sim \cN_{d}}[y^2]=1$ and dimension of the low dimensional subspace equal to \(K\). 

    Let $W$ be a $K$ dimensional subspace of $\R^d$ such that $f(\x)=f(\x^W)$ (existence of $W$ is guaranteed since $f\in \mathcal{H}_{K,L}$) and let $V$ a subspace of $W$.
    Notice that since $\eta$ has been chosen appropriately small \Cref{fact:structResultPoly,lem:approxTransform,lem:transformationRelus} 
    together imply that if 
    $\E_{\x\sim \cN_d}[(f(\x)-f(\x_V))^2]\geq \eps$, then there exists $(S,I)\in (\mathcal{S},\mathcal{I})$ and zero mean, unit variance polynomial $p:W_{V^{\perp}}\to \R$ of degree at most $2$ such that 
    $\E_{(\x,y)\sim D}[p(\x_{W_{V^{\perp}}})\Ind(y\in I)\mid \x_V\in S]\geq e^{-CK^3L^2/\eps^2}$.

    We can generalize the above statement for a general subspace $V$ of $\R^d$ with $\dim(V)\leq K$ by noticing that $f$ also depends only on $W'=W+V$.
    Since $V\subseteq W'$ and $\dim(W')\leq 2K$ we have that 
    if 
    $\E_{\x\sim \cN_d}[(f(\x)-f(\x_V))^2]\geq \eps$, then there exists $(S,I)\in (\mathcal{S},\mathcal{I})$ and zero mean, unit variance polynomial $p:W'_{V^{\perp}}\to \R$ of degree at most $2$ such that 
    $\E_{(\x,y)\sim D}[p(\x_{W'_{V^{\perp}}})\Ind(y\in I)\mid \x_V\in S]\geq e^{-8CK^3L^2/\eps^2}$.
    Noticing that $W'_{V^{\perp}}=W_{V^{\perp}}$ gives us the  statement for a general subspace $V$ of $\R^d$ of dimension at most $K$.


    Therefore, by the assumption that \( f \) is \( L \)-Lipschitz, to verify Condition (3), we can apply the aforementioned statement along with \Cref{nn:almost-bounded,lem:piecewise-constant-suffices},   imply that if for a piecewise constant approximation \( h_{\mathcal{S}} \) (see \Cref{def:h}) it holds that  $\E_{(\x,y)\sim D}[(h_{\mathcal{S}}(\x) -y )^2]\leq \eps$, then 
    $\E_{(\x,y)\sim D}[p(\x_{W'_{V^{\perp}}})\Ind(y\in I)\mid \x_V\in S]\geq e^{-32CK^3L^2/\eps^2}$.
    Consequently, conclude that Condition (3) is satisfied with the specified parameters. 


     Taking into account \Cref{rem:samplecomplexity} on the sample complexity of the algorithm, concludes the proof of \Cref{thm:learninghom}.
\end{proof}



\subsubsection{Polynomials in a Few Relevant Directions}
\label{sec:poly}

In this section, we demonstrate an application of our algorithm to the problem of learning polynomials that depend on only a few directions. Specifically, consider the class of $\alpha$‑non‑degenerate, low‑rank polynomials.
\begin{definition}\label{def:non-degenerate}
A polynomial \(q : \mathbb{R}^d \to \mathbb{R}\) is $\alpha$-\emph{non-degenerate} if
\[
  \bM =\E_{\x \sim \cN_d}\bigl[\nabla q(\x)\,\nabla q(\x)^\top\bigr]
  \quad\text{satisfies}\quad
  \bM \;\succeq \; \alpha\,\|\vec M\|_{2}\vec I.
\]
We say a rank-\(K\) polynomial \(p : \mathbb{R}^d \to \mathbb{R}\) is non-degenerate if \(p\) is non-degenerate in the \(K\)-dimensional subspace corresponding to the relevant directions. That is, there exist orthonormal vectors \(\w^{(1)}, \dots, \w^{(K)}\) such that
\(
  p(\x) = q(\w^{(1)}\cdot  \x,\dots, \w^{(K)} \cdot \x)
\)
and \(q\) is non-degenerate. 
We denote by $\mathcal{P}_{K,m}^{\alpha}$ the class of $\alpha$ non-degenerate polynomials of rank $K$, degree at most $m$ that have zero mean and unit variance under the standard gaussian.
\end{definition}
Note the assumption on the mean and the variance is without loss of generality as we can normalize the samples and obtaining a variance dependency however we assume it for simplicity.
We first present a key structural result of \cite{CM20} for the aforementioned class of polynomials. 
Specifically, for a distribution $D$ of $\R^d\times \R$, a scalar $\tau>0$ and subspace $V$ with orthonormal basis $\vec v^{(1)},\dots,\vec v^{(k)}$, $\dim(V)=k$ define the following matrix:
\begin{align}
\vec M_\tau^V =
\biggl(
  \E_{(\x,y)\sim D}
  \Bigl[T(\x_V,y)
  \bigl(\x_{V^{\perp}}(\x_{V^{\perp}})^\top {-} \Pi_{V^{\perp}}\bigr)\Bigr]
\biggr), \text{ }T(\x_V,y)= \Ind(\lvert y\rvert>\tau, \abs{\vec v^{(i)}\cdot \x} \le 1, i\in [k])\label{eq:polynomialsTransformation}    
\end{align}
The following fact states that this label transformation $T$ leads to a non-trivial moment.
\begin{fact}[e.g., Lemma 4.2 \cite{CM20}]\label{fact:structResultPoly}
Let $d,m,K\in \Z_+$ and $\alpha>0$. There exists constants $\tau$ and $ \lambda$ that depend only on $K,m$ and $\alpha$ such that the following holds.
Let $V$ and $W$ be a subspaces of $\R^d$ with $\dim(V)< \dim(W)=K$ such that $\norm{\vec v_W}\geq 1-\lambda$ for all unit vectors $\vec v\in V$.
Let $p:\R^d\to \R$ be a  polynomial  in the class  $\mathcal{P}_{K,m}^{\alpha}$ (see \Cref{def:non-degenerate}) with $p(\bx)=p(\bx_W)$.
There exists a unit vector $\vec u\in W_{V^{\perp}}$ such that 
${\vec u}^{\top} \vec M_{\tau}^V \vec u\geq \lambda\;.$
\end{fact}
In the following lemma we show that the label transformation defined in \Cref{eq:polynomialsTransformation} can be approximated arbitrary well by a piecewise constant function over a discretization of $V\times \R$ in cubes and intervals.
\begin{lemma}\label{lem:transformationPolynomials}
Let $d,k\in \Z_+$ and let $\eps>0$ such that $\eps< c$, for a sufficiently small constant $c>0$.
Let $p:\R^d\to \R$ be a  polynomial of degree $m$ that 
has mean zero and variance one under $\cN_d$,  
and let $D$ be the joint distribution of $(\x,p(\x))$ where $\x\sim \cN_d$.
Let $V$ be a $k$-dimensional subspace of $\R^d$, $k\geq 1$.
Denote by $T:V\times \R\to \{0,1\}$ the function defined in \eqref{eq:polynomialsTransformation}, and let $(\mathcal{S},\mathcal{I})$ be an $\eps$-approximating discretization of $V\times \R$ (see \Cref{def:approximatingDiscretization}).
Assume that $T$ and $\mathcal{S}$ are defined with respect to the 
same orthonormal basis of $V$.
There exists  a subset of the discretization $P\subseteq \mathcal{S}\times \mathcal{I}$ such that for the function $\widehat{T}(\x_V,y)=\sum_{(S,I)\in P}\Ind(\x_V\in S,y\in I)$ it holds that 
$
    \pr_{(\x,y)\sim D}[T(\x_V,y)\neq \widehat{T}(\x_V,y)]=O(k\eps+m\eps^{1/m})\;.
$
\end{lemma}
\begin{proof}
Let $\vec v^{(1)},\dots,\vec v^{(k)}$ be a basis of $V$ used to define $T$; this same basis is also used to construct the $\eps$-approximating partition $\mathcal{S}$.
We  construct $P$ as a cartesian product of subsets  $\mathcal{S}'\subseteq \mathcal{S}$ and $\mathcal{I}'\subseteq\mathcal{I}$.

Define $R\eqdef \{\x: \abs{\vec v^{(i)}\cdot \x}\leq 1, i \in [k]\}$. 
Since \( 1 \leq \sqrt{\log(k/\eps)} \) for \( \eps \leq c \), for a sufficiently small constant \( c > 0 \), it follows from the definition of an \( \eps \)-approximating partition (see \Cref{def:approximatingPartition}) that for all \( \x \in R \), there exists some \( S \in \mathcal{S} \) such that \( \x \in S \).

We define $\mathcal{S}'$ to be the union of the sets  $S\in \mathcal{S}$ such that $S\subseteq R$. 
Note that in order 
for $\sum_{S\in \mathcal{S}'}\Ind(\x\in S)$ and $\Ind(\x\in \R)$ to disagree on some point $\x\in \R^d$, it must be that $\abs{\vec v^{(i)}\cdot \x}\in [1,1-\eps]$ for some $i\in [k]$. 
Indeed, if  $\x$ satisfies $\abs{\vec v^{(i)}\cdot \x}\leq 1-2\eps$ for all $i\in [k]$, then the corresponding $S\in \mathcal{S}$ that contains $\x S$ must lie lie entirely within $R$

Using the union bound and the anti-concentration of the Gaussian distribution, we obtain the following bound on the  disagreement probability
\begin{align*}
  \pr_{\x\sim \cN_d}[\exists i\in [k]:\abs{\vec v^{(i)}\cdot \x}\in [1,1-2\eps]]\leq 2k\eps\;.
\end{align*}

Next, since $\E_{\x\sim \cN_d}[p^2(\x)]=1$, by Markov's inequality we have that $\pr_{\x\sim \cN_d}[\abs{y}\geq 1/\eps^2]\leq \eps$. 
Hence,  all but an $\eps$ fraction of the probability mass of $y$ that satisfying the condition $\abs{y}\geq \tau$ lies within the discretization $\bigcup_{I\in \mathcal{I}} I$. 

We define $\mathcal{I}'$ to be  the union of all $I\in \mathcal{I}$ such that for all $y\in I$, we have that $\abs{y}>\tau$.
Then, similar to the  argument above have that 
\begin{align*}
    \pr[ \Ind(y\in \mathcal{I}')\neq \Ind(\abs{y}>\tau) ]\leq \pr[\abs{y}\in(\tau-\eps,\tau)]\lesssim m \eps^{1/m}\;,
\end{align*}
where the final inequality follows from the Carbery-Wright inequality (see \Cref{fact:CW}).
Applying the union bound concludes the proof of \Cref{lem:transformationPolynomials}.
\end{proof}

Now given \Cref{lem:transformationPolynomials}  we can prove the following theorem which states that polynomials in a few relevant directions can learned by using our algorithmic approach.
\begin{theorem}[Learning Polynomials in a Few Relevant Directions]\label{thm:learning-polynomials}
Let $K,m,d\in \Z_+, \alpha >0$ and $\delta,\eps\in (0,1)$.
There exists a constant $C(K,m,\alpha)$ that depends only on $K,m$ and $\alpha$ such that the following holds.
Let $p:\R^d\to \R$ be a  polynomial in $\mathcal{P}_{K,m}^{\alpha}$  (see \Cref{def:non-degenerate}) and let $D$ be the joint distribution of $(\x,p(\x))$ where $\x\sim \cN_d$.
Then, \Cref{alg:MetaAlgRealizable} draws $N =d^2\log(1/\delta)C(K,m,\alpha)/\eps^{O(mK)}$ i.i.d.\ samples from $D$, runs in time $\poly(N)$, and returns a  hypothesis $h$ such that, with probability at least $1 - \delta$, it holds 
   $\E_{(\bx,y)\sim D}[(h(\bx)-y)^2] \leq \eps\;.$
\end{theorem}
\begin{proof}
The proof is very similar to the proof of \Cref{thm:MetaTheorem-realizable}.
Let $W$ be a $K$-dimensional subspace of $\R^d$ such that $p(\x)=p(\x_W)$ (note that the existence of $W$ is guaranteed by since $p\in \mathcal{P}_{K,m}^{\alpha}$).



First, observe that for the distribution $D$, Conditions (1) and (2) of \Cref{def:well-behaved-realizable}  are satisfied for $ \E_{(\x,y)\sim D}[y^2]=1$ and dimension of the low dimensional subspace equal to $K$.

We can apply \Cref{prop:inprovedCorrelation} together with \Cref{lem:approxTransform,fact:structResultPoly} iteratively $K+1$ times to obtain subspaces $V_t$, each of dimension $t-1$ for $t \in [K+1]$, starting from $V_1 = \{\vec{0}\}$ (exactly as in the proof of \Cref{thm:MetaTheorem-realizable}).
Using $N = d^2 \log(1/\delta) C(K, m, \alpha)/\eps^{O(mK)}$ samples and $\poly(N)$ time for all $K$ iterations,
we have that every unit vector in $V_{K+1}$ is arbitrarily $\eps/(K^2m)$-close to some unit vector in $W$

Using this we prove that 
$\|\Pi_W-\Pi_{V}\| \le\eps/(mK) $. 
Denote by $V\eqdef V_{K+1}$, by $\{\vec v^{(i)}\}_1^K$ and $\{\vec w^{(i)}\}_1^K$ orthonormal basis of $V$ and $W$ respectively.
Also denote by $\vec M_{V}$ and $\vec M_{W}$ matrices that have $\{\vec v^{(i)}\}_1^K$ and $\{\vec w^{(i)}\}_1^K$ as column vectors.
We have that 
\[\|\Pi_W-\Pi_{V}\|\leq K- \|\vec M_W^\top\vec M_{V}\|_F^2 = K-\sum_{i=1}^K\|\vec v^{(i)}_W\|\leq \eps/(mK)\;.\]
Hence, it also holds that
$\|\Pi_W\,\Pi_{V^\perp}\|=\|\Pi_W-\Pi_V\|\le\eps/(mK).$


Therefore, by applying \Cref{fact:gradientNorm} we have that   $\E_{\x\sim \cN_d}[\norm{\nabla p(\x)}^2]\leq m$.
Hence, the difference 
$\E[(p(\x_W)-\E[p(\z+\x_{W_{V^{\perp}}} )\mid z=\x_{W_V}])]$ 
can be bounded above 
by $O(\eps)$ using  \Cref{cl:nabla2smallchange}.
Thus, we have that after $K$ iterations 
that there exists a function $g(\x_V)$ that 
achieves error $\eps$.

 Finally, note that from the well-known fact that
 for $t>2^{O(m)}$ it holds that 
 $\pr[\abs{p(\x)}\geq t]\leq \exp(-O(mt^{2/m}))$ by simply integrating we can show that $p$ is $\eps$-close in squared error to a function bounded on $[-B,B]$ with $B=m/\eps^{O(m)}$.
 Hence, we can apply \Cref{lem:piecewise-constant-suffices,cl:hConcetration} for the aforementioned 
 number of samples
 we conclude that the difference 
 $\E_{(\x,y)\sim D}[(h(\x) -y )^2]= O(\eps)$, for the output hypothesis $h$.
Taking into account \Cref{rem:samplecomplexity} on the sample complexity of the algorithm, concludes the proof of \Cref{thm:learning-polynomials}.
\end{proof}





\section{Omitted Technical Facts}\label{sec:ommited}

\subsection{Basic Mathematical Facts}
\begin{fact}[see e.g. Claim 2.3 in \cite{DKRS23}]
 \label{clm:othor-tran}
Let $1\le m<n$. Let $\bB\in\R^{m\times n}$ with $\bB\bB^\intercal=\bI_m$.
It holds that
$\bH_k(\bB\bx)=\bB^{\otimes k}\bH_k(\bx),\bx\in\R^n$.
\end{fact}


\begin{fact}[Gaussian Density Properties]
\label{fact:gaussianfacts}
    Let $\mathcal{N}$ be the standard one-dimensional normal distribution. Then, the following properties hold:
\begin{enumerate}[leftmargin=*]
    \item For any $t > 0$, it holds $e^{-t^2/2}/4 \leq \pr_{z \sim \mathcal{N}}[z > t] \leq e^{-t^2/2}/2$.
    \item For any $a, b \in \mathbb{R}$ with $a \leq b$, it holds $\pr_{z \sim \mathcal{N}}[a \leq z \leq b] \leq (b-a)/\sqrt{2\pi}$.
\end{enumerate}
\end{fact}

\begin{fact}[Gaussian Annulus Theorem see e.g., \cite{Ver18}]\label{fact:Annulus}
    If $\x\sim \cN_d$, with probability at least $1-\tau$ we have that 
    $
        \left| \norm{\x}^2 -d \right| \lesssim \log \frac{1}{\tau}+ \sqrt{d\log \frac{1}{\tau}} \;.
    $
\end{fact}

\begin{fact}[Gaussian Hypercontractivity; see e.g., \cite{AoBF14}]
\label{fact:fourthmoment}
Let $p:\R^d\to \R$ be a polynomial of degree at most $m$ which has zero mean and variance one under the gaussian distribution.
 For every real number $q \ge 2$, we have
$
\|p\|_{L^q} 
=
(q - 1)^{\,\frac{d}{2}}\,\|p\|_{L^2}\;.$
\end{fact}
\begin{fact}[Carbery-Wright Inequality see e.g., \cite{CW:01}]
\label{fact:CW}
Let $p:\R^d\to \R$ be a polynomial of degree $m$. If $\Var_{\x\sim \cN_d}[p(\x)]=1$, then it holds that for any $t\in \R$ and $\eps >0$
$
    \pr_{\x\sim \cN_d}[\abs{p(\x)-t}\leq \eps ]\lesssim m\eps^{1/m}\;.
$
\end{fact}


\begin{fact}[see, e.g., Lemma 6 in \cite{KTZ19}]\label{fact:gradientNorm}
 Let  $f \in L^2(\mathbb{R}^d, \cN_d)$ with its $k$-degree Hermite expansion $f(\bx)= \sum_{\alpha\in \N^d,\|\alpha\|_1\leq k}\widehat{f}(\alpha)H_{\alpha}(\bx)$. It holds that $\mathbb{E}_{\bx \sim \cN_d} \left[ (\nabla f (\bx) \cdot \be_i)^2 \right] = \sum_{\alpha \in \mathbb{N}^d
 \|\alpha\|_1\leq k} \alpha_i (\widehat{f}(\alpha))^2$.

\end{fact}




\subsection{Omitted Content from \Cref{sec:agnostic} to \Cref{sec:applications}}



\begin{fact}[see e.g. Claim B.1 \cite{diakonikolas2025robustlearningmultiindexmodels}]
    \label{cl:coorelationofeigenvalues}
 Let $\bM\in \mathbb{R}^{d\times d}$ a symmetric positive semi-definite (PSD) matrix and let \(\bv\in \mathbb{R}^d \) with $\norm{\bv}\le 1$ such that  \( \bv^\top  \bM \bv \ge \alpha \). 
Then there exists a unit eigenvector $\bu$ of $\bM$ with eigenvalue at least $\alpha/2$ such that
\(
\abs{\bu\cdot \bv} \gtrsim ({\alpha}/{\|\bM\|_F})^{3/2}\;.
\)
Moreover, the number of eigenvectors of $\bM$ with eigenvalue greater than $\alpha/2$ is at most
\(
{4\|\bM\|_F}/{\alpha^2}\;.
\)
\end{fact}
\begin{fact}[see e.g. Claim 4.12 \cite{diakonikolas2025robustlearningmultiindexmodels}]
    \label{cl:smallQuadraticFormNotLargeEigProj}
Let $\vec M\in \R^{d\times d}$ be a symmetric, PSD matrix and let $\vec v\in \R^d$ be a unit vector such that $\vec v^{\top} \vec M \vec v\le \eps$. Let $U$ denote  the set of unit eigenvectors of $\vec M$ with eigenvalue {at least} $\lambda$. Then, for every $\vec u\in U$, it holds that $\abs{\vec u\cdot \vec v}\le \sqrt{\eps/\lambda}$.
\end{fact}
\begin{fact}[see, e.g., Lemma 3.3 in \cite{DKKTZ21}]\label{fact:regressionAlg}
     Let $\mathcal{D}$ be a distribution on $\mathbb{R}^d \times \{\pm 1\}$ whose x-marginal is $\cN_d$. Let $k \in \mathbb{Z}_+$ and $\epsilon, \delta > 0$. There is an algorithm that draws $N = (dk)^{O(k)} \log(1/\delta)/\epsilon^2$ samples from $\mathcal{D}$, runs in time $\text{poly}(N, d)$, and outputs a polynomial $P(\bx)$ of degree at most $k$ such that
$
\mathbb{E}_{(\bx,y) \sim \mathcal{D}} [(y - P(\bx))^2] \leq \min_{P' \in \mathcal{P}_k} \mathbb{E}_{(\bx,y) \sim \mathcal{D}} [(y - P'(\bx))^2] + \epsilon,
$ 
with probability $1 - \delta$.
\end{fact}
\begin{fact}[see, e.g., Lemma 3.3 in \cite{DKKTZ21}]
\label{fact:regressionSubspaceBound}
    Fix $\epsilon \in (0,1)$ and let $P(\bx)$ be a degree-$k$ polynomial, such that
$
\mathbb{E}_{(\bx,y) \sim \mathcal{D}}[(y - P(\bx))^2] \leq \min_{P' \in \mathcal{P}_k} \mathbb{E}_{(\bx,y) \sim \mathcal{D}}[(y - P'(\bx))^2] + O(\epsilon).
$
Let $\bM = \mathbb{E}_{\bx \sim \mathcal{D}_\bx} [\nabla P(\bx) \nabla P(\bx)^\top]$ and $V$ be the subspace spanned by the eigenvectors of $\bM$ with eigenvalues larger than $\eta$. Then the dimension of the subspace $V$ is $\dim(V) = O(k/\eta)$ and moreover $\tr(\bM)=O(k)$.
\end{fact}
\begin{fact}[Approximation of a Bounded Variation Function using Cubes]\label{fact:piecewiseconstantfromboundedgradientnorm}
There exists a sufficiently small constant $c>0$ such that the following holds.
Let $f:\R^d\to \R$ continuous and continuous differentiable almost everywhere such that 
$\E_{\bx\sim \cN_d}[\norm{\nabla f(\bx)}^2]\leq L$.
Moreover, assume that there exists a $B>0$ and $f_B:\R^d\to [-B,B]$ such that $\E_{\bx\sim\mathcal N_d}[(f(\x)-f_B(\x))^2]\leq \rho$.
Denote by $h:\R^d\to \R$ the piecewise constant approximation $h(\bx)=\E_{\bx \sim \cN_d}[f(\bx) \mid \bx\in S]$, for all $\bx\in S$ and $S\in \mathcal{S}$, where $\mathcal{S}$ is a collection of consecutive cubes over $\R^d$ of width $\eta\leq c\eps/(Ld\log(B))$, i.e. $\mathcal{S}$ denotes all subsets of $\R^d$ of the form $\{\bx: \bj_i\eps+t \leq \bx_i\leq  (\bj_{i}+1)\eps+t\}, \bj_i\in \Z^d, t\in [0,\eps/2]$.

Then $\E_{\bx\sim \cN_d}[(f(\bx)-h(\bx))^2]\leq \eps+2\rho$.
\end{fact}\begin{proof}
Denote by $ \phi(\bx)=(2\pi)^{-d/2}\exp(-\|\bx\|^2/2) $ and set 
$ \mu_S(\bx)=\phi(\bx)/\Pr_{\bx\sim\cN_d}[\bx\in S].$
For each cube $S\in\cS$ define 
$ f_S=\E_{\bz\sim\mu_S}[f(\bz)] $ and $
   m_S=1/|S|\int_S f(\bz)\,d\bz, $
where we denote by $\abs{S}$ the geometric volume of the set $S$.
Write 
\[ \phi_{\min}^S=\inf_{\x\in S}\phi(\x),\quad
   \phi_{\max}^S=\sup_{\x\in S}\phi(\x),\quad
   \kappa_S= \frac{\phi_{\max}^S}{\phi_{\min}^S} \]
Fix $R=\sqrt{d\log(B/\eps)/c }$ and let $T=\bigcup\{S:\min_{\x\in S}\|\x\|>R\}$.  From the Gaussian Annulus Theorem (\Cref{fact:Annulus}) we have that  
$\Pr[\x\in T]\le \eps/(8B^2)$.

Moreover, note that since $f$ is close to a bounded function, by Jensen's inequality so is $h$. 
Indeed
$\E[(h(\x)-\E_{\bx \sim \cN_d}[f_B(\bx) \mid \bx\in S])^2]\leq \rho$.
Hence the tail error approximation error of $h$ is bounded 
the tail error $\E[(f(\x)-h(\x))^2\Ind(\x\in T)]\leq 2\rho+\eps/2$.

Hence without loss of generality we can consider cubes with $\|\x\|\le R$ for all $\x\in S$.
Moreover, for those cubes $S\not \subseteq T$ it holds that 
\[ \kappa_S\le \kappa \eqdef \exp( R\eta\sqrt d)\;. \]

From the fundamental theorem of calculus, for every $\x,\y\in S$, it holds that 
\[ f(\x)-f(\y)=\int_0^1\nabla f\bigl(\y+t(\x-\y)\bigr)\cdot(\x-\y)\,dt\;. \]
Hence, using Jensen's  inequality  we have 
\[ (f(\x)-f(\y))^2\le\|\x-\y\|^2\int_0^1\|\nabla f(\y+t(\x-\y))\|^2\,dt
              \le d\,\eta^2\int_0^1\|\nabla f(\y+t(\x-\y))\|^2\,dt \]
Averaging in $\y\in S$ and then in $\x\in S$ yields
\[\frac{1}{\abs{S}}\int_S(f(\x)-m_S)^2\,d\x
   \le d\,\eta^2 \frac{1}{\abs{S}}\int_S\|\nabla f(\x)\|^2\,d\x\;. \]
We can transfer the above bound to the gaussian case for all cubes $S\not \subseteq T$. Specifically,
\begin{align*}
\E_{\mu_S}[(f-m_S)^2]
&\le  \frac{\phi_{\max}^S\abs{S}}{\pr[S]}\E_{\mathrm{Unif}(S)}[(f-m_S)^2]\\
&\le \frac{\phi_{\max}^S\abs{S}}{\pr[S]} d\,\eta^2\,\E_{\mathrm{Unif}(S)}[\|\nabla f\|^2]\\
&\le \kappa_S d\eta^2\E_{\mu_S}[\|\nabla f\|^2].
\end{align*}
Moreover, since $f_S$ minimizes $\E_{\mu_S}[(f(\x)-m)^2]$, we have 
\[ \E_{\mu_S}[(f(\x)-f_S)^2]\le\E_{\mu_S}[(f(\x)-m_S)^2]\;. \]
Averaging over cubes we have 
\[ \E[(f(\x)-h(\x))^2]\le \kappa d\eta^2\E[\|\nabla f(\x)\|^2]+ 2\rho+\eps/2
  \le Ld\kappa\eta^2 + 2\rho+\eps/2 \;. \]
Setting $\eta= c^2\eps/(Ld\log(B))$ for a sufficiently small constant $c>0$ concludes the proof of \Cref{fact:piecewiseconstantfromboundedgradientnorm}.
\end{proof}


\begin{fact}[Discretization over a Subspace]\label{fact:subspaceApprox}
Let $f:\R^d\to\R$ is continuous,  continuous differentiable almost everywhere and satisfies $\E_{\bx\sim\mathcal N_d}[\|\nabla f(\bx)\|^2]\le L$.
Moreover, assume that there exists a $B>0$ and $f_B:\R^d\to [-B,B]$ such that $\E_{\bx\sim\mathcal N_d}[(f(\x)-f_B(\x))^2]\leq \rho$.
Let $V$ be a $k$-dimensional subspace of $\R^d$ and let $\vec v^{(1)},\dots,\vec v^{(k)}$ be an orthonormal basis of $V$ and let $\mathcal S$ be the partition of $V$ into axis-aligned cubes of width $\eps$.  
Define  $h(\bx)=\E_{\bz_V\sim\mathcal N_k}\bigl[f(\bz_V+\bx_{V^\perp})\mid \bz_V\in S\bigr]$.  
Then  
$\E_{\bx\sim\mathcal N_d}[(f(\bx)-h(\bx))^2]\le L\,k\,\eps^2$.  
\end{fact}

\begin{proof}
Let $f_B$ be the truncation of $f$ to the interval $[-B,B]$, that is $f_B(\x)=\sign(f(\x))\min(\abs{f(\x)},B)$.
Note that $\E[(f_B(\x)-f(\x))^2]\leq \rho$ since $f_B$ is closer to $f$ than any other truncated function.

The function $f_B$ is continuous since we truncate at the level set $B$ continuously.
Moreover, $f_B$ is non‐differentiable at the points $\{\,f(\x)=B\}\cap\{\nabla f(\x)\neq\vec 0\}$.
But by the implicit‐function theorem, whenever $f(\x_0)=B$ and $\nabla f(\x_0)\neq\vec 0$
there is a neighborhood in which $\{x\colon f(x)=B\}$ is a $C^1$ submanifold of codimension $1$
in $\R^d$, hence of Lebesgue (and thus Gaussian) measure $0$. 
Therefore these extra non‐differentiable
points lie in a countable union, since each neighborhood contains at least one point in $\mathbb{Q}^d$, of such submanifolds
and so form a Gaussian‐measure $0$ set.

Moreover, almost everywhere
\[
\nabla f_B(\x)
=
\begin{cases}
\nabla f(\x), 
& |f(\x)| < B, \\[6pt]
\mathbf{0}, 
& |f(\x)| > B \text{ or } \bigl(f(\x)=\pm B \text{ with } \nabla f(\x)=\mathbf{0}\bigr),
\end{cases}
\]
and on the remaining set—namely 
$
\{\,f(\x)=\pm B\}\cap\{\nabla f(\x)\neq\mathbf{0}\}
$
together with the set of original non-differentiable points of $f$—the function fails to be differentiable but that set has Gaussian measure $0$.  Hence
\[
\E_{\x\sim\cN_d}\bigl[\|\nabla f_B(\x)\|^2\bigr]
\;\le\;
\E\bigl[\|\nabla f(\x)\|^2\bigr]
\;\le\;L.
\]





Denote by $h_B(\bx)=\E_{\bz_V\sim\mathcal N_k}\bigl[f_B(\bz_V+\bx_{V^\perp})\mid \bz_V\in S\bigr]$.
First, by the law of total expectation and the independence of orthogonal components of the standard gaussian we have that
\[
\E[(f_B(\x)-h_B(\x))^2]
=\E_{\x_{V^{\perp}}}[\E_{\x_V}[(f_B(\x)-h_B(\x))^2]].
\]
For each fixed \(\x_{V^{\perp}}\), we can apply  \Cref{fact:piecewiseconstantfromboundedgradientnorm} in the \(k\)–dimensional subspace \(V\) to the function \(\phi_{\x_{V^{\perp}}}(\x_V)\eqdef f_B(\x^{V}+\x_{V^{\perp}})\), which is always bounded by $B$.  Noting that inequality \(\|\nabla_{\x_V}\phi_{\x_{V^{\perp}}}(\x_V)\|\le\|\nabla f_B(\x)\|\) gives us that that for any fixed $\x_{V^{\perp}}$
\[
\E_{\x_V}[(f_B(\x)-h_B(\x))^2]\leq 2\rho+\eps.
\]
Taking the outer expectation over \(\x_{V^{\perp}}\) yields
\[
\E_{\x}[(f_B(\x)-h_B(\x))^2]\leq  2\rho+\eps.
\]
Finally, we have that 
\begin{align*}
    &\E[(f(\x)-h(\x))^2]\\
    &\leq 2\E[(f(\x)-f_B(\x))^2]+2\E[(f_B(\x)-h_B(\x))^2]+2\E[(h_B(\x)-h(\x))^2]
    \lesssim \rho +\eps\;,
\end{align*}
 where we used that $\E[(h_B(\x)-h(\x))^2]\leq 2\rho+\eps$ because of Jensen's inequality.
\qedhere
\end{proof}


\begin{fact}[Median of Means Estimator see, e.g., \cite{BouLM13} ]
\label{fact:medianofmeans}
Let $x_1,\ldots,x_n$ be i.i.d. random variables with mean $\mu$ and variance $\sigma^2$. Suppose that $n = m k$, where $m$ and $k$ are positive integers. Define the median-of-means estimator $\widehat{\mu}_n$ as the median of $k = \lceil 8\log(1/\delta)\rceil$ independent sample means. Then, with probability at least $1-\delta$, we have
$
\left|\widehat{\mu}_n - \mu\right|
\le
\sigma \sqrt{\frac{32\,\log(1/\delta)}{n}}.
$
\end{fact}

\begin{fact}[see e.g. Fact 3.3 \cite{chen2022FPT}]\label{fact:basicanti}
If $Z$ is a random variable for which $\abs{Z} \le M$ almost surely, and $\E[Z^2]\ge \sigma^2$, then $\Pr{\abs{Z} \ge t} \ge \frac{1}{M^2}(\sigma^2 - t^2)$.
\end{fact}



