In the following, we intend to show that each (saturated) $(G,R)$-automaton is a (maximally permissive) supervisor.     It should be pointed out that our proof methods are from\rvgreplace{ }{~}\cite{2020Synthesis}. We begin with  giving the following lemma,  which is  proposed in \cite{2020Synthesis} and holds for the automaton $(G,R)^\uparrow$. Since it only depends on the conditions (istate) and $(\ref{def-S arrow new}-b)$ in Definition \ref{def-S arrow new}, it is  still valid for any  $(G,R)$-automaton. For the sake of completeness, we provide its proof given in \cite{2020Synthesis}.
\smallskip


\begin{lemma} \label{lemma-couter-pi(X)w2}
	Given a plant $G=(X,\Sigma, \longrightarrow, X_0)$ and  specification $R=(Z,\Sigma, \longrightarrow, Z_0)$, if $\mathcal{A}=(A,\Sigma,\longrightarrow,A_0)$ is a $(G,R)$-automaton, then, for  any $s\in \Sigma^*$, $W_0\in A_0$ and $W\in A$,  $W_0\stackrel{s}{\longrightarrow}W$ implies $\pi_G(W)=Reach(s,X_0)$, where
	\begin{align}
		&\pi_G(W)= \{x\in X: (x,z)\in W \text{ for some }z\in Z\} \text{ and }\notag\\ &Reach(s,X_0)=\{x\in X: x_0\stackrel{s}{\longrightarrow}x\text{ for some }x_0\in X_0\}\notag.
	\end{align}


	\begin{proof}
		It proceeds by induction on $|s|$, i.e., the length of $s$. If $|s|=0$ then $s=\varepsilon$, and hence $\pi_G(W_0)=X_0=Reach(s,X_0)$ by the clause (istate) in Definition \ref{def-S arrow new}. In the following, we deal with the inductive step and let $|s|=k+1$.   		 		
		Assume that $s=s_1\sigma$ and $W_0\stackrel{s_1}{\longrightarrow}W_1\stackrel{\sigma}{\longrightarrow}W$ with  $W_1\in A$. By the induction hypothesis, we have $\pi_G(W_1)=Reach(s_1,X_0)$. Next we show $\pi_G(W)=Reach(s,X_0)$. 

		($\subseteq$) Let $x\in \it left.$ Then, there exists $z\in Z$ such that $(x,z)\in W$. Due to $W_1\stackrel{\sigma}{\longrightarrow}W$, by the clause $(\ref{def-S arrow new}-b)$ in Definition \ref{def-S arrow new}, we get
		$W\in N(W_1,\sigma)$, and hence	$$W\in\powerset(\bigcup_{(x_1,z_1)\in W_1}\{x':x_1\stackrel{\sigma}{\longrightarrow} x'\}\times\{z':z_1\stackrel{\sigma}{\longrightarrow} z'\}).$$
		Thus, 	there exists $(x_1,z_1)\in W_1$ such that $x_1\stackrel{\sigma}{\longrightarrow}x$ and $z_1\stackrel{\sigma}{\longrightarrow}z$. Due to $(x_1,z_1)\in W_1$, $x_1\in \pi_G(W_1)=Reach(s_1,X_0)$. Then, it follows that $x_0\stackrel{s_1}{\longrightarrow}x_1\stackrel{\sigma}{\longrightarrow}x$ for some $x_0\in X_0$, which implies $x\in Reach(s,X_0)$.

		$(\supseteq)$ Let $x\in right.$ Thus, $x_0\stackrel{s_1}{\longrightarrow}x_1\stackrel{\sigma}{\longrightarrow}x$ for some $x_1\in X$ and $x_0\in X_0$. Hence, $x_1\in Reach(s_1,X_0)=\pi_G(W_1)$, and thus $(x_1,z_1)\in W_1$ for some $z_1\in Z$. Due to $W_1\stackrel{\sigma}{\longrightarrow}W$, by the clause $(\ref{def-S arrow new}-b)$ in Definition \ref{def-S arrow new}, $W\in N(W_1,\sigma)$. Further, it follows from  $x_1\stackrel{\sigma}{\longrightarrow}x$ and $(x_1,z_1)\in W_1$ that $z_1\stackrel{\sigma}{\longrightarrow}z$ and $(x,z)\in W$ for some $z\in Z$, and thus $x\in \pi_G(W)$.	
	\end{proof} 



\end{lemma}
\smallskip

Next we show that   any $(G,R)$-automaton is a solution of the $(G,R)$-similarity control problem whenever $G\sqsubseteq_{uc} R$.
\smallskip

\begin{theorem}\label{th-couter-S arrow is a solution2}
	Given two automata $G=(X,\Sigma, \longrightarrow, X_0)$ and  $R=(Z,\Sigma, \longrightarrow, Z_0)$  with $G \sqsubseteq_{uc} R$, let $\mathcal{A}=(A,\Sigma,\longrightarrow,A_0)$ be any $(G,R)$-automaton. Then  $\mathcal{A}\in \SP(G,R) $. 
	\smallskip

	\begin{proof}
		Let  $\Phi_{uc}:G \sqsubseteq_{uc} R$.
		First we show the $\Sigma_{uc}$-admissibility of $\mathcal{A}$.    Let $(W,x)$ be a reachable state in $\mathcal{A}||G$ and $x\stackrel{\sigma}{\longrightarrow}$ with $\sigma\in \Sigma_{uc}$. 
		By Definition \ref{def-composition} and \ref{def-admissible l}, it suffices to show $W\stackrel{\sigma}{\longrightarrow}$.			
		Since $(W,x)$ is  reachable, there exists $(W_0,x_0)\in A_0\times X_0$ such that $(W_0,x_0)\stackrel{s}{\longrightarrow}(W,x)$ for some $s\in \Sigma^*$. Thus, $W_0\stackrel{s}{\longrightarrow}W$ and $x_0\stackrel{s}{\longrightarrow}x$ due to Definition \ref{def-composition}. Then, it follows from Lemma \ref{lemma-couter-pi(X)w2} that $x\in Reach(s,X_0)=\pi_G(W)$, and hence $(x,z)\in W$ for some $z\in Z$. Further, by $x\stackrel{\sigma}{\longrightarrow}$  and $\sigma\in \Sigma_{uc}$, it is easy to see that $W$ and $\sigma$ satisfy the clauses $(\ref{def-S arrow old}-a)$ and $(\ref{def-S arrow old}-b)$ in Definition \ref{def-S arrow old}. Since $\mathcal{A}$ is an $(G,R)$-automaton, by the clause $(\ref{def-S arrow new}-a)$ in Definition \ref{def-S arrow new}, we have $W\stackrel{\sigma}{\longrightarrow}$, as desired.


		To complete the proof, it remains to be proven that   $\mathcal{A}||G \sqsubseteq R$.  We define the relation $\Phi\subseteq(A\times X)\times Z $ as follows:\vspace{-2ex} 
		\begin{align*}
			\Phi= \{	&((W,x),z): (x,z)\in W \text{ and }\\
			& (W,x) \text{ is reachable in }    \mathcal{A}||G     \}.  
		\end{align*}   		 		
		Next we  show that $\Phi$ is a simulation relation from $ \mathcal{A}||G$ to $R$.  Let $(W_0,x_0)\in A_0\times X_0$. Then, $W_0\in A_0$ and $x_0\in X_0$. By the clause (istate) in Definition \ref{def-S arrow new}, we have $(x_0,z_0)\in W_0$ for some $z_0\in Z_0$.  Thus, $((W_0,x_0),z_0)\in \Phi$. Hence, each initial state in $\mathcal{A}||G$ is related to one in $R$ via $\Phi$.

		Let $((W,x),z)\in\Phi$ and $(W,x)\stackrel{\sigma}{\longrightarrow}(W',x')$ with $\sigma\in \Sigma$. Then,  $(x,z)\in W$ and   $(W,x)$  is reachable in $\mathcal{A}||G$. Since $\mathcal {A}$ is a $(G,R)$-automaton and $W\stackrel{\sigma}{\longrightarrow}W'$, by the clause $(\ref{def-S arrow new}-b
		)$   in Definition \ref{def-S arrow new}, we get $W'\in N(W,\sigma)$. Further, it follows from  $x\stackrel{\sigma}{\longrightarrow}x'$ and $(x,z)\in W$ that $z\stackrel{\sigma}{\longrightarrow}z'$ and $(x',z')\in W'$  for some $z'\in Z$. Clearly, $(W',x')$ is reachable in $\mathcal{A}||G$, and hence $((W',x'),z')\in\Phi$, as desired.
	\end{proof}
\end{theorem}
