In the following, we show that each saturated $(G,R)$-automaton is  a maximally permissive supervisor for the $(G,R)$-similarity control problem.
\smallskip

\begin{theorem}\label{theorem-couter-maximall-permessive} 	Let $G=(X,\Sigma, \longrightarrow, X_0)$ and $R=(Z,\Sigma, \longrightarrow,\linebreak Z_0)$ be two automata and $\mathcal{A}=(A, \Sigma, \longrightarrow, A_0)$ a saturated $(G,R)$-automaton. If $G\sqsubseteq_{uc} R$ then $S||G\sqsubseteq \mathcal{A}||G$	 for any $S\in \SP(G,R)$.
	\smallskip

	\begin{proof}    		
		Let $S=(Y,\Sigma, \longrightarrow, Y_0)\in \SP(G,R)$ and $\Phi: S||G\sqsubseteq R$. Since $\mathcal{A}$ is a  $(G,R)$-automaton, by Theorem \ref{th-couter-S arrow is a solution2}, we have $\mathcal{A}\in \SP(G,R)$. To complete the proof, it suffices to show that the relation $\Psi\subseteq (Y\times X)\times (A\times X)$ defined as				
		\begin{align*}\nonumber
			\Psi=\{&((y,x),(W,x)):\  \forall(x_W,z_W)\in W (((y,x_W),z_W)\in \Phi)\\  
			&\text{ and }
			\exists s\in \Sigma^*  				
			((y,x) \text{ and } (W,x)  \text{ are $s$-reachable in }\\      			
			& S||G \text{ and } \mathcal{A}||G \text{ resp.})   \}\nonumber
		\end{align*}		
		\noindent	is a  simulation relation from $S||G$ to $\mathcal{A}||G$. 

		First, it will be verified that $\Psi$ satisfies the first condition in Definition \ref{def-conventional simulation}.		
		Let $(y_0,x_0)\in Y_0\times X_0$ and $x_0'\in X_0$. Since $\Phi$ is a simulation relation from $S||G$ to $R$ and $(y_0,x_0')\in Y_0\times X_0$, there exists $z_0'\in Z_0$ such that $((y_0,x_0'),z_0')\in \Phi$. Then, it follows from Lemma \ref{lemma-couter-touying is  simulation} that $(x_0',z_0')\in \pi(\Phi)$ and $\pi(\Phi): G\sqsubseteq_{uc} R$. Thus, by the clause $(\ref{prop-fixpoint}-a)$ in Proposition \ref{prop-fixpoint}, $\pi(\Phi)=F_{(G,R)}(\pi(\Phi))$, and hence $(x_0',z_0')\in \pi(\Phi)\subseteq W_{(G,R)}^\uparrow$. 

		We have shown that, for any $x_0'\in X_0$, there exists $z_0'\in Z_0$ such that $(x_0',z_0')\in W_{(G,R)}^\uparrow$ and $((y_0,x_0'),z_0')\in \Phi$. Hence, for any $x_0'\in X_0$, we can choose arbitrarily and fix such a state  $z_0'$ and denote it as $\Delta(x_0')$. Set  $ W_0=\{(x_0',\Delta(x_0')): x_0'\in X_0\}.$
		Then $W_0\subseteq W_{(G,R)}^\uparrow\cap (X_0\times Z_0)$. Since $\mathcal{A}$ is a saturated $(G,R)$-automata, by the clauses (state) and (sistate) in Definition \ref{def-S arrow new}, we have $W_0\in A_0$, moreover,  $((y_0,x_0'),z_0')\in \Phi$ for any $(x_0',z_0')\in W_0$ due to the definition of $W_0$. Thus, $((y_0,x_0),(W_0,x_0))\in \Psi$. Further, since $(W_0,x_0)$ is an initial state of $\mathcal{A}||G$, the first condition in  Definition \ref{def-conventional simulation} holds.


		Next, we deal with  the second condition in Definition \ref{def-conventional simulation}.
		Let $((y,x),(W,x))\in \Psi$, $(y,x)\stackrel{\sigma}{\longrightarrow}(y^*,x^*)$ and $\sigma\in \Sigma$. Thus, both $(y,x)$ and $(W,x)$ are $s$-reachable for some $s\in \Sigma^*$. Hence,  $(y_0,x_{01})\stackrel{s}{\longrightarrow}(y,x)$  and $(W_0,x_{02})\stackrel{s}{\longrightarrow}(W,x)$ for some $y_0\in Y_0$, $x_{01}\in X_0$, $W_0\in A_0$ and $x_{02}\in X_0$.  To complete this proof, it suffices to show that $W\stackrel{\sigma}{\longrightarrow}W^*$ and $((y^*,x^*),(W^*,x^*))\in \Psi$ for some $W^*\in A$. To this end, we give the claim below firstly.

		\textbf{Claim} The clauses $(\ref{def-S arrow old}-a)$ and $(\ref{def-S arrow old}-b)$ in Definition \ref{def-S arrow old} hold  for $W$ and $\sigma$.

		Since $W_0\stackrel{s}{\longrightarrow}W$ and $x_{02}\stackrel{s}{\longrightarrow}x$ due to $(W_0,x_{02})\stackrel{s}{\longrightarrow}(W,x)$, by Lemma \ref{lemma-couter-pi(X)w2}, $x\in Reach(s,X_0)=\pi_G(W)$, and hence $(x,z)\in W$ for some $z\in Z$. Further, it follows from  $x\stackrel{\sigma}{\longrightarrow}x^*$ that the clause $(\ref{def-S arrow old}-a)$ in Definition \ref{def-S arrow old} holds for $W$ and $\sigma$.


		In order to illustrate that the clause $(\ref{def-S arrow old}-b)$ in Definition \ref{def-S arrow old} holds for $W$ and $\sigma$, let $(x_1,z_1)\in W$ and $x_1\stackrel{\sigma}{\longrightarrow}x_1'$. Thus, 
		$((y,x_1),z_1)\in \Phi$ because of $((y,x),(W,x))\in \Psi$ and $(x_1,z_1)\in W$. By Lemma \ref{lemma-couter-pi(X)w2}, it follows from $W_0\stackrel{s}{\longrightarrow}W$ and $x_1\in \pi_G(W)$ that $x_1$ is  $s$-reachable. Further, due to $y_0\stackrel{s}{\longrightarrow}y$, $(y,x_1)$ is also  $s$-reachable in  $S||G$,  moreover, $(y,x_1)\stackrel{\sigma}{\longrightarrow}(y^*,x_1')$ comes from $(y,x)\stackrel{\sigma}{\longrightarrow}(y^*,x^*)$ and $x_1\stackrel{\sigma}{\longrightarrow}x_1'$. Hence, it follows from $((y,x_1),z_1)\in \Phi$  that 
		$z_1\stackrel{\sigma}{\longrightarrow}z_1'$ and 	$((y^*,x_1'),z_1')\in \Phi$ for some $z_1'\in Z$. Then, since $(y^*,x_1')$ is  $s\sigma$-reachable in $S||G$, 	by  Lemma \ref{lemma-couter-touying is  simulation},  $(x_1',z_1')\in \pi(\Phi)$ and $\pi(\Phi)$ is a $\Sigma_{uc}$-simulation from $G$ to $R$. Further, by the clause $(\ref{prop-fixpoint}-a)$ in Proposition \ref{prop-fixpoint}, we have $\pi(\Phi)=F_{(G,R)}(\pi(\Phi))$, and hence $(x_1',z_1')\in \pi(\Phi)\subseteq W_{(G,R)}^\uparrow$. Hence, the clause $(\ref{def-S arrow old}-b)$ in Definition \ref{def-S arrow old} holds for $W$ and $\sigma$.

		Next, we turn to proving the theorem itself. By the proof of the above claim,  for any $(x_1,z_1)\in W$ and $x_1'\in X$ with $x_1\stackrel{\sigma}{\longrightarrow}x_1'$, there exists $z_1'\in Z$ such that  $z_1\stackrel{\sigma}{\longrightarrow}z_1'$, $(x_1',z_1')\in W_{(G,R)}^\uparrow$ and 	$((y^*,x_1'),z_1')\in \Phi$. Thus, for each $(x_1,z_1)\in W$ and $x_1\stackrel{\sigma}{\longrightarrow}x_1'$, we can choose arbitrarily and fix such a state $z_1'$ and denote it as $\ast(x_1,z_1,x_1')$. Set 		 	
		$$W''= \{(x_1', \ast(x_1,z_1,x_1')): (x_1,z_1)\in W \text{ and } x_1\stackrel{\sigma}{\longrightarrow}x_1'  \}.       $$
		Clearly, $W''\in N(W,\sigma)$ and
		\begin{equation}\label{equation-counter theorem2}
			\ ((y^*,x_1'),z_1')\in \Phi\text{ for any }(x_1',z_1')\in W''.\tag{\ref{theorem-couter-maximall-permessive}-1}
		\end{equation}  

		\noindent	Since $\mathcal{A}$ is  a saturated $(G,R)$-automaton, by the above claim and clauses $(\ref{def-S arrow new}-a)$ and $(\ref{def-S arrow new}-c)$ in Definition \ref{def-S arrow new},  there exists  $W^*\in N(W,\sigma)$ such that $W\stackrel{\sigma}{\longrightarrow}W^*$ and $W^*\subseteq W''$, and hence $(W,x)\stackrel{\sigma}{\longrightarrow}(W^*,x^*)$ due to $x\stackrel{\sigma}{\longrightarrow}x^*$. Finally, we end the proof by showing $((y^*,x^*),(W^*,x^*))\in \Psi$.
		Since both $(W,x)$ and $(y,x)$ are $s$-reachable, 
		both $(y^*,x^*)$ and  $(W^*,x^*)$  are $s\sigma$-reachable due to $(W,x)\stackrel{\sigma}{\longrightarrow}(W^*,x^*)$ and $(y,x)\stackrel{\sigma}{\longrightarrow}(y^*,x^*)$.
		Moreover, $W^*$ satisfies $
		\ ((y^*,x_1'),z_1')\in \Phi \text{ for any }(x_1',z_1')\in W^*
		$   because of (\ref{equation-counter theorem2}) and $W^*\subseteq W''$. Hence,  $((y^*,x^*),(W^*,x^*))\in \Psi$, as desired.	    		
	\end{proof}     
\end{theorem}
