	\begin{lemma}\label{lemma-exists minimal element in N(W)}
		Let $G=(X,\Sigma, \longrightarrow, X_0)$ and   $R=(Z,\Sigma, \longrightarrow,\linebreak Z_0)$ be two automata and $(G,R)^\uparrow=(Y^\uparrow,\Sigma,\longrightarrow,Y_0^\uparrow)$. If $R$ is image-finite, then, for any $W\in Y^\uparrow$, $\sigma\in \Sigma$ and $W'\in    N(W,\sigma)$, there exists a minimal element $W^*$ in $N(W,\sigma)$ such that $W^*\subseteq W'$.
		\smallskip

		\begin{proof}
			If $W'=\emptyset$, then $W'$ itself is minimal in $N(W,\sigma)$. In the following, we consider the case where $W'\neq\emptyset$.
			Put $\Omega=\{W''\in N(W,\sigma):W''\subseteq W'\}$ and let $\Omega'\subseteq \Omega$ be any chain under the relation $\subseteq$ (that is, $\Omega'\neq\emptyset$ and, for any $W,W'\in \Omega'$, either $W\subseteq W'$ or $W'\subseteq W$). By Zorn's lemma (see e.g.\  \cite{davey2002introduction}), if $\bigcap \Omega'\in \Omega$, then there exists a minimal element in the partially ordered set $\langle \Omega,\subseteq \rangle$, as desired. Next, we intend to show $\bigcap \Omega'\in \Omega$. Due to $\bigcap \Omega'\subseteq W'$, it is enough to prove $\bigcap \Omega' \in N(W,\sigma)$.

			Let $(x,z)\in W$ and $x^*\in X$ with $x\stackrel{\sigma}{\longrightarrow}x^*$. It suffices to show that $(x^*,z')\in \bigcap \Omega'$ for some $z'\in Z$ with $z\stackrel{\sigma}{\longrightarrow}z'$. On the contrary, we assume that there isn't such a state. Since $R$ is image-finite, there exist finitely many states in $Z$, say $z_0,z_1,...,z_n$, such that $z\stackrel{\sigma}{\longrightarrow}z_i$ $(0\leqslant i\leqslant n)$. By the assumption, for each $i\leqslant n$, $(x^*,z_i)\notin W_i$ for some $W_i\in \Omega'$. However, since $\Omega'$ is a chain, $\bigcap_{0\leqslant i \leqslant n}W_i=W_{i_0}$ for some $0\leqslant i_0\leqslant n$, and hence $\bigcap_{0\leqslant i \leqslant n}W_i\in N(W,\sigma )$, which contradicts that $(x,z)\in W$, $x\stackrel{\sigma}{\longrightarrow}x^*$ and $(x^*,z_i)\notin \bigcap_{0\leqslant i \leqslant n}W_i$ for each $0\leqslant i \leqslant n$.			
		\end{proof}
	\end{lemma}
	\smallskip





	\begin{proposition}\label{proposition-S arrow is satureted}
		Given a plant $G=(X,\Sigma, \longrightarrow, X_0)$ and   specification $R=(Z,\Sigma, \longrightarrow, Z_0)$ with $G\sqsubseteq_{uc}R$, if $R$ is   image-finite,  	then $(G,R)^\uparrow$ is a  
		saturated $(G,R)$-automaton.\smallskip

		\begin{proof}
			Let $(G,R)^\uparrow=(Y^\uparrow,\Sigma,\longrightarrow,Y_0^\uparrow)$. It immediately follows from the fact below that the automaton
			$(G,R)^\uparrow$ satisfies the clause (sistate) in Definition \ref{def-S arrow new}.		
			\begin{align*}
				&\{W_0\in Y^\uparrow\cap\powerset(X_0\times Z_0):\forall x_0\in X_0\  \exists !z_0\in Z_0((x_0,z_0)\\[-1ex]
				&\in W_0)\}\subseteq\{W_0\in Y^\uparrow\cap\powerset(X_0\times Z_0): |W_0|=|X_0| \text{ and } \\[-1ex]
				&\forall x_0\in X_0 \ \exists z_0\in Z_0((x_0,z_0)\in W_0)\}=Y_0^\uparrow.
			\end{align*}	
			\noindent 	Moreover, it satisfies all other clauses in Definition \ref{def-S arrow new} trivially except  	$(\ref{def-S arrow new}-a)$ and
			$(\ref{def-S arrow new}-c)$. Next we verify that $(G,R)^\uparrow$ satisfies them in turn. 


			$(\ref{def-S arrow new}-a)$  Let $W\in Y^\uparrow$ and $\sigma\in \Sigma$. Assume that $W$ and $\sigma$ satisfy the clauses $(\ref{def-S arrow old}-a)$ and
			$(\ref{def-S arrow old}-b)$ in Definition $\ref{def-S arrow old}$. Then, $W\neq\emptyset$ due to $(\ref{def-S arrow old}-a)$. Put 
			\begin{align*}
				W'=\{&(x',z'):\exists(x,z)\in W\\
				&(x\stackrel{\sigma}{\longrightarrow}x',  z\stackrel{\sigma}{\longrightarrow}z'  \text{ and } (x',z')\in W_{(G,R)}^\uparrow)\}.
			\end{align*}	
			\noindent Thus, $ W'\subseteq W_{(G,R)}^\uparrow$. Moreover, since $W$ and $\sigma$ satisfy the clauses $(\ref{def-S arrow old}-b)$ and $G\sqsubseteq_{uc}R$, by Observation \ref{obs-1}, for any 	$ (x,z)\in W$   and $x'\in X$ with  $x\stackrel{\sigma}{\longrightarrow} x'$, there exists $z'\in Z$  such that $z\stackrel{\sigma}{\longrightarrow}z'$ and $(x',z')\in W_{(G,R)}^\uparrow$. Hence, $ W'\in N(W,\sigma) $. Then, by Lemma \ref{lemma-exists minimal element in N(W)}, there exists a minimal element $W^*$ in $N(W,\sigma)$ such that $W^*\subseteq W'$. Further, by Definition \ref{def-S arrow old}, we have $W\stackrel{\sigma}{\longrightarrow}W^*$, as desired.

			$(\ref{def-S arrow new}-c)$ Assume $W\in Y^\uparrow$ and $\sigma\in \Sigma$ with $W\stackrel{\sigma}{\longrightarrow}$. Let $W'\in N(W,\sigma)$. Due to $W\stackrel{\sigma}{\longrightarrow}$, by Definition \ref{def-S arrow old}, the clauses 	$(\ref{def-S arrow old}-a)$ and 	$(\ref{def-S arrow old}-b)$ in  Definition \ref{def-S arrow old} hold for $W$ and $\sigma$. Moreover, by Lemma \ref{lemma-exists minimal element in N(W)}, there exists a minimal element $W^*$ in $N(W,\sigma)$ such that $W^*\subseteq W'$. Thus, by Definition \ref{def-S arrow old}, $W\stackrel{\sigma}{\longrightarrow}W^*$, as desired.
		\end{proof}
	\end{proposition}
	\smallskip

	By  the above proposition and Theorem \ref{theorem-couter-maximall-permessive}, we could  obtain the  following corollaries, which show that the methods for synthesizing maximally permissive supervisors 
	proposed in \cite{2020Synthesis} indeed work well under the assumption of image-finiteness. 
	\smallskip


	\begin{corollary}(Correction of Theorem 1 and 2 in \cite{2020Synthesis})\label{corollary-1}
		For any plant $G$ and  specification $R$ with $G \sqsubseteq_{uc} R$,  if $R$ is image-finite, then $(G,R)^\uparrow\in \MSP(G,R)$.
	\end{corollary}


	For the automaton $\widetilde{(G,R)^\uparrow}$, we also have the following result. Its proof is the same as that in \cite{2020Synthesis} except  using Corollary \ref{corollary-1} above instead of Theorem 1 and 2  in \cite{2020Synthesis}.
	\smallskip


	\begin{corollary}(Correction of Theorem 3 in \cite{2020Synthesis}) \label{corollary-2}
		Let $G$ and  $R$ be two automata with $G \sqsubseteq_{uc} R$. If $R$ is 
		image-finite, then  $\widetilde{(G,R)^\uparrow}\in \MSP(G,R)$.
	\end{corollary}
	\smallskip


	We can modify the clause $(\ref{def-S arrow old}-c)$ in Definition $\ref{def-S arrow old}$ to provide methods of constructing maximally permissive supervisors that solve the $(G,R)$-similarity control problem whenever $G \sqsubseteq_{uc} R$, which don't depend on the assumption of image-finiteness. In other words, we can modify Takai's construction to make Theorem 1-3 in \cite{2020Synthesis} hold in general.
	In detail, we have the following two corollaries. It's not difficult to verify that  both of the below modifications  will result in saturated $(G,R)$-automata. Therefore, by Theorem \ref{th-couter-S arrow is a solution2} and \ref{theorem-couter-maximall-permessive}, they hold immediately. 
	\smallskip

	\begin{corollary}(Modify Takai's Construction 1)\label{corollary-construction1}
		For any automaton $G$ and $R$, if $G\sqsubseteq_{uc}R$, then $(G,R)_1^\uparrow\in \MSP(G,R)$, where $(G,R)_1^\uparrow$ is defined as Definition $\ref{def-S arrow old}$ except that the clause $(\ref{def-S arrow old}-c)$ is weakened as

		$(\ref{def-S arrow old}-c') W'\in N(W,\sigma)$.	
	\end{corollary}
	\smallskip


	\begin{corollary}(Modify Takai's Construction 2)\label{corollary-construction2}
		For any automaton $G$ and $R$, if $G\sqsubseteq_{uc}R$, then $(G,R)_2^\uparrow\in \MSP(G,R)$, where $(G,R)_2^\uparrow$ is defined as Definition $\ref{def-S arrow old}$ except that the clause $(\ref{def-S arrow old}-c)$ is weakened as

		$(\ref{def-S arrow old}-c'')$  $W'$ satisfies one of the following conditions:

		\ \ $(\ref{def-S arrow old}-c''-1)$  $W'$ is minimal in $N(W,\sigma)$;

		\ \ $(\ref{def-S arrow old}-c''-2)$  $W'\in N(W
		,\sigma)$ and there is no minimal element in the set $\{W''\in N(W,\sigma): W''\subseteq W'\}.$
	\end{corollary}
	\smallskip
	In order to meet the condition $(\ref{def-S arrow new}-c)$ in Definition \ref{def-S arrow new}, compared to the clause $(\ref{def-S arrow old}-c)$, $(\ref{def-S arrow old}-c')$ simply removes the requirement for successors to be minimal elements. One advantage of $(\ref{def-S arrow old}-c'')$ over $(\ref{def-S arrow old}-c')$ is that it may reduce the number of reachable states in some situations (e.g., $N(W,\sigma)$ contains no infinite decreasing chains.) Here, we intend to provide theoretical results about a maximally permissive supervisor in general cases rather than its effective constructing method\footnote{For finite automata, such an effective constructing method has been given by Takai in \cite{2020Synthesis}, see Definition \ref{def-S arrow old} in this paper.}, so these results do not rely on the decidability of predicates like ``$W'$ is minimal in $N(W,\sigma)$" and ``there is no minimal element in the set $\{W''\in N(W,\sigma): W''\subseteq W'\}$". Moreover, in order to further reduce the number of reachable states, we can define the set of initial states of $(G,R)^\uparrow$ and $(G,R)_i^\uparrow$ $(i=1,2)$ as
	%		\vspace{-2ex}
	\begin{align*}
		\{&W_0\in Y^\uparrow\cap\powerset(X_0\times Z_0):\forall x_0\in X_0\\\ &\exists! z_0\in Z_0((x_0,z_0)\in W_0)\},
	\end{align*} 
	which is a subset of 
	\begin{align*}
		\{&W_0\in Y^\uparrow\cap\powerset(X_0\times Z_0):|W_0|=|X_0| \text{ and }\\&\forall x_0\in X_0 \ \exists z_0\in Z_0((x_0,z_0)\in W_0)\}=Y_0^\uparrow.
	\end{align*}

	To apply the construction of \cite{2020Synthesis} in non-image-finite systems, one may transform them to image-finite ones at the cost of introducing infinitely many initial states, as mentioned in Section 2.  However, this transformation can be circumvented by modifying the construction of \cite{2020Synthesis} in accordance with  Corollary \ref{corollary-construction1} or \ref{corollary-construction2}.




	By the way,  the following implication doesn't always  hold, where $W_0\in Y_0^\uparrow$ in $(G,R)^\uparrow$,
	\begin{align*}
		& |W_0|=|X_0| \text{ implies } \forall (x_0,z_0),(x_0',z_0')\in W_0 \\
		&(x_0=x_0'\Longrightarrow (x_0,z_0)=(x_0',z_0')).
	\end{align*}
	\noindent For instance, consider  $W_0$ given in Example \ref{example-couter example}. 
	We end this section by providing examples of $(G,R)_i^\uparrow$ ($i=1,2$).
	\smallskip



	\begin{example}
		Consider the plant $G$ and specification $R$  given in Example \ref{example-couter example}. Let  $W_{01}=\{(x_{0i},z_{0i}):i\geqslant1\}\cup\{(x_0,z_{01}), (x_0,z_{02})\}$ and $W_1=\{(x,z_1),(x,z_2)\}$. Clearly,  $W_{01}\in Y_0^\uparrow$, $W_1\in Y^\uparrow$ and $W_{01}\stackrel{\sigma}{\longrightarrow}W_1$ in $(G,R)^\uparrow$, $(G,R)_1^\uparrow$ and $(G,R)_2^\uparrow$. Since $N(W_1,\sigma)=\powerset(\{x'\}\times\{z_i':i\geqslant1\})\linebreak-\{\emptyset, \{(x',z_1')\}\}$ 
		and the set $T=\{\{(x',z_i')\}:i\geqslant 2\}$ consists of all the minimal elements in $N(W_1,\sigma)$,  for any $W_1'\in N(W_1,\sigma)$, we have $W_1\stackrel{\sigma}{\longrightarrow}W_1'$ in $(G,R)_1^\uparrow$ and
		$$ 	W_1\stackrel{\sigma}{\longrightarrow}W_1' \text{ in } (G,R)_2^\uparrow\  (\text{or, }  (G,R)^\uparrow)  \text{ iff } W_1'\in T.$$               

		For the state  $W$ in  Example \ref{example-couter example}, it's a deadlock in $(G,R)^\uparrow$, while $W\stackrel{\sigma}{\longrightarrow}W'$ in both $(G,R)_1^\uparrow$ and $(G,R)_2^\uparrow$ for any  infinite subset $W'$ of $\{(x',z_i'):i\geqslant 1\}$. Therefore, $(G,R)^\uparrow$, $(G,R)_1^\uparrow$ and $(G,R)_2^\uparrow $ are different from each other.
	\end{example}




