\tabcolsep=2mm
\begin{tabular}{l|cc}
\toprule
\textbf{Framework} & \textbf{EX (\%)} & \textbf{EP (\%)} \\ 
\midrule
Full Model & 31.81 & 88.33 \\ 
--w/o Schema Pruning & -4.63 $\downarrow$ & -20.34 $\downarrow$ \\ 
--w/o Schema Linking & -3.45 $\downarrow$ & -20.92 $\downarrow$ \\ 
