\subsection{The Proposed FICA Formulation}
%\vspace{-1 mm}


    The proposed FICA extends the success of our previous SFLA in RHS-WJCC \cite{SFLA}. An RHS-WJCC consists of the following set of constraints:
    \begin{equation*}
        \bm b_p^\top \bm \xi + d_p - \bm a_p^\top \bm x \geq 0, \  p\in [P].
    \end{equation*}
    We can observe that the only difference between the RHS-WJCC and the LHS-WJCC is the coefficient of $\bm \xi$. Based on this observation, it is clear that for each specific value of the decision vector $\bm x$, a general LHS-WJCC reduces to a RHS-WJCC since the term $(\bm b_p - \bm A_p^\top \bm x)$ becomes a parameter. This motivates us to directly apply the SFLA formulation \cite{SFLA} to the LHS-WJCC as follows:
    \begin{subequations}\label{eq:SFLA}
	    \begin{align}
	        & s \geq 0, \bm r \geq \bm 0, \label{eq:SFLA_s_r} \\
	        & \epsilon N s - \sum\limits_{i\in [N]}r_i \geq \theta N, \label{eq:SFLA_epsilonNs} \\
	        & \kappa_i \Big(\dfrac{(\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_i + d_p - \bm a_p^\top \bm x}{\| \bm b_p - \bm A_p^\top \bm x \|_*} \Big) \geq s - r_i,\nonumber \span\\
            & & \forall i \in [N]_p,\ p\in [P],  \label{eq:SFLA_main} \\
	        & \dfrac{q_p(\bm x) + d_p - \bm a_p^\top \bm x}{\| \bm b_p - \bm A_p^\top \bm x \|_*} \geq s, & \forall p \in [P], \label{eq:SFLA_spup}
        \end{align}
    \end{subequations}
    where $s$ and $\bm r$ are ancillary decision variables. The term $\bm \xi_i$ with $i\in[N]$ represents the $i$-th data sample for the random vector $\bm \xi$ (namely $\bm e$ in the dispatch problem \eqref{prob:ed}). The dual norm $\|\cdot\|_*$ corresponds to the norm used in defining the Wasserstein distance. Vector $\bm \kappa \coloneqq [\kappa_i]_{i \in [N]}$ represents tunable hyperparameters, and a uniform setting $\bm \kappa = \bm 1$ is recommended in~\cite{SFLA}. 
    Both $q_p(\bm x)$ and $[N]_p$ play a key role in enhancing computational efficiency by tightening the space of ancillary variables and removing redundant constraints, which are defined as:
    \begin{align*}
    	& q_p(\bm x) \coloneqq \text{($k{+}1$)-th smallest value of } \{ (\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_i \}_{i\in[N]}, \\
    	& [N]_p \coloneqq \{i \in [N] \mid (\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_i < q_p(\bm x) \}.
    \end{align*}
    Although a general LHS-WJCC can be expressed using SFLA as in \eqref{eq:SFLA}, such a formulation is not usable due to the difficulty of obtaining a closed-form expression for $q_p(\bm x)$ and the constraints in $[N]_p$. However, an exception arises in the one-dimensional special structure of the LHS-WJCC \eqref{cons:ed-jcc} in the power system dispatch problem. This special structure provides us with an analytical expression for $q_p(\bm x)$ illustrated in Proposition \ref{prop:1dim}. Specifically, for any $p \in [P]^*$, we have:
    {\small\begin{align}\label{eq:q_1dim}
        q_p(\bm x) = & \min\{ (\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_{k+1}, (\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_{N-k} \},
    \end{align}}where, without loss of generality, we assume that the indices $1, \ldots, N$ are ordered such that
    \begin{equation}\label{eq:order}
        (\bm b_p - \bm A_p^\top \bm 1)^\top \bm \xi_1 \leq \cdots \leq (\bm b_p - \bm A_p^\top \bm 1)^\top \bm \xi_N.
        % \sum\limits_{w\in\cW} {e}_{1,t,w} \leq \cdots \leq \sum\limits_{w\in\cW} {e}_{N,t,w}.
    \end{equation}
    These elements are derived by setting $\bm x = \bm 1$, which is the same as setting $\alpha_{t,g}=1$ in Proposition~\ref{prop:1dim}. 
    % assume that the indices $1,\cdots,N$ (including $k+1$ and $N-k$) achieve the following ordering (this can be achieved by first sorting and then re-indexing):
    % \begin{equation}
    %     (\bm b_p - \bm A_p^\top \bm 1)^\top \bm \xi_1 \leq \cdots \leq (\bm b_p - \bm A_p^\top \bm 1)^\top \bm \xi_N.
    % \end{equation}
    % These elements are derived by setting $\bm x=1$, which is the same as setting $\alpha_{t,g}=1$ in Proposition \ref{prop:1dim}.
    When constructing constraints, the $\min(\cdot)$ operator in~\eqref{eq:q_1dim} can be replaced by two inequality constraints, each corresponding to one of the two elements inside $\min(\cdot)$. This is valid since $q_p(\bm x)$ appears on the left-hand side of a ``$\geq$" constraint. Similarly, the set $[N]_p$ can be expressed as:
    \begin{align}\label{eqn:reductionset}
        [N]_p = \{ 1,\cdots, k\} \cup \{N-k+1, \cdots, N \}.
    \end{align}
    It includes the indices of the first $k$ and the last $k$ elements 
    % in the set $\{ (\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_i \}_{i \in [N]}$
    of the ordered sequence in Eq.~\eqref{eq:order}
    , which correspond to the two terms inside the $\min(\cdot)$ operator.
    % This is because $[N]_p$ collects the indices for the $1$-st to the $k$-th elements of $\{ (\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_i \}_{i\in [N]}$, which is similarly to how $q_p(\bm x)$ is defined; therefore, $[N]_p$ includes the two ends of the indices to express the $\min(\cdot)$ operator.

    Since only the $[P]^*$ group of the WJCC \eqref{cons:ed-jcc} enjoys this one-dimensional structure, the SFLA can only be partially adapted, resulting in the following migrated version:
	\begin{subequations}\label{eq:SFLA-mig}
	    \begin{align}
	        & s \geq 0, \bm r \geq \bm 0,  \label{eq:SFLA-mig_s_r} \\
	        & \epsilon N s - \sum\limits_{i\in [N]}r_i \geq \theta N,  \label{eq:SFLA-mig_epsilonNs} \\
	        & \kappa_i \Big(\dfrac{(\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_i + d_p - \bm a_p^\top \bm x}{\| \bm b_p - \bm A_p^\top \bm x \|_*} \Big) \geq s - r_i,  \nonumber \span\\ 
            & &\forall i \in [N]_p,\ p\in [P]^*,  \label{eq:SFLA-mig_main} \\
	        & \dfrac{q_p(\bm x) + d_p - \bm a_p^\top \bm x}{\| \bm b_p - \bm A_p^\top \bm x \|_*} \geq s, & \forall p \in [P]^*,  \label{eq:SFLA-mig_spup}\\
	        & \kappa_i \Big(\dfrac{(\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_i + d_p - \bm a_p^\top \bm x}{\| \bm b_p - \bm A_p^\top \bm x \|_*} \Big) \geq s - r_i,  \nonumber \span \\ 
            & & \forall i \in [N],\ p\in [P] \setminus [P]^*.  \label{eq:SFLA-mig_main2}
	    \end{align}
	\end{subequations}
    The form in \eqref{eq:SFLA-mig} is non-convex because the decision variable $\bm x$ appears in the denominator of constraints \eqref{eq:SFLA-mig_main}--\eqref{eq:SFLA-mig_spup}. To mitigate this issue, we propose a further inner approximation by replacing the denominator $\| \bm b_p - \bm A_p^\top \bm x \|_*$ with $\max_{p\in[P]}\| \bm b_p - \bm A_p^\top \bm x \|_*$. After this replacement, the denominator becomes uniform across all constraints, which motivates us to multiply both sides by this common denominator. This leads to the proposed \textit{Faster Inner Convex Approximation} (FICA) expressed in the following general form:
    \begin{subequations}\label{eq:FICA}
	    \begin{align}
	        & s \geq 0, \bm r \geq \bm 0, \label{eq:FICA_s_r} \span \\
	        & \epsilon N s - \sum\limits_{i\in [N]}r_i \geq \theta N \max_{p\in[P]}\| \bm b_p - \bm A_p^\top \bm x \|_*, \label{eq:FICA_epsilonNs} \span\\
	        & \kappa_i \Big((\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_i + d_p - \bm a_p^\top \bm x \Big) \geq s - r_i, \notag \span\\
            & \qquad\qquad\qquad\qquad\qquad\qquad \forall i \in [N]_p,\ p\in [P]^*,  \label{eq:FICA_main} \span \\
	        & \kappa_i \Big((\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_i + d_p - \bm a_p^\top \bm x \Big) \geq s - r_i, \notag \span \\
            & \qquad\qquad\qquad\qquad\qquad\quad \forall i \in [N],\ p\in [P] \setminus [P]^*,\label{eq:FICA_main2} \span \\
	        & (\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_{k+1} + d_p - \bm a_p^\top \bm x \geq s, & \forall p \in [P]^*, \label{eq:FICA_s_str_0} \span \\
            & (\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_{N-k} + d_p - \bm a_p^\top \bm x \geq s, & \forall p \in [P]^*, \label{eq:FICA_s_str} \span
	    \end{align}
	\end{subequations}
    where constraints \eqref{eq:FICA_s_str_0} and \eqref{eq:FICA_s_str} correspond to \eqref{eq:SFLA-mig_spup} that expands the $\min(\cdot)$ operator in \eqref{eq:q_1dim}.
	Appendix~\ref{appen:fica-ed} presents the FICA formulation using the specific nomenclature of the power system dispatch problem~\eqref{prob:ed}.


\section{Equivalence to CVaR}\label{sec:eq-cvar}

An alternative and widely applied inner approximation is the CVaR approach \cite{mohajerin2018data, chen2023approximations}, which can be formulated as the following set of convex constraints:
% \begin{subequations}\label{eq:CVaR}
%     \begin{align}
%         & \bm \alpha \geq \bm 0, \beta \in \mathbb{R}, \tau \in \mathbb{R},  \label{eq:wcvar-fea} \\
%         & \tau + \frac{1}{\epsilon} \Big(\theta \beta + \frac{1}{N} \sum_{i\in [N]} \alpha_i\Big) \leq 0,  \\
%         & \alpha_i \geq w_p \Big(\bm a_p^\top \bm x - (\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_i - d_p\Big) - \tau,  \notag\\
%         & && \hspace{-97pt} \forall i\in[N], p\in [P], \\
%         & \beta \geq w_p \| \bm b_p - \bm A_p^\top \bm x \|_*,  \hspace{60pt} \forall p \in [P],  \label{eq:wcvar-last}
%     \end{align}
% \end{subequations}
\begin{subequations}
    \begin{align*}
        & \bm \alpha \geq \bm 0, \beta \in \mathbb{R}, \tau \in \mathbb{R}, \\
        & \tau + \frac{1}{\epsilon} \Big(\theta \beta + \frac{1}{N} \sum_{i\in [N]} \alpha_i\Big) \leq 0,  \span\\
        & \alpha_i \geq w_p \Big(\bm a_p^\top \bm x - (\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_i - d_p\Big) - \tau,  \span\\
        & & \forall i\in[N], p\in [P], \\
        & \beta \geq w_p \| \bm b_p - \bm A_p^\top \bm x \|_*,  & \forall p \in [P], 
    \end{align*}
\end{subequations}
where $\bm w \coloneqq [w_p]_{p\in[P]} \in \{\bm w \in (0,1)^P \mid \sum_{p\in[P]}w_p = 1\}$ are tunable hyperparameters that affect the performance of the CVaR approximation by prioritising specific constraints within a WJCC. The tunable weights $\bm w$ are proposed by \cite{chen2023approximations}, with standard CVaR having $w_p = 1/P$ for each $p\in[P]$. In the following, we will show that CVaR with $\bm w = \bm 1/P$ has a \emph{projected} feasible region for $\bm x$ that is equivalent to that of the proposed FICA method, given the recommended setting $\bm \kappa=\bm 1$. Our analysis focuses on $\bm x$-space, as the remaining ancillary variables do not appear in the objective function.

Note that for any optimal solution to the CVaR formulation, we can always set $\beta = \max_{p\in[P]} w_p \| \bm b_p - \bm A_p^\top \bm x \|_*$ without affecting optimality (see the proofs of Proposition 11 in \cite{chen2023approximations}). This allows us to eliminate the variable $\beta$ from the CVaR expression as follows:
\begin{subequations}
    \begin{align}
        & \bm \alpha \geq \bm 0, \tau \in \mathbb{R},  \\
        & \tau + \frac{1}{\epsilon} \Big(\theta \max_{p\in[P]} w_p \| \bm b_p - \bm A_p^\top \bm x \|_* + \frac{1}{N} \sum_{i\in [N]} \alpha_i\Big) \leq 0,   \\
        & \alpha_i \geq w_p \Big(\bm a_p^\top \bm x - (\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_i - d_p\Big) - \tau,  \notag \\
        & && \hspace{-97pt}  \forall i\in[N], p\in [P]. 
    \end{align}
\end{subequations}
Let $s = -\tau$ and $\bm r = \bm\alpha$, we reach the following equivalent form for CVaR with the standard $\bm w = \bm 1/P$:
\begin{subequations}\label{eq:cvar-lhs-eq}
    \begin{align}
        & \bm r \geq \bm 0, s \geq 0,  \label{eq:cvar-lhs-eq-s-r}\\
        & \epsilon N s - \sum_{i\in [N]} r_i \geq \theta N \max_{p\in[P]} \| \bm b_p - \bm A_p^\top \bm x \|_* ,   \label{eq:cvar-lhs-eq-epsNs}\\
        & (\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_i - \bm a_p^\top \bm x + d_p \geq s - r_i,   \notag \\ & && \hspace{-97pt} \forall i\in[N], p\in [P], \label{eq:cvar-lhs-eq-main}
    \end{align}
\end{subequations}
Denote the $\bm x$-\emph{feasible} region of CVaR by:
\begin{align*}
    \mathcal{X}_C \coloneqq \{\bm x \mid \exists s, \bm r \ \text{satisfying \eqref{eq:cvar-lhs-eq-s-r}--\eqref{eq:cvar-lhs-eq-main} }\},
\end{align*}
which is the projection of of the feasible region in~\eqref{eq:cvar-lhs-eq} onto the $\bm x$-space.
We then have:
\begin{theorem}\label{theorem:cvar_subeq_fica_exist}
    For any $\bm x \in \mathcal{X}_C$, there exists ($\bm r$, $s$) such that constraints~\eqref{eq:FICA_s_r}--\eqref{eq:FICA_s_str} are satisfied, under $\bm \kappa = \bm 1$.
\end{theorem}
\begin{theorem}\label{theorem:fica_subeq_cvar_all}
    For any $(\bm x, \bm r, s)$ that satisfies the FICA constraints in \eqref{eq:FICA} under $\bm \kappa = \bm 1$, constraints~\eqref{eq:cvar-lhs-eq-s-r}--\eqref{eq:cvar-lhs-eq-main} that define $\mathcal{X}_C$ are satisfied.
\end{theorem}
The proofs are provided in Appendix \ref{appen:proof}. The two theorems above establish the equivalence of the $\bm x$-feasible regions between the proposed FICA and the standard CVaR approximation. Furthermore, the stronger result in Theorem \ref{theorem:fica_subeq_cvar_all}---which holds for $\bm x, \bm r, s$ rather than just $\bm x$ as in Theorem \ref{theorem:cvar_subeq_fica_exist}---implies that the proposed FICA reduces the feasible space for the ancillary variables $\bm r$ and $s$. This reduction is the key to the computational speedup achieved by the proposed FICA.

