\section{Proof}\label{appen:proof}
% \vspace{-1mm}

We start with introducing the following important lemma:
\begin{lemma}\label{lemma:cvar}
    $\mathcal{X}_C$ can be equivalently defined by the emperical CVaR operator $\mathbb{P}_N\mhyphen\mathrm{CVaR_{1-\epsilon}} (\cdot)$ as follows:
    \begin{align}\label{eq:ori_eq}
        \Big\{ \bm x \in \mathcal{X}: \frac{\Theta(\bm x)}{\epsilon} + \mathbb{P}_N\mhyphen\mathrm{CVaR_{1-\epsilon}}(-d(\bm x, \bm\xi)) \leq 0 \Big\},
    \end{align}
    where we have defined
    {\small
    \begin{subequations}
        \begin{align}
            & \mathbb{P}_N\mhyphen\mathrm{CVaR_{1-\epsilon}}(-d(\bm x, \bm\xi)) \coloneqq \nonumber \\
            & \quad \min_{s'} \Big\{ s' + \frac{1}{\epsilon N} \sum\limits_{i \in [N]} \max \{0, -d(\bm x, \bm\xi_i) - s'\} \Big\}, \label{eq:cvar_def} \\
            & d(\bm x, \bm\xi_i) \coloneqq \min_{p\in[P]} \Big\{ d_p(\bm x, \bm\xi_i) \Big\}, \\
            & d_p(\bm x, \bm\xi_i) \coloneqq (\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_i - \bm a_p^\top \bm x + d_p, \\
            & \Theta(\bm x) \coloneqq \theta \max\limits_{p\in[P]} \| \bm b_p - \bm A_p^\top \bm x \|_*.
        \end{align}
    \end{subequations}
    }
\end{lemma}
\begin{IEEEproof}
   \eqref{eq:ori_eq} $\Longrightarrow \mathcal{X}_C$: Similar to Lemma 2 of our previous work \cite{SFLA}, we can assume that $s'$ is selected such that the term $s' + \frac{1}{\epsilon N} \sum_{i \in [N]} \max \{0, -d(\bm x, \bm\xi_i) - s'\}$ inside the CVaR operator \eqref{eq:cvar_def} is minimised. Then, take $r_i^* = \max \{0, -d(\bm x, \bm\xi_i) - s'\}$ (implying $r_i^* \geq 0$). The inequality in~\eqref{eq:ori_eq} indicates the following:
    {\small\begin{equation}\label{eq:right_direction}
         \dfrac{\Theta(\bm x)}{\epsilon} + s' + \frac{1}{\epsilon N} \sum_{i \in [N]} r_i^* \leq 0 
         \Leftrightarrow 
         \epsilon N s' + \sum_{i \in [N]} r_i^* \leq -\Theta(\bm x) N. 
    \end{equation}  }  
    Taking $s^* = -s'$, now we will prove that the tuple $(\bm x, s^*, \bm r^*)$ satisfy all the constraints in $\mathcal{X}_C$, namely \eqref{eq:cvar-lhs-eq-s-r}--\eqref{eq:cvar-lhs-eq-main}, for any $\bm x$ belonging to the set~\eqref{eq:ori_eq}. Since $r_i^* \geq 0$ and $-\Theta(\bm x) N \leq 0$ (because of the non-negativity of dual norm),~\eqref{eq:right_direction} implies:
    \begin{align*}
        \epsilon N s^* - \sum_{i \in [N]} r_i^* \geq \Theta(\bm x) N = \theta N \max_{p\in[P]} \| \bm b_p - \bm A_p^\top \bm x \|_*,
    \end{align*}
    which means~\eqref{eq:cvar-lhs-eq-s-r} and~\eqref{eq:cvar-lhs-eq-epsNs} are satisfied. It remains to prove the satisfaction of~\eqref{eq:cvar-lhs-eq-main}. Based on the setting of $r_i^*$, we have:
    \begin{equation}
    \begin{split}
        s^* - r_i^* & = s^* - \max \Big\{0, -d(\bm x, \bm\xi_i) + s^* \Big\}.
    \end{split}
    \label{eq:s-ri}
    \end{equation}
    Notice that constraint~\eqref{eq:cvar-lhs-eq-main} is equivalent to:
    \begin{equation}
       d(\bm x, \bm\xi_i) \geq s-r_i \quad \forall i\in [N]. \label{eq:ori_main_eq}
    \end{equation}
    When $d(\bm x, \bm\xi_i) \geq s^*$,~\eqref{eq:cvar-lhs-eq-main} must be satisfied for $(\bm x, s^*, \bm r^*)$ due to $r_i^* \geq 0$. When $d(\bm x, \bm\xi_i) < s^*$, we have $s^*-r_i^* =d(\bm x, \bm\xi_i)$ based on~\eqref{eq:s-ri}. Therefore,~\eqref{eq:ori_main_eq} and equivalently~\eqref{eq:cvar-lhs-eq-main} are satisfied.

   \eqref{eq:ori_eq} $\Longleftarrow \mathcal{X}_C$: For any $\bm x$ belonging to the set $\mathcal{X}_C$, by definition there exist $(\bm r, s)$ such that constraints in the set $\mathcal{X}_C$, namely~\eqref{eq:cvar-lhs-eq-s-r}--\eqref{eq:cvar-lhs-eq-main}, are satisfied. Among these constraints,~\eqref{eq:cvar-lhs-eq-main} (equivalently~\eqref{eq:ori_main_eq}) informs that: 
    \begin{align*}
        r_i \geq s - d(\bm x, \bm\xi_i).
    \end{align*}
    Combining with $r_i \geq 0$ in~\eqref{eq:cvar-lhs-eq-s-r}, we further have:
    \begin{align*}
        r_i \geq \max \Big\{0, s - d(\bm x, \bm\xi_i) \Big\}.
    \end{align*}
    Then we have: 
    \begin{align*}
        \epsilon N s - \sum\nolimits_{i \in [N]} r_i \leq \epsilon N s  - \sum\nolimits_{i \in [N]} \max \Big\{0, s - d(\bm x, \bm\xi_i) \Big\}.
    \end{align*}
    Based on constraint \eqref{eq:cvar-lhs-eq-epsNs}, namely $\epsilon N s - \sum\nolimits_{i\in [N]}r_i \geq \Theta(\bm x) N$, we have:
    \begin{align*}
        \epsilon N s  - \sum\nolimits_{i \in [N]} \max \Big\{0, s - d(\bm x, \bm\xi_i) \Big\} \geq \Theta(\bm x) N,
    \end{align*}
    which means:
    \begin{align*}
        \frac{\Theta(\bm x)}{\epsilon} - s + \frac{1}{\epsilon N}\sum\nolimits_{i \in [N]} \max \Big\{0, s - d(\bm x, \bm\xi_i) \Big\} \leq 0.
    \end{align*}
    Now take $s' = -s$, we further have:
    \begin{align*}
        \frac{\Theta(\bm x)}{\epsilon} + s' + \frac{1}{\epsilon N}\sum\nolimits_{i \in [N]} \max \Big\{0, -s' - d(\bm x, \bm\xi_i) \Big\} \leq 0
    \end{align*}
    which leads to:
    \begin{align*}
        \frac{\Theta(\bm x)}{\epsilon} + \min_{s'}\Big\{ s' + \frac{1}{\epsilon N}\sum\nolimits_{i \in [N]} \max\{0, -s' - d(\bm x, \bm\xi_i) \Big\} \leq 0.
    \end{align*}
    Therefore, the constraint in~\eqref{eq:ori_eq} is satisfied.
\end{IEEEproof}

% #######################################################
\vspace{-3 mm}
\subsection*{Proof of Theorem \ref{theorem:cvar_subeq_fica_exist}}
\vspace{-1 mm}

\begin{IEEEproof}
    Notice that the CVaR operator in \eqref{eq:cvar_def} can be equivalently expressed as the following form:  
    {\small
    \begin{subequations}\label{eq:CVaR_optional}
    \begin{align}
    & \mathbb{P}_N\mhyphen\mathrm{CVaR_{1-\epsilon}}(-d(\bm x, \bm\xi)) \\
    = & \min_{s'} \Big\{ s' + \frac{1}{\epsilon N} \sum\nolimits_{i \in [N]} \max \{0, -d(\bm x, \bm\xi_i) - s'\} \Big\} \\
    = & \min_{s'\in \mathbb{R}, \bm r \geq 0} \; s' + \frac{1}{\epsilon N} \sum\nolimits_{i \in [N]} r_{i} \label{eq:CVaR_optional_obj}\\
        &\qquad \mbox{s.t.} \quad  r_{i} \geq -d(\bm x, \bm\xi_i) - s',\quad i\in [N]. \notag
    \end{align}
    \end{subequations}
    }By strong duality of linear programming, we have:
    \begin{equation}\label{eq:CVaR_optional_obj_dual}
        \begin{split}
            \eqref{eq:CVaR_optional_obj} = & \max_{\bm 0\leq \bm y \leq \bm 1} \; -\frac{1}{\epsilon N} \sum\nolimits_{i\in [N]} d(\bm x, \bm\xi_i) y_{i}\\
            & \qquad \mbox{s.t.}\quad \frac{1}{N} \sum\nolimits_{i\in [N]} y_{i} = \epsilon. 
        \end{split}
    \end{equation}  
    Without loss of generality, we assume the following ordering $d(\bm x, \bm\xi_1) \leq \cdots \leq d(\bm x, \bm\xi_N)$.
    Then a primal-dual optimal pair for the problems \eqref{eq:CVaR_optional_obj} and \eqref{eq:CVaR_optional_obj_dual} is given by:
    {\small
    \begin{subequations}\label{eq:s_r_y_pri_dual}
        \begin{align}
           & s'^* = -d(\bm x, \bm\xi_{k+1}), \\
           & r_{i}^* = \max\{ 0, -d(\bm x, \bm\xi_i) - s'^* \}, \label{eq:r_pri_dual} \\
           & y_{i}^* = 
            \begin{cases} 
              1, & i = 1, \cdots, k \\
              \epsilon N - k, & i=k+1 \\
              0, & i > k+1.
           \end{cases} 
        \end{align}
    \end{subequations}       
    }The validity of the above primal-dual optimal pair holds because of the satisfaction of primal and dual constraints and the equality of the objectives of the primal and dual problems:
    \begin{align*}\label{eq:CVaR_primal_dual}
        -\frac{1}{\epsilon N} \sum\nolimits_{i\in [N]} d(\bm x, \bm\xi_i) y_{i}^*
        = s'^* + \frac{1}{\epsilon N} \sum\nolimits_{i \in [N]} r_{i}^*,
    \end{align*}
    which holds because of: 
    {\small \begin{align*}
        & -\frac{1}{\epsilon N} \sum\nolimits_{i\in [N]} d(\bm x, \bm\xi_i) y_{i}^* \\
        = &
        -\frac{1}{\epsilon N} \Big( \sum\nolimits_{i\in [k]} d(\bm x, \bm\xi_i) + d(\bm x, \bm\xi_{k+1}) (\epsilon N - k) \Big) \\
        = & -d(\bm x, \bm\xi_{k+1}) - \frac{1}{\epsilon N} \Big( \sum\nolimits_{i\in [k]} d(\bm x, \bm\xi_i) - k\cdot d(\bm x, \bm\xi_{k+1}) \Big)
    \end{align*}}and
    {\small \begin{align*}
        & s'^* + \frac{1}{\epsilon N} \sum\nolimits_{i \in [N]} r_{i}^* \\
        = & -d(\bm x, \bm\xi_{k+1}) + \frac{1}{\epsilon N} \sum_{i \in [N]} \max\{ 0, -d(\bm x, \bm\xi_i) + d(\bm x, \bm\xi_{k+1}) \} \\
        = & -d(\bm x, \bm\xi_{k+1}) + \frac{1}{\epsilon N} \sum\nolimits_{i \in [k]} \Big( -d(\bm x, \bm\xi_i) + d(\bm x, \bm\xi_{k+1}) \Big) \\
        = & -d(\bm x, \bm\xi_{k+1}) - \frac{1}{\epsilon N} \Big( \sum\nolimits_{i\in [k]} d(\bm x, \bm\xi_i) - k\cdot d(\bm x, \bm\xi_{k+1}) \Big),
    \end{align*}}where the second equality holds because of $d(\bm x, \bm\xi_{k+1})-d(\bm x, \bm\xi_i)\leq 0$ for $i\geq k+1$.

    Given the primal-dual analysis of the CVaR operator \eqref{eq:cvar_def} and Lemma \ref{lemma:cvar}, for any $\bm x \in \mathcal{X}_C$, we have:
    {\small
    \begin{subequations}       
        \begin{align}
            & \frac{\Theta(\bm x)}{\epsilon} + \mathbb{P}_N\mhyphen\mathrm{CVaR_{1-\epsilon}}(-d(\bm x, \bm\xi)) \leq 0 \\
            \Leftrightarrow \quad
            & \frac{\Theta(\bm x)}{\epsilon} + s'^* + \frac{1}{\epsilon N} \sum\nolimits_{i\in [N]} r_i^* \leq 0 \\
            \Leftrightarrow \quad 
            & \epsilon N s'^* + \sum\nolimits_{i\in[N]} r_i^* \leq -\Theta(\bm x) N. \label{eq:derive}
        \end{align}
    \end{subequations}   
    }Eq.~\eqref{eq:derive} informs us that $s'^* \leq 0$, due to the non-negativity of $\Theta(\bm x)$ and $r_i$ (based on \eqref{eq:r_pri_dual}).
    Now let us define $s^* \coloneqq -s'^* \geq 0$, \eqref{eq:derive} further indicates 
    {\small
    \begin{equation*}
        \epsilon N s^* - \sum\nolimits_{i \in [N]} r_i^* \geq \Theta(\bm x) N = \theta N \max\limits_{p\in[P]} \| \bm b_p - \bm A_p^\top \bm x \|_*,
    \end{equation*}
    }As $r_i^* \geq 0$, we have proved that constraints~\eqref{eq:FICA_s_r} and~\eqref{eq:FICA_epsilonNs} are satisfied. It remains to prove the satisfaction of~\eqref{eq:FICA_main}--\eqref{eq:FICA_s_str}. 
    For \eqref{eq:FICA_main} and \eqref{eq:FICA_main2}, we can even prove their stronger version, namely \eqref{eq:cvar-lhs-eq-main}. Based on the setting of $r_i^*$ in~\eqref{eq:r_pri_dual} and the definition $s^* \coloneqq -s'^* \geq 0$, we have: 
    \begin{equation}
        \label{eq:s-r}
        \begin{split}
            s^* - r_i^* & = s^* - \max \{0, -d(\bm x, \bm\xi_i) + s^*\}.
        \end{split}
    \end{equation}
    Recall that constraint~\eqref{eq:cvar-lhs-eq-main} is equivalent to the following (see~\eqref{eq:ori_main_eq}):
    \vspace{-3mm}
    \begin{align*}
       d(\bm x, \bm\xi_i) \geq s-r_i \quad i\in [N].
    \end{align*}
    When $d(\bm x, \bm\xi_i) \geq s^*$,~\eqref{eq:cvar-lhs-eq-main} must be satisfied due to $r_i^* \geq 0$. When $d(\bm x, \bm\xi_i) < s^*$, the inequality \eqref{eq:s-r} informs that $s^*-r_i^* = d(\bm x, \bm\xi_i)$, so~\eqref{eq:cvar-lhs-eq-main} is also satisfied; thus \eqref{eq:FICA_main} and \eqref{eq:FICA_main2} are satisfied. Therefore, we have proved that the pair $(\bm x, s^*, \bm r^*)$ satisfies constraints \eqref{eq:FICA_s_r}--\eqref{eq:FICA_main2}, with $s^* = -s'^* = d(\bm x, \bm\xi_{k+1})$ and $r_i^* = \max\{ 0, -d(\bm x, \bm\xi_i) + s^* \}$. Finally, based on our assumed ordering, $s^* = d(\bm x, \bm\xi_{k+1})$ is the $(k+1)$-th smallest value amongst $\{d(\bm x, \bm\xi_i)\}_{i\in [N]}$. Then for any $p\in [P]^*$, when $i\geq k+1$, we have:
    \begin{align*}
        s^*  = d(\bm x, \bm\xi_{k+1}) \leq d(\bm x, \bm\xi_i) =  \min_{p\in [P]} d_p(\bm x, \bm\xi_i)
        \leq  d_p(\bm x, \bm\xi_i).
    \end{align*}
    In other words, for any $p \in [P]^*$, there will be at least $N-k$ elements in the set $\{ d_p(\bm x, \bm\xi_i) \}_{i\in [N]}$ not less than $s^*$. Since $q_p(\bm x)$ is defined as the $(k+1)$-th smallest value of the set $\{ (\bm b_p - \bm A_p^\top \bm x)^\top \bm \xi_i \}_{i\in[N]}$, the term $q_p(\bm x) + d_p - \bm a_p^\top \bm x$ is the $(k+1)$-th smallest value of $\{ d_p(\bm x, \bm\xi_i) \}_{i\in[N]}$, and thus we must have:
    \begin{align*}
        s^* \leq q_p(\bm x) + d_p - \bm a_p^\top \bm x,\ \forall p\in[P]^*,
    \end{align*}
    which indicates the satisfaction of~\eqref{eq:FICA_s_str}.
\end{IEEEproof}

% \vspace{-4 mm}
\subsection*{Proof of Theorem \ref{theorem:fica_subeq_cvar_all}}
\begin{IEEEproof}
    First, it is apparent that constraints \eqref{eq:cvar-lhs-eq-s-r} and \eqref{eq:cvar-lhs-eq-epsNs} are always satisfied for any $(\bm x, \bm r, s)$ that satisfies the FICA constraints in \eqref{eq:FICA}. It remains to prove the satisfaction of \eqref{eq:cvar-lhs-eq-main}.
    Based on the definition of $[N]_p$, we have:
    \begin{equation*}
        d_p(\bm x, \bm\xi_i) \geq q_p(\bm x) + d_p - \bm a_p^\top \bm x, \quad \forall i \in [N] \setminus [N]_p,\ p\in [P].
    \end{equation*}
    Therefore, constraint~\eqref{eq:FICA_s_str} implies that for any $i \in [N] \setminus [N]_p$ with $p\in [P]^*$, we have $d_p(\bm x, \bm\xi_i) \geq q_p(\bm x) + d_p - \bm a_p^\top \bm x \geq s$.
    As $r_i \geq 0$, we further have $d_p(\bm x, \bm\xi_i) \geq s - r_i$,
    which, combined with~\eqref{eq:FICA_main} and \eqref{eq:FICA_main2}, implies the satisfaction of~\eqref{eq:cvar-lhs-eq-main}.
\end{IEEEproof}

