\noindent\textbf{Kinematic Loss.} To enhance the physical plausibility of generated motions, we incorporate several auxiliary losses commonly used in kinematic motion generation. In addition to the basic reconstruction loss $\mathcal{L}_{\mathrm{simple}}$, we adopt auxiliary terms introduced by Tevet et al.\cite{tevet2022human} and further refined in EDGE\cite{tseng2023edge}, targeting three key aspects of motion realism: joint positions (Eq. \ref{eq:loss_joint}), joint velocities (Eq. \ref{eq:loss_vel}), and foot-ground contact consistency (Eq. \ref{eq:loss_contact}). Below, $\mathbf{FK(\cdot)}$ denotes the forward kinematic function that converts joint angles into joint positions and the $\mathit{i}$-th superscript denotes the frame index. We note Eq. \ref{eq:loss_contact} only applies to the foot joints, and $\mathbf{\hat{b}}_i$ is binary foot contact signal.
%Auxiliary losses are commonly used in kinematic motion generation settings to improve physical realism in the absence of true simulation. In addition to the reconstruction loss $\mathcal{L}_{\mathrm{simple}}$, we adopt auxiliary losses similar to those in Tevet et al. \cite{tevet2022human} to encourage matching three aspects of physical realism: joint positions (Eq. \ref{eq:loss_joint}), velocities (Eq. \ref{eq:loss_vel}), and foot velocities following the contact consistency loss (Eq. \ref{eq:loss_contact}) in EDGE \cite{tseng2023edge}. Below, $\mathbf{FK(\cdot)}$ denotes the forward kinematic function that converts joint angles into joint positions and the $\mathit{i}$-th superscript denotes the frame index.  We note Eq. \ref{eq:loss_contact} only applies to the foot joints. 
\begin{equation}
  \mathcal{L}_{\mathrm{joint}} = 
  \frac{1}{\mathit{N}}
  \sum^{\mathit{N}}_{i=1}
  \parallel\mathbf{FK}(\mathbf{x}_i) - \mathbf{FK}(\mathbf{\hat{x}}_i)\parallel^{2}_{2}
  \label{eq:loss_joint}
\end{equation}

% \begin{equation}
%   \mathcal{L}_{\mathrm{vel}} = 
%   \frac{1}{\mathit{N}-1}
%   \sum^{\mathit{N}-1}_{i=1}
%   \parallel(\mathit{x}^{(i+1)}-\mathit{x}^{(i)}) - (\mathit{\hat{x}}^{(i+1)}-\mathit{\hat{x}}^{(i)})\parallel^{2}_{2}
%   \label{eq:loss_vel}
% \end{equation}
\begin{equation}
  \mathcal{L}_{\mathrm{vel}} = 
  \frac{1}{\mathit{N}-1}
  \sum^{\mathit{N}-1}_{i=1}
  \parallel(\mathbf{x}_{i+1}-\mathbf{x}_{i}) - (\mathbf{\hat{x}}_{i+1}-\mathbf{\hat{x}}_{i})\parallel^{2}_{2}
  \label{eq:loss_vel}
\end{equation}
% \begin{equation}
%   \mathcal{L}_{\mathrm{contact}} = 
%   \frac{1}{\mathit{N}-1}
%   \sum^{\mathit{N}-1}_{i=1}
%   \parallel(\mathit{FK}(\mathit{x}^{(i+1)})-\mathit{FK}(\mathit{\hat{x}}^{(i)}))\cdot\mathit{\hat{b}^{(i)}}\parallel^{2}_{2}
%   \label{eq:loss_contact}
% \end{equation}
\begin{equation}
  \mathcal{L}_{\mathrm{contact}} = 
  \frac{1}{\mathit{N}-1}
  \sum^{\mathit{N}-1}_{i=1}
  \parallel(\mathbf{FK}(\mathbf{x}_{i+1})-\mathbf{FK}(\mathbf{\hat{x}}_i))\cdot\mathbf{\hat{b}}_i\parallel^{2}_{2}
  \label{eq:loss_contact}
\end{equation}

\noindent\textbf{Multi-modal Alignment Loss.}
To bridge the semantic gap between music and motion, we design a multi-modal alignment loss function that leverages text as an intermediate modality. Unlike traditional approaches that directly align music and motion, our method calculates similarity between \textit{motion-text} and \textit{text-music} pairs at each timestep $\mathit{t}$ in the diffusion process. By using text as a common semantic space, we allow the model to capture descriptive and interpretable features that relate both to the audio’s rhythmic and tonal characteristics and to the motion’s dynamic and stylistic attributes. Specifically, for each timestep, we compute cosine similarity between motion and text embeddings and text and music embeddings, promoting alignment across all three modalities through the text-based intermediary. The total alignment loss is defined as Eq. \ref{eq:loss_mm}, encouraging consistent semantic alignment between music and motion via the shared text representation. %This alignment loss is then combined with the kinematic losses, weighted by a factor $\lambda_{\text{cosine}}$.
%, to ensure that the generated dance movements are rhythmically synchronized with the music and semantically coherent with the provided dance instructions. This approach effectively reduces the semantic gap between music and motion, producing dance movements that are both musically aligned and contextually meaningful.

\begin{equation}
  \mathcal{L}_{\mathrm{align}} = 
  \frac{1}{\mathit{N}}
  \sum^{\mathit{N}}_{i=1}
  [(1-\mathrm{sim}(E_{t_i}, E_{m_i})) + (1-\mathrm{sim}(E_{t_i}, E_{x_i}))]
  \label{eq:loss_mm}
\end{equation}
This alignment loss is then combined with the other auxiliary losses, weighted by factors $\lambda$ to balance the magnitudes of the losses at the start of training.

\begin{equation}
\begin{split}
  \mathcal{L} & = \mathcal{L}_{\mathrm{simple}} + \lambda_{\mathrm{joint}}\mathcal{L}_{\mathrm{joint}} + \lambda_{\mathrm{vel}}\mathcal{L}_{\mathrm{vel}} + \\
  &\lambda_{\mathrm{contact}}\mathcal{L}_{\mathrm{contact}} + \lambda_{\mathrm{align}}\mathcal{L}_{\mathrm{align}}
\end{split}
  \label{eq:loss_all}
\end{equation}


