		\centering
		\begin{tikzpicture}[scale=0.5]
			\node (u1) {$1$};
			\node (u2) [right=0cm of u1] {$2$};
			\node (u3) [right=0cm of u2] {$3$};
			\node (u4) [right=0cm of u3] {$4$};
			\node (u5) [right=0cm of u4] {$5$};
			\node (u6) [right=0cm of u5] {$6$};
			\node (u7) [right=0cm of u6] {$7$};
