	In particular, one can view every primitive $\pi$-clustering word $w \in \A^*$ as a DIET associated with the composition $\Psi_{\A}(w)$ of $|w|$ and the permutation $\pi$, the permutation $\mu$ describing the action of such a DIET being circular (see~\cite{FerencziZamboni13} for a characterization of $\pi$-clustering words in terms of trajectories in IETs or DIETs).




	\section{Rauzy Induction}
	\label{sec:Rauzy}

	Let $\A = \{ a_1 < \ldots < a_d \}$ and $\pi$ a permutation of $\A$.
	Let $T$ be an IET over $[\ell, r)$ associated with $(I_a)_{a \in \A}$ and $\pi$.
	The \emph{transformation induced} by $T$ on a subinterval $J \subset I$ is the map $T': J \to J$ defined by $T'(z) = T^{\nu(z)} (z)$, where $\nu(z) = \min \{ n>0 \; | \; T^n(z) \in J \}$ is the \emph{first return map} of $T$ to $J$.
	Note that $\nu(z)$ is well-defined because IETs do not have wandering intervals (see, e.g.,~\cite{FerencziHubertZamboni24}).

	Rauzy induction is a procedure that associates to a regular IET $T$ associated with an alphabet $\A$, a sequence of regular IETs associated with the same reordered alphabet.

	The \emph{right Rauzy step}, is the mapping $\rho$ sending $T$ to the induced transformation $T'$ on $[\ell, r')$, where $r'$ is the rightmost between the points in $D(T) \cup D(T^{-1})$.
	Since $T$ is regular, it has no $0$-connections and $|I_{a_d}| \ne |I_{a_{\pi(d)}}|$.
	Moreover, since $\pi$ is irreducible we have $\pi(a_d) \ne a_d$.

	If $|I_{a_d}| > |I_{a_{\pi(d)}}|$ then $\Omega(x)$ starts with $a_{\pi(d)} a_d$ for every $x \in I_{a_{\pi(d)}}$; if $|I_{a_d}| < |I_{a_{\pi(d)}}|$ then $\Omega(x)$ starts with $a_{\pi(d)} a_d$ for every $x \in T^{-1}(I_{a_d})$.
	We can actually give a more precise description of the obtained induced intervals: in one case the order given by the alphabet stays the same while the one given by the permutation change, while in the other case the opposite happens.
	Recall that we identify $S_\A$ with $S_d$ when no confusion arises.

	\begin{lemma}
		\label{lem:rho}
		Let $T$ be a regular IET associated with $\A = \{ a_1 < \ldots < a_d \}$ and $\pi \in S_\A$.
		Let $h = \pi^{-1}(d)$.
		If $|I_{a_d}| > |I_{a_{\pi(d)}}|$, then $\rho(T)$ is the regular IET associated with $\A$ and $\pi' \in S_\A$ defined as
		$$
		\pi'(i) =
		\left\{
		\begin{array}{ll}
			\pi(i) & \quad {\rm if  } \quad i \le h \\
			\pi(d) & \quad {\rm if } \quad i = h+1 \\
			\pi(i)+1 & \quad {\rm if } \quad i > h+1
		\end{array}
		\right..
		$$

		If $|I_{a_d}| < |I_{a_{\pi(d)}}|$, then $\rho(T)$ is the regular IET associated with
		$$
		\A' = \{ a_1 < \ldots < a_h < a_d < a_{h+1} < \ldots < a_{d-1} \}
		$$
		and $\pi \in \A'$ defined as $\pi'(i) = \pi(i)$ for every $i$.
	\end{lemma}
	\begin{proof}
		Let $S = \rho(T)$.
		If $I_{a_d}$ is longer than $I_{a_{\pi(d)}}$, then the domain of $S$ is partitioned by $(I'_a)_{a \in \A}$, where all $I'_a = I_a$ but $I'_{a_d}$, which is cut of its final part.
		The first return map of $T$ into the domain of $S$ is given by $T^2(z)$ if $z \in I_{a_{\pi(d)}}$ and $T(z)$ elsewhere.
		Thus, $T(I_{a_d})$ is split into $S(I_{a_d})$ and $S(I_{a_{\pi(d)}})$.

		If $I_{a_d}$ is shorter than $I_{a_{\pi(d)}}$, then $S$ is defined as $T^2(z)$ if $z \in T^{-1}(I_{a_d})$ and $T(z)$ elsewhere.
		Thus, the subinterval $I_{a_{pi(d)}}$ for $T$ is split into $I'_{a_{\pi(d)}}$ and $I'_{a_d}$ in the partition associated with $S$.
		The interval $S(I'_{\pi(d)})$ will remain the rightmost (even though is smaller then $T(I_{\pi(d)})$), so the permutation does not change.
	\end{proof}

	The \emph{left Rauzy step} $\lambda$ is defined in a symmetric way considering the interval $[\ell', r)$, where $\ell' \ne \ell$ is the leftmost between the points in $D(T) \cup D(T^{-1})$ and the intervals considered are $I_{a_1}$ and $I_{\pi(a_1)}$.

	A symmetrical version of Lemma~\ref{lem:rho} holds.

	\begin{lemma}
		\label{lem:lambda}
		Let $T$ be a regular IET associated with $\A = \{ a_1 < \ldots < a_d \}$ and $\pi \in S_\A$.
		Let $h = \pi^{-1}(1)$.
		If $|I_{a_1}| > |I_{a_{\pi(1)}}|$, then $\lambda(T)$ is the regular IET associated with $\A$ and $\pi' \in S_\A$ defined as
		$$
		\pi'(i) =
		\left\{
		\begin{array}{ll}
			\pi(i)-1 & \quad {\rm if } \quad i < h-1 \\
			\pi(1) & \quad {\rm if } \quad i = h-1 \\
			\pi(i) & \quad {\rm if } \quad i \le h
		\end{array}
		\right. .
		$$

		If $|I_{a_1}| < |I_{a_{\pi(1)}}|$, then $\lambda(T)$ is the regular IET associated with
		$$
		\A' = \{ a_2 < \ldots < a_{h-1} < a_1 < a_h < \ldots < a_d \}
		$$
		and $\pi \in \A'$ defined as $\pi'(i) = \pi(i)$ for every $i$.
	\end{lemma}

	In~\cite{branching} it is shown that if $T$ is a regular IET, then for every $w \in \LL(T)$ the transformation induced by $T$ on $I_w$ is of the form $\chi(T)$, with $\chi \in \{ \rho, \lambda \}^*$, where each morphism corresponds to a Rauzy step.

	The following result is a consequence of Propositions 3.15, 4.12, 4.14 and Theorem 4.15 in~\cite{branching}.\footnote{The result being separated in several statements in~\cite{branching}, the authors managed to avoid using multiple indexes as it is done here.}

	\begin{proposition}[\cite{branching}]
		\label{pro:Iw}
		Let $T$ be a regular IET and $w \in \LL(T)$.
		The transformation induced by $T$ on $I_w$ is of the form $\chi(T)$, where $\chi \in \{ \rho, \lambda \}^*$.
		Moreover, let $\chi = \chi_n \circ \cdots \circ \chi_1$.
		Then the morphism $\theta = \theta_1 \circ \cdots \circ \theta_n$ is an automorphism of the free group sending $\A$ to $\R(w)$, where
		$$
		\theta_i =
		\left\{
		\begin{array}{ll}
			\alpha_{\pi(a^{(i)}_d),a^{(i)}_d} & \quad {\rm if } \quad \chi_i = \rho \quad {\rm  and } \quad |I_{a^{(i)}_d}| > |I_{\pi(a^{(i)}_d)}| \\
			\tilde{\alpha}_{a^{(i)}_d,\pi(a^{(i)}_d)} & \quad {\rm if } \quad \chi_i = \rho \quad {\rm and } \quad |I_{a^{(i)}_d}| < |I_{\pi(a^{(i)}_d)}| \\
			\alpha_{\pi(a^{(i)}_1),a^{(i)}_1} & \quad {\rm if } \quad \chi_i = \lambda \quad {\rm and } \quad |I_{a^{(i)}_1}| > |I_{\pi(a^{(i)}_1)}| \\
			\tilde{\alpha}_{a^{(i)}_1,\pi(a^{(i)}_1)} & \quad {\rm if } \quad \chi_i = \lambda \quad {\rm and } \quad |I_{a^{(i)}_1}| < |I_{\pi(a^{(i)}_1)}|
		\end{array}
		\right.
		$$
		and $\{ a^{(i)}_1 < \cdots < a^{(i)}_d \}$ is the alphabet associated to $\chi_i \circ \cdots \circ \chi_1(T)$.
	\end{proposition}





	\section{Rauzy Steps and Morphisms}

	In order to prove Theorem~\ref{thm:main}, we use the morphisms defined in Section~\ref{sec:preliminaries}\ to step back from $I_w$ to $[\ell, r)$.

	Let us show that under certain additional conditions, clustering is preserved by these morphisms.

	\begin{lemma}
		\label{lem:clustering}
		Let $w$ be a primitive word over $\A = \{a_1 < \ldots < a_d \}$.
		Suppose $w$ is $\pi$-clustering on $\A$ for some permutation $\pi$.
		\begin{enumerate}
			\item Let $\mu \in S_\A$ be a permutation.
			Then $\mu(w) \in \A'^*$ is $\pi'$-clustering, with $\A' = \{ \mu(a_1) < \ldots < \mu(a_d) \}$ and $\pi' \in S_{\A'}$.

			\item If $b = a_1$, $\pi^{-1}(a) = a_i$ and $\pi^{-1}(b) = a_{i+1}$ with $1 \le i < d$, then $\alpha_{a,b}(w) \in \A^*$ is $\pi'$-clustering, for a certain $\pi' \in S_\A$.

			\item If $b = a_d$, $\pi^{-1}(b) = a_i$ and $\pi^{-1}(a) = a_{i+1}$ with $1 \le i < d$, then $\alpha_{a,b}(w) \in \A^*$ is $\pi'$-clustering, for a certain $\pi' \in S_\A$.

			\item If $\pi^{-1}(b) = a_1$, $a=a_i$ and $b=a_{i+1}
			$ with $1 \le i < d$, then $\tilde{\alpha}_{a,b}(w) \in \A'^*$ is $\pi'$-clustering, for a certain $\pi' \in S_{\A'}$, where $\A' = \{a_i < a_1 < \ldots < a_{i-1} < a_{i+1} < \ldots < a_d \}$.

			\item If $\pi^{-1}(b) = a_d$, $b=a_i$ and $a=a_{i+1}$ with $1 \le i < d$, then $\tilde{\alpha}_{a,b}(w) \in \A'^*$ is $\pi'$-clustering, for a certain $\pi' \in S_{\A'}$, where $\A' = \{a_1 < \ldots < a_i < a_{i+2} < \ldots < a_d < a_{i+1} \}$.
		\end{enumerate}
	\end{lemma}

	\begin{proof}
		We proceed by addressing each case.
		\begin{enumerate}
			\item Since $w$ is $\pi$-clustering, $\bwt{\A}{w}$ consists of contiguous blocks - possibly of length $0$, if $w$ is not pangrammatic - of each letter of $\A$.
			Since an application of $\mu$ to $w$ simply amounts to letter renaming, we immediately obtain clustering of $\mu (w)$. Defining $\pi' = \mu \circ \pi \circ \mu^{-1} \in S_{\A'}$, via elementary permutation properties we see that $w$ is $\pi'$-clustering.

			\item Define $\pi' \in S_{\A}$ by altering $\pi$ such that $\pi^{-1} (a)$ and $\pi^{-1} (b)$ are adjacent in the cycle. If $\pi^{-1} (a) = a_i$ and $\pi^{-1} (b) = a_{i+1}$, then the blocks $\pi (a)$ and $\pi (b)$ appear consecutively in $\bwt{\A}{w}$.
			Replacing each $a$ by $ab$ in $w$ connects the blocks $\pi (a)$ and $\pi (b)$ into a single-block adjacency in $\bwt{\A}{\alpha_{a,b} (w)}$. Thus, $\alpha_{a,b} (w)$ is $\pi'$ clustering.

			\item This proof is identical to that of the second argument.

			\item We have $\pi(a_1) = b$. We define $\A' = \{a_i < a_1 < \ldots < a_{i-1} < a_{i+1} < \dots <a_d \}$ so that $a$ is the new smallest letter in $\A'$ with $b$ appearing later.
			Now let $\pi' \in S_{\A'}$ be the permutation such that $a$ is treated as the first letter and $b$ follows it somewhere in the cycle.
			Applying $\tilde{\alpha}_{a,b}$ to $w$ replaces every $a$ in $w$ with $ba$.
			In the Burrows-Wheeler transform, this forces the blocks of $\pi (a)$ and $\pi (b)$ to be contiguous.
			On the new order $\A'$ and under permutation $\pi'$, we immediately obtain the clustering via elementary Burrows-Wheeler transform properties.

			\item Let $\A' = \{ a_1 < \dots < a_i < a_{i+2} < \ldots < a_d < a_{i+1} \}$ so that $a$ is the largest letter of $\A'$.
			We define $\pi' \in S_{\A'}$ so that $\pi' (a_d) = b$ and $\pi' (b)$ such that $\pi' (b)$ sits next to $\pi' (a)$.
			Replacing $a$ by $ba$ again merges the blocks of $\pi(a)$ and $\pi(b)$ contiguously in the Burrows-Wheeler transform of $w$ over $\A'$.
			Thus, $\tilde{\alpha}_{a,b} (w)$ is $\pi'$-clustering.
		\end{enumerate}
	\end{proof}





	We are now able to prove our main result.

	\begin{proof}[of Theorem~\ref{thm:main}]
		Let $T$ be a regular IET and $w \in \LL(T)$.
		By Proposition~\ref{pro:Iw} there exist $\chi_1, \ldots, \chi_n \in \{ \rho, \lambda \}$ such that $\chi_n \circ \cdots \circ \chi_1(T)$ is the IET induced by $T$ on $I_w$.
		From the same proposition we obtain a morphism $\theta_i$ for each $1 \le i \le n$.

		By Lemmata~\ref{lem:rho} and~\ref{lem:clustering}, $\theta_i$ sends a clustering word in $\LL(\chi_{i-1} \circ \cdots \circ \chi_1(T))$ to a clustering word in $\LL(\chi_i \circ \cdots \circ \chi_1(T))$.
		Thus, by induction on $n$, $\theta(u)$ is clustering for every clustering word $u \in \LL(T)$.

		Since every letter is trivially clustering and $\R(w) = \{ \theta(a) \, | \, a \in \A \}$, we can conclude.
	\end{proof}

	\begin{example}
		\label{ex:krokzakrokem}
		Let $T$ be the IET associated with the alphabet $\{ {\tt a} < {\tt b} < {\tt c} \}$ and the permutation $\pi = ({\tt b,c,a})$, with $|I_{\tt a}| = 1-2\alpha$, $|I_{\tt b}| = |I_{\tt c}| = \alpha$, where $\alpha = \frac{3-\sqrt{5}}{2}$.
