		\alpha_{{\tt a},{\tt c}} \circ
		\tilde{\alpha}_{{\tt c},{\tt a}} \circ
		\tilde{\alpha}_{{\tt a},{\tt b}} \circ
		\tilde{\alpha}_{{\tt c},{\tt b}}$.
	\end{example}

