	\begin{proposition}
		\label{pro:multiclustering}
		If a multiset $W \subset \A^*$ is $\pi$-clustering, then every $w \in W$ is $\pi_w$-clustering, with $\pi_w$ the restriction of $\pi$ to the letters appearing in $w$.
	\end{proposition}
	\begin{proof}
		The result easily follows by considering the DIET associated with $W$ and noticing that each word $w \in W$ corresponds to exactly one orbit of the DIET.
	\end{proof}

	Note that the opposite of Proposition~\ref{pro:multiclustering} is not true.

	\begin{example}
		\label{ex:multinonclustering}
		Let $\A = \{ {\tt a} < {\tt b} \}$.
		The words $w_1 = {\tt ab}, w_2 = {\tt aab}$ are $\pi$-clustering with $\pi = ({\tt ba})$.
		The  multiset $W = \{ w_1, w_2 \}$ is not clustering since
		$\ebwt{\A}{W} = {\tt babaa}$.
		Note also that $\LL(W^\omega) = \LL(w_1^\omega) \cup \LL(w_2^\omega)$ is not ordered dendric as one can easily check by considering $\G(\varepsilon)$, $\G({\tt a})$ and $\G({\tt aba})$ (see Figure~\ref{fig:multinonclustering}).
