Let the coordinates of the end effector in the $\Sigma_0$ coordinate system be $(x,y,z)$, and the transformation matrix from the $\Sigma_8$ coordinate system to the $\Sigma_0$ coordinate system be
$T = {}^{0}T_1 {}^{1}T_2 {}^{2}T_3 {}^{3}T_4 {}^{4}T_5 {}^{5}T_6 {}^{6}T_7 {}^{7}T_8.$
Since the end effector is located at the origin of the $\Sigma_8$ coordinate system, the coordinates of the end effector in the $\Sigma_0$ coordinate system can be expressed as
\begin{align}
  \label{eq:forward-kinematics}
  \left(
    \begin{array}{c}
      x \\ y \\ z \\ 1
    \end{array}
  \right)
  = T
  \left(
  \begin{array}{c}
    0 \\ 0 \\ 0 \\ 1
  \end{array}
  \right).
\end{align}
By expressing $s_i=\sin{\theta_i}$ and $c_i=\cos{\theta_i}$ for $i=1,3,4$, 
\cref{eq:forward-kinematics} can be rewritten as
\begin{equation}
  \label{eq:forward-kinematics-formula}
  \begin{split}
    -169.18s_1s_3c_4 -169.18s_1c_3s_4 -43.6s_1s_3s_4 +43.6s_1c_3c_4 \quad & \\
    -110.4s_1s_3 -66.39c_1 +x &= 0,\\
    169.18c_1s_3c_4 +169.18c_1c_3s_4 +43.6c_1s_3s_4 -43.6c_1c_3c_4 \quad  & \\
    +110.4c_1s_3 -66.39s_1 +y &= 0, \\
    -169.18c_3c_4 +169.18s_3s_4 -43.6c_3s_4 -43.6s_3c_4  \quad & \\
     -110.4c_3 - 131.56 +z&= 0, \\
    s_1^2 + c_1^2 - 1 = 0, \quad s_3^2 + c_3^2 - 1 = 0, \quad s_4^2 + c_4^2 - 1 &= 0.
  \end{split}
\end{equation}

In the following, for a set of polynomials $F=\{f_1,\dots,f_m\}\subset \R[c_1,s_1,c_3,s_3,c_4,s_4]$, The system of polynomial equations $f_1=\cdots=f_m=0$ is denoted by $F=0$.
Since the first, second, and third equations of \cref{eq:forward-kinematics-formula} contain decimal coefficients, both sides of these equations are actually multiplied by 100.
Thus, we obtain the inverse kinematic problem as the one to find the solution $c_1,s_1,c_3,s_3,c_4,s_4$ to the system of polynomial equations $F=0$ with $F=\{f_1,\dots,f_6\}$, where
\begin{equation}
  \label{eq:inverse-kinematics-formula}
  \begin{split}
  f_1&=-16918s_1s_3c_4 -16918s_1c_3s_4 -4360s_1s_3s_4 +4360s_1c_3c_4 -11040s_1s_3\\
  &\quad -6639c_1 +100x,\\
  f_2&=16918c_1s_3c_4 +16918c_1c_3s_4 +4360c_1s_3s_4 -4360c_1c_3c_4 +11040c_1s_3\\
  &\quad -6639s_1 +100y,\\
  f_3&=-16918c_3c_4 +16918s_3s_4 -4360c_3s_4 -4360s_3c_4 -11040c_3\\
  &\quad - 13156 +100z,\\
  f_4&=s_1^2 + c_1^2 - 1,\quad f_5=s_3^2 + c_3^2 - 1,\quad f_6=s_4^2 + c_4^2 - 1.
  \end{split}
\end{equation}
Note that the system of equations $F=0$ has parameters $x,y,z$ in the coefficients.

The inverse kinematic problem is solved as follows.
With our previously proposed method \cite[Algorithm 1]{yos-ter-mik2023}, 
before solving $F=0$, we calculate the CGS of $\ideal{f_1,\dots,f_6}$.
Then, for a given end-effector coordinate $(x,y,z)=(\alpha,\beta,\gamma)\in\R^3$,
determine the feasibility of such a configuration using the CGS-QE method.
If the configuration is feasible, we solve $F=0$ numerically after substituting parameters $x,y,z$ with $\alpha,\beta,\gamma$, respectively, to obtain the inverse kinematic solution.

\section{Path and trajectory planning using spline interpolation}
\label{sec:spline-interpolation}

% \subsection{Generating trajectories using cubic spline interpolation}

In the path planning problem, a finite number of points through which the path passes are given in advance, and a trajectory is generated on the smooth path passing through these points.
While a straight line was used as the path in our previous study, 
a path is generated using cubic spline interpolation \cite{far2002} in the present paper.

\subsection{Path planning using cubic spline interpolation}

Let $(x_0,y_0,z_0)$, $(x_1,y_1,z_1)$, $(x_2,y_2,z_2)$, $(x_3,y_3,z_3)$ be four different points given in $\R^3$.
For $j=0,1,2$, calculate a curve $C_j$ passing through 
$(x_j,y_j,z_j)$ and $(x_{j+1},y_{j+1},z_{j+1})$
in the form of a function $(X_j(s),Y_j(s),Z_j(s))$ with $s\in[0,1]$ as a parameter.
In cubic spline interpolation, $X_j(s),Y_j(s),Z_j(s)$ are cubic polynomials
given by
\begin{equation}
  \label{eq:qubic-spline}
  \begin{split}
    X_j(s) &= a_{X,j}s^3 + b_{X,j}s^2 + c_{X,j}s + d_{X,j}, \\
    Y_j(s) &= a_{Y,j}s^3 + b_{Y,j}s^2 + c_{Y,j}s + d_{Y,j}, \\
    Z_j(s) &= a_{Z,j}s^3 + b_{Z,j}s^2 + c_{Z,j}s + d_{Z,j},
  \end{split}
\end{equation}
where $a_{X,j},b_{X,j},...,d_{Z,j}$ are real numbers.
Furthermore, we impose the following conditions on these functions.
\begin{equation}
  \label{eq:spline-interpolation}
  % \small
  \begin{split}        
    & (X_j(j),Y_j(j),Z_j(j))=(x_j,y_j,z_j),\quad j=0,1,2,\\
    & (X_j(j+1),Y_j(j+1),Z_j(j+1)) \\
    &\quad =(x_{j+1},y_{j+1},z_{j+1}),\quad j=0,1,2,\\
    &(X'_j(j+1),Y'_j(j+1),Z'_j(j+1)) \\
    &\quad =(X'_{j+1}(j+1),Y'_{j+1}(j+1),Z'_{j+1}(j+1)),\quad j=0,1,\\
    &(X''_j(j+1),Y''_j(j+1),Z''_j(j+1)) \\
    &\quad =(X''_{j+1}(j+1),Y''_{j+1}(j+1),Z''_{j+1}(j+1)),\quad j=0,1.
  \end{split}
\end{equation}
In this paper, in addition to the conditions in \cref{eq:spline-interpolation},
we find the \emph{natural} cubic Spline interpolation that satisfies
\begin{equation}
  \label{eq:natural-spline}
  X''_0(0)=X''_3(3)=Y''_0(0)=Y''_3(3)=Z''_0(0)=Z''_3(3)=0.
\end{equation}

The coefficients of $X_j(s)$ are determined as follows (the coefficients of $Y_j(s)$ and $Z_j(s)$ are determined similarly).
In general, suppose that $N$ points $(x_0,y_0),\dots,(x_N,y_N)$ are given, and, 
for $j=0,\dots,N-1$, the curve $C_j$ passing through $(x_j,y_j,z_j)$ and $(x_{j+1},y_{j+1},z_{j+1})$ are to be calculated. 
Let $v_{x,j+1}=6(x_j-2x_{j+1}+x_{j+2})$ for $j=0,\dots,N-2$ and $v_{x,0}=v_{x,N-1}=0$.
Then, define $u_{X,j}$ as the solution to the following system of linear equations:
\begin{align}
  \label{eq:spline-interpolation-linear-equation}
  \begin{pmatrix}
    4 & 1 \\
    1 & 4 & 1 \\
      & \ddots & \ddots & \ddots \\
      &        & 1      & 4      & 1 \\
      &        &        & 1      & 4 \\
  \end{pmatrix}
  \begin{pmatrix}
    u_{X,1} \\ u_{X,2} \\ \vdots \\ u_{X,N-2} \\ u_{X,N-1}
  \end{pmatrix}
  =
  \begin{pmatrix}
    v_{x,1} \\ v_{x,2} \\ \vdots \\ v_{x,N-2} \\ v_{x,N-1} 
  \end{pmatrix}
  .
\end{align}
Furthermore, set $u_{X,0}=u_{X,N}=0$ by the natural spline condition (\cref{eq:natural-spline}).
Then, the coefficients $a_{X,j},b_{X,j},c_{X,j},d_{X,j}$ of $X_j(s)$ are determined as
\begin{align*}
  a_{X,j}&=\frac{1}{6}(u_{X,j+1}-u_{X,j}), & 
  b_{X,j}&=\frac{u_{X,j}}{2},\\
  c_{X,j}&=x_{j+1}-x_j-\frac{1}{6}(u_{X,j+1}+2u_{X,j}), &
  d_{X,j}&=x_j,
\end{align*}
for $j=0,\dots,N-1$.


\subsection{Solving the inverse kinematics problem}

We generate the trajectory for the curve $C_j$ obtained in the previous section by solving the inverse kinematics problem using the following procedure.

First, using the CGS-QE method, we determine the existence of solutions to the inverse kinematics problem for each curve $C_j$ ($j=0,1,2$) that constitutes the path to move the end-effector.
In \cref{eq:inverse-kinematics-formula}, replace $x,y,z$ in each equation by $X_j(s),Y_j(s),Z_j(s)$, respectively, to obtain a system of polynomial equations with $s$ as parameter. Let 
the result be $\bar{F}_j(s)$.

Next, we apply the CGS-QE method to $\bar{F}_j(s)$ to determine whether the system of equations $\bar{F}_j(s)=0$ has real solutions within the parameter $s\in[0,1]$.
If $\bar{F}_j(s)=0$ has real solutions within the parameter $s\in[0,1]$,
%  (i.e., within $s\in[0,3]$ throughout for $s$), 
we calculate the trajectory of the end-effector's position 
by changing $s$ with a series of time steps $t=0,\dots,T$, where $T$ is a positive integer.
For time $t=0,\dots,T$, let $s=f(t)$ where $f$ is a continuous function of $[0,T]\to[0,1]$.
To ensure that the end-effector has no velocity and acceleration at the beginning and end of the trajectory, we obtain $f$ as a polynomial of the smallest degree possible to satisfy $f'(t)=f''(t)=0$ at $t=0$ and $T$.
Then, we obtain 
\begin{equation}
  \label{eq:ft}
  f(t)=\left(\frac{6t^5}{T^5}-\frac{15t^4}{T^4}+\frac{10t^3}{T^3}\right)   
\end{equation}
(see \cite{lyn-par2017,yos-ter-mik2023}).

Finally, 
% we solve the inverse kinematics problem $t=0,\dots,T$. 
For $j=0,1,2$ and $t=0,\dots,T$, the configuration of the joints is obtained by solving the system of polynomial equations 
\begin{equation}
  \label{eq:inverse-kinematics-each-time}
  \bar{F}_j(f(t))=0.    
\end{equation}

\subsection{An algorithm for path and trajectory planning with spline interpolation}

Summarizing the above, an algorithm for path and trajectory planning with spline interpolation is 
given in \Cref{alg:spline-trajectory}.

\begin{algorithm}[t]
  \caption{Path and trajectory planning with spline interpolation}
  \label{alg:spline-trajectory}
  \begin{algorithmic}[1]
    \Input{The points that the end-effector of myCobot should pass through, 
    including the initial position and the target position: $(x_0,y_0,z_0),\dots,(x_N,y_N,z_N)$,
    The number of time steps: $T$}
    \Output{A set of the tuple $(\theta_1,\theta_3,\theta_4)$ for each of the $(N\times T+1)$ points on the spline curve passing through the input points}
    \State{$A\gets\emptyset$;}  
    \State{Solve the inverse kinematic problem \cref{eq:inverse-kinematics-formula} for 
    $(x,y,z)=(x_0,y_0,z_0)$ with the algorithm for the inverse kinematics problem 
    \cite[Algorithm 1]{yos-ter-mik2023};}
    \If{no solution is obtained}
      \State{\Return Error;}
    \EndIf
    \State{$A\gets A\cup\{(\theta_1,\theta_3,\theta_4)\}$;}
    \State{For $(x_0,y_0,z_0),\dots,(x_N,y_N,z_N)$, input to the algorithm for spline interpolation \cite{far2002} to obtain the spline curve $(X_j(s),Y_j(s),Z_j(s))$;}
    \For{$j\in[0,\dots,N-1]$}
      \State{Put $f(t)$ in \cref{eq:ft} into $s$ in $(X_j(s),Y_j(s),Z_j(s))$;}
      \For{$t\in[1,\dots,T]$}
        \State{Solve the inverse kinematic problem \cref{eq:inverse-kinematics-each-time} for $(X_j(t),Y_j(t),Z_j(t))$ with the algorithm for the inverse kinematics problem 
        \cite[Algorithm 1]{yos-ter-mik2023};}
        \If{no solution is obtained}
          \State{\Return Error, ($j, t$);}
        \Else
          \State{$A\gets A\cup\{(\theta_1,\theta_3,\theta_4)\}$;}
        \EndIf
      \EndFor
    \EndFor 
  \end{algorithmic}
\end{algorithm}

