For a closed, convex set $\X \subseteq \R^n$ and $x\in \R^{n}$, $\Px{x}$ is the projection of $x$ onto $\X$.



\section{Problem setup and case study}


    \subsection{Problem Setup}

Consider $N \in \N$ agents indexed by the set $\mc I \coloneqq \{1,\dots, N\}$, whose individual strategy is denoted as $\x_i \in \R^{n_i}$. Given all other players' strategies, each agent aims at solving the following optimization problem:
%
\begin{equation}\label{eq:problem}
	\forall i \in \mc I : \underset{\x_i\in \X_i}{\min} \; \Ji(\x_i, \agg(\x)),
\end{equation}
%
where $x \coloneqq \col(\x_1,\dots,\x_N) \in \R^n$ is the global strategy vector, and the cost function $\map{\Ji}{\R^{n_i} \times \R^d}{\R}$ depends on $\x_i \in \R^{n_i}$ as well as on the \emph{generalized aggregator} \cite{Jensen2010} 
\begin{align}\label{eq:sigma}
	\agg(\x) \coloneqq \frac{1}{N} \sum_{i \in \mc I}\phii(\x_i),
\end{align}
%
where each \emph{aggregation rule} $\phii: \R^{n_i} \to \R^d$ models the contribution of $\x_i$ to $\sigma(\x)$.
%
Finally, $\X_i \subseteq \R^{n_i}$ denotes the domain of feasible strategies for agent $i$ and $\X := \prod_{i\in\mc I}\X_i$ is the collective one.
%
A standard solution concept for the aggregative game in \eqref{eq:problem} is the NE~\cite{facchinei2007gnep} defined as follows.
\begin{definition}[\textup{Nash equilibrium}]\label{def:NE}
	A collective vector of strategies $\xstar \in \X$ is a NE of \eqref{eq:problem} if, for all $i \in \mc I$,
	\begin{equation*}
		\Ji(\xistar, \agg(\xstar)) \leq \underset{\x_i \in \X_i}{\min} \, \Ji(\x_i,\tfrac{1}{N}\phii(\x_i) + \aggmi(\xstari)), %\eqoprocend
	\end{equation*}
	where $\aggmi(x_{-i}^\star)\coloneqq \tfrac{1}{N} \sum_{j\in\mc I\setminus\{i\}} \phij(x_j^\star)$, and $x_{-i}^\star\coloneqq \col(x_1^\star,\ldots,x_{i-1}^\star,x_{i+1}^\star,\ldots,x_N^\star) \in \R^{n-n_i}$.
\end{definition} 
%
To demonstrate the relevance of this framework, we formulate a voltage support problem in smart grids as an instance of~\eqref{eq:problem}. We will then revisit this problem in \S \ref{sec:numerical_simulation} to illustrate the efficacy of the proposed scheme numerically.


\subsection{Case study: voltage support in smart grids}
\label{subsec:motivating_example}

Consider a set of $N$ electric vehicles (EVs) populating a distribution grid, in which
each agent controls both the active and reactive power injections of their own EV charger. 
Active power demand is exclusively associated to battery charging and is subject to the presence of a plugged-in vehicle. The charger is equipped with an inverter capable of full two-quadrant operation (see, e.g.,~\cite{Qatnight1}).
In this setting, every agent wishes to determine a day-ahead EV charging schedule, subject to time-varying cost of electricity and an additional fee applied by the distribution system operator (DSO) to encourage voltage support provision \cite{BolognaniEtAl2015TAC,DorflerEtAl2019ECC}. The latter is carried out by means of reactive power compensation: this is known to benefit the network efficiency, in terms of reduction of losses as well as curtailment of distributed generators \cite{DeakinEtAl2018PESGM,DEAKIN2020106770}.
%
Given a discrete time interval $\{1,\ldots,T\}$, we define each agent's strategy as $x_i\coloneqq \col(p_i,q_i)$, where $p_i,q_i\in\mathbb{R}^{T}$ are the active and reactive power injections, respectively.
The voltage at each of the $N_b \in \N$ buses is obtained through the linearized \emph{DistFlow} branch flow model as a function of nodal power injections \cite{BaranWu1989_TPD,FarivarEtAl2013_CDC}. In our problem setup, this is
\begin{displaymath}
	v = v_0 + \sum_{i=1}^N(\rho_i\otimes I_T)p_i + \sum_{i=1}^N(\xi_i\otimes I_T)q_i,
\end{displaymath}
where $v\in\mathbb{R}^{d}$, with $d=N_bT$, is the vector of bus voltages, 
$\rho_i, \xi_i\in\mathbb{R}^{N_b}$ are the columns of the resistance and reactance matrices, respectively, corresponding to the bus where agent $i$ is connected; finally, $v_0$ is a voltage offset due to non-manipulable generation/load. 
Then, by letting  $\Phi_i\coloneqq N [\rho_i \; \xi_i]\otimes I_T \in \R^{d \times 2T}$ for all $i$, we define
\begin{equation}\label{eq:distflow}
	\sigma(x) = \frac{1}{N}\sum_{i=1}^N \Phi_i x_i,
\end{equation}

This yields a game in the form of \eqref{eq:problem}, where
\begin{displaymath}
	J_i(x_i,\sigma(x)) = -\col(\pi,0_{T \times 1})^\top x_i + \|\sigma(x) - \bar{\sigma} \|^2_H + \| x_i \|^2_{\lwm}.
\end{displaymath}
Here, to incentivize voltage support provision, the deviation of the aggregate variable from a given reference voltage vector $\bar{\sigma}\in\mathbb{R}^{N_bT}$ is penalized via the positive definite matrix $H \in \R^{d \times d}$; this can be broadcast, e.g., by the distribution system operator \cite{ZhangEtAl2018_JSTSP}.
Energy prices are expressed by $\pi\in\mathbb{R}^{T}$, and $\lwm \in \R^{2T\times 2T}$ is a positive definite weight matrix. 

Finally, $X_i\subset\mathbb{R}^{2T}$ takes the form:
\begin{multline*}
	X_i \coloneqq  \left\{(p_i,q_i)\mid a_{i,\mathrm{ch}}^\top p_i = b_{i,\mathrm{ch}} \right\}
	\cap \left\{(p_i,q_i)\mid p_i\leq 0 \right\}\\
	\cap \left\{(p_i,q_i) \mid p_{i\tau}^2 + q_{i\tau}^2  \leq \bar{S}^2,\,  \tau = 1,\ldots, T\right\},
\end{multline*}
where the last two terms model the EV charger's apparent power limit $\bar{S} > 0$ (in kVA), and prevents any active power from being fed back to the grid; the first term imposes a total recharge target $b_{i,\mathrm{ch}} > 0$ (kWh) along the horizon, with any recharge event being possible compatibly with the plugged-in state of the vehicle (encoded by the vector $a_{i,\mathrm{ch}}\in\{0,1\}^{T}$).

\section{Nash equilibrium seeking algorithm}
\label{sec:unconstrained_algorithm}

\subsection{Algorithm description and main result}

In this section, we derive a novel equilibrium-seeking algorithm for problem~\eqref{eq:problem} working in a fully distributed fashion.
%
Indeed, we assume partial information, i.e., each agent $i$ is only aware of its own local information (e.g., the current local strategy or the local functions $\Ji$ and $\phii$) and exchanges tentative decisions with a subset of agents considered as neighbors, according to an underlying communication graph.

In particular, we assume the $N$ agents communicating over a directed graph $\cG = (\mc I, \cE)$, with $\cE \subset \mc I^2$, such that $i$ can receive information from agent $j$ only if the edge $(j,i)\in\cE$. 
%
The set of in-neighbors of $i$ is represented by $\cN_i \coloneqq \{j \in \mc I \mid (j,i) \in \cE\}$ (where also $i\in\cN_i$).
%
Graph $\cG$ is associated with a weighted adjacency matrix $\cW \in\R^{N\times N}$ whose entries satisfy $w_{ij} >0$ whenever $(j,i)\in \cE$ and $w_{ij} =0$ otherwise. 
%

We proceed with the derivation of our distributed algorithm. Let $\xit \in \R^{n_i}$ be the strategy chosen by agent $i$ at iteration $\iter \ge 0$, $\iter \in \N$.
%
We update each agent's strategy by performing a projected pseudo-gradient descent step, as
%
\begin{equation}\label{eq:desired_update}
    \xitp = \Pxi{\xit - \gamma \left( \nabla_{\x_i}\Ji(\xit, \agg(\xt))\right)},
\end{equation}
%
where $\gamma > 0$ plays the role of the gradient stepsize.
%
 We point out that the chain rule and the definition of $\agg(\xt)$ (cf.~\eqref{eq:sigma}) lead to $\nabla_{\x_i}\Ji(\xit, \agg(\xt)) = \nabla_1 J_i(\xit,\agg(\xt)) + \tfrac{\nabla \phii(\xit)}{N}\nabla_2 \Ji(\xit,\agg(\xt))$.
In our distributed setting, however, agent $i$ does not have access to the aggregate variable $\agg(\xt)$. 
 %
 To compensate for this lack of information, we rely on the auxiliary variable $\zit \in \R^{d}$. 
 %
 Thus, for all $i \in \mc I$, we introduce the operator $\tFi: \R^{n_i} \times \R^d \to \R^{n_i}$ defined as
 %
 \begin{equation*}
   \tFi(\x_i,s) \coloneqq \nabla_1 J_i(\x_i,s) + \tfrac{\nabla \phii(x_i)}{N}\nabla_2 \Ji(x_i,s),
 \end{equation*}
 and, in accordance, we modify the update~\eqref{eq:desired_update} as 
%
\begin{equation}
    \xitp = \Pxi{\xit - \gamma \tFi\left(\xit,\phii(\xit) + \zit\right)},\label{eq:implementable_update}
\end{equation}
%
which meets the distributed requirements of our algorithm. 
%
Note that, in case $\zit\rightarrow -\phii(\xit)  + \agg(\xt)$,
then the implementable law~\eqref{eq:implementable_update} coincides with the one in~\eqref{eq:desired_update}. 
%
In particular, variable $\zit$ encodes the estimate of $\agg(\xit) - \phii(\xit)$. 
%
For this reason, we update each auxiliary variable $\zit$ according to the following causal version of the perturbed average consensus scheme:
%
\begin{equation}\label{eq:update_zit}
    \zitp = \sum_{j\in\cN_i}w_{ij}\zjt + \sum_{j\in\cN_i}w_{ij}(\phij(\xjt) - \phii(\xit)).
\end{equation}
%
This is indeed implementable in a distributed fashion, as it only requires communication with neighboring agents $j \in \cN_i$. 
%
If each $\xit$ is fixed, then it is possible to establish the global exponential stability of equilibrium $-\phii(\xit) + \sigma(\xt)$ for each dynamics \eqref{eq:update_zit}.
%
With an eye to singular perturbation, we then modify~\eqref{eq:implementable_update} by introducing a tuning parameter $\delta \in (0,1)$ and taking a convex combination step that allows for arbitrarily reducing the variations of each $\xit$ while preserving the invariance of each $\X_i$, thus obtaining:
\begin{equation*}
    \xitp = \xit + \delta\left(\Pxi{\xit - \gamma \tFi\left(\xit,\phii(\xit) + \zit\right)} - \xit\right).
\end{equation*}

We summarize our main update steps in Algorithm~\ref{algo:unconstrained}, which will be hereafter referred to as TRacking Aggregative Distributed Equilibrium Seeking (\algo/).
%
\begin{algorithm}[t!]
	\begin{algorithmic}
		\State \textbf{Initialization}: $\x_i^0 \in \R^{n_i}, \z_i^0 = 0$\\
		\smallskip
		\textbf{For} $t=1, 2, \dots$ \textbf{do} 
        \begin{subequations}\label{eq:local_update}
            \begin{align}
                \xitp\!&=\!\xit \!+\! \delta\left(\Pxi{\xit \!-\! \gamma\tFi\left(\xit,\phii(\xit) \!+\! \zit\right)} \!-\! \xit\right)\label{eq:x_update}
                \\
                \zitp &= \sum_{j\in\cN_i}w_{ij}\zjt + \sum_{j\in\cN_i}w_{ij}(\phij(\xjt) - \phii(\xit))\label{eq:z_local}
            \end{align}
        \end{subequations}
		\textbf{End}
	\end{algorithmic}
	\caption{\algo/ (Agent $i$)}
	\label{algo:unconstrained}
\end{algorithm}
%
Note that \algo/ requires the initialization $\z_i^0 = 0$ for all $i \in \mc I$: we will discuss in the sequel the interpretation of this specific choice. 
%
Algorithm~\ref{algo:unconstrained} appears similar to the scheme in~\cite{koshal2016distributed} where, however, a diminishing stepsize is employed and the convex combination step is missing.
% 
As clarified later in the paper, such a combination step turns out to be crucial for using constant parameters $\delta$ and $\gamma$ and analyzing \algo/ under the lens of singular perturbation, ultimately yielding linear convergence to $\xstar$.
%
The local update~\eqref{eq:local_update} leads to the stacked vector form of \algo/, which reads as
%
\begin{subequations}\label{eq:global_update}
    \begin{align}
        \xtp &= \xt + \delta\!\left(\! P_{\X}\!\big[\xt \! - \! \gamma\tF\left(\xt,\phi(\xt) + \zt\right)\big] - \xt\!\right)\!\!,\label{eq:global_update_x}
        \\
        \ztp &= \Wd\zt + (\Wd - I_{Nd})\phi(\xt),\label{eq:global_update_z}
  \end{align}  
\end{subequations}
%
with $\Wd \coloneqq \cW \otimes I_d \in \R^{Nd}$, $\zt \coloneqq \col(\z_{1,\iter},\dots,\z_{N,\iter})$, $\phi(\xt) \coloneqq \col(\phi_1(\xt_1),\dots,\phi_N(\xt_N))$, $\tF(\xt,\phi(\xt) + \zt) \coloneqq \col(\tilde{F}_1(\x_{1}^{\iter},\phi_1(\x_{1}^{\iter}) + z_{1}^{\iter}), \dots,
\tilde{F}_N(\x_{N}^{\iter},\phi_N(\x_{N}^{\iter}) + z_{N}^{\iter}))$.

Before establishing the convergence properties of \algo/, we need to enforce the following assumptions.
%
\begin{assumption}[\textup{Feasible sets and cost functions}]\label{ass:local_feasible_set}
    For all $i \in \mc I$, we have that:
        \begin{itemize} 
            \item[(i)] The feasible set $\X_i$ is nonempty, closed, and convex;
            \item[(ii)] The function $J_i(\cdot,\phii(\cdot)/N + \sigmai(\xmi))$ is of class $\cC^1$, i.e., its derivative exists and is continuous, for all $\xmi$.             
        \end{itemize} 
    \end{assumption}
    %
    A crucial element in this game-theoretic framework is the so-called \emph{pseudo-gradient mapping} $F: \R^n \to \R^n$:
    %
    \begin{equation}\label{eq:F_definition}
        \hspace{-.2cm}F(\x) \coloneqq \col(\nabla_{\x_1} J_1(\x_1,\agg(\x)), \dots, \nabla_{\x_N} J_N(\x_N,\agg(\x))),
    \end{equation}
    %
    for which we postulate the following conditions.
    \begin{assumption}[\textup{Strong monotonicity and Lipschitz continuity}]
        \label{ass:objective_function}
        $F$ is $\mu$-strongly monotone, i.e., there exists $\mu > 0$ such that, for any $\x, \y \in \R^{n}$,  $(F(x) - F(y))\T (\x - \y) \ge \mu\norm{\x - \y}^2.$
        %
        Moreover, given any $\x_i, \x_i^\prime \in \R^{n_i}$ and $y, y^\prime \in \R^{n-n_i}$, for all $i \in \mc I$ we assume that 
        %
        \begin{align*}
            \|\nabla_{\x_i}\Ji(\x_i,\phii(\x_i)/N + y) - & \nabla_{\x_i^\prime}\Ji(\x_i^\prime,\phii(\x_i^\prime)/N + y^\prime)\|
            \\
            & \leq \!\beta_1\!\norm{\col(\x_i,y) \!-\! \col(\x_i^\prime,y^\prime)}\!,
            \\
            \norm{\nabla_1\Ji(\x_i,y) \!-\! \nabla_1\Ji(\x_i^\prime,y^\prime)} & \leq \!\beta_1\!\norm{\col(\x_i,y) \!-\! \col(\x_i^\prime,y^\prime)}\!,
            \\
            \norm{\nabla_2\Ji(\x_i,y) \!-\! \nabla_2\Ji(\x_i^\prime,y^\prime)} & \leq \!\beta_2\!\norm{\col(\x_i,y) \!-\! \col(\x_i^\prime,y^\prime)}\!,
            \\
            \norm{\phii(\x_i) - \phii(\x_i^\prime)} &\leq \beta_3\norm{\x_i - \x_i^\prime}, 
        \end{align*} 
        %
        hold true for positive scalars $\beta_1,\beta_2, \beta_3>0$.
    \end{assumption}

    Assumptions~\ref{ass:local_feasible_set} and~\ref{ass:objective_function} together guarantee the existence and uniqueness of a NE $\xstar$ for~\eqref{eq:problem}~\cite[Th.~2.3.3]{facchinei2003finite}.  
    %
Further, for any $\gamma > 0$, it holds that \cite[Ch.~12]{facchinei2003finite}
%
\begin{align*}
    \xstar = \Px{\xstar - \gamma \F(\xstar)}.
\end{align*}
%
This, in turn, leads to $\xstar =\xstar + \delta(\Px{\xstar - \gamma \F(\xstar)} - \xstar)$ for any $\delta > 0$.
%
The following assumption characterizes the considered network graph.
%
\begin{assumption}[\textup{Network}]
    \label{ass:network}
    The graph $\cG$ is strongly connected, i.e., for every $(i,j) \in \mc I^2$ there exists a path of directed edges from $i$ to $j$, and the matrix $\cW$ is doubly stochastic, i.e., $\cW 1_N = 1_N$ and $1_N\T \cW = 1_N\T.$
\end{assumption}
%
We are now in the position of providing the convergence properties of \algo/ in computing the NE $\xstar$ of~\eqref{eq:problem}.
%
\begin{theorem}\label{th:convergence}
	Consider~\eqref{eq:global_update}.
	%
	There exist constants $\bar{\gamma}, \bar{\delta}, a_1, a_2 > 0$ such that, for any $\delta \in (0,\bar{\delta})$ and $\gamma \in (0,\bar{\gamma})$ and $(\x^0,\z^0) \in \X \times \R^{Nd}$ such that $\oned\T \z^0 = 0$, it holds that
	%
	\begin{align*}
		\norm{\xt - \xstar} \leq a_1 e^{-a_2\iter}.
	\end{align*}
	%
\end{theorem}
%
The proof of Theorem~\ref{th:convergence} relies on a \emph{singular perturbation} analysis of~\eqref{eq:global_update} and it is provided in the next subsection.

\subsection{Proof of Theorem \ref{th:convergence}}
\label{sec:thm_proof}

The key intuition consists in the interpretation of~\eqref{eq:global_update} as a singularly perturbed system, i.e., an interconnected dynamics in the form 
%
\begin{subequations}\label{eq:interconnected_system_generic}
    \begin{align}
        \chitp &= \chit + \delta f(\chit,\wt)\label{eq:slow_system_generic}
        \\
        \wtp &= g(\wt,\chit,\delta),\label{eq:fast_system_generic}
    \end{align}
\end{subequations}
%
with $\chit \in \cD \subseteq \R^n$, $\wt \in \R^m$, $\delta > 0$, $f: \cD \to \R^n$, and $g: \cD \times \R^m \times \R \to \R^m$.
%
The subsystem~\eqref{eq:slow_system_generic} is the so-called slow dynamics and~\eqref{eq:fast_system_generic} is the so-called fast one having an equilibrium parametrized in the slow state $\chit$, namely, there exists $h: \cD \to \R^m$ such that 
%
\begin{align}
    0 = g(h(\chi),\chi,\delta),
\end{align}
%
for all $\chi \in \cD$ and $\delta > 0$.

Singular perturbations results (see, e.g.,~\cite[Th.~II.5]{carnevale2022tracking}) allow for guaranteeing the stability properties of interconnected systems of the form~\eqref{eq:interconnected_system_generic} by separately studying the so-called boundary layer system 
%
\begin{equation}\label{eq:boundary_layer_system_generic}
    \psitp = g(\psit + h(\chi),\chi,\delta) - h(\chi)
\end{equation}
%
with $ \psit \in \R^m$, and the so-called reduced system
%
\begin{equation}\label{eq:reduced_system_generic}
    \chitp = \chit + \delta  f(\chit,h(\chit)).
\end{equation}
%
We note that the boundary layer system~\eqref{eq:boundary_layer_system_generic} is obtained by arbitrarily fixing the slow state $\chit = \chi$ in the fast dynamics~\eqref{eq:fast_system_generic} and considering the error coordinate with respect to the parametrized equilibrium $h(\chi)$.
%
As for the reduced system~\eqref{eq:reduced_system_generic}, it is obtained by plugging $\wt = h(\chit)$ (i.e., fast state always at the parametrized equilibrium) into the slow dynamics~\eqref{eq:slow_system_generic}.
%
The rationale behind this approach is that, by decreasing $\delta$ (see~\eqref{eq:slow_system_generic}), we can arbitrarily reduce the variations of $\chit$ and, thus, also the approximations characterizing the auxiliary systems~\eqref{eq:boundary_layer_system_generic}-\eqref{eq:reduced_system_generic}.
%

We will analyze~\eqref{eq:global_update} scheme by identifying (a transformation of) the consensus-based part~\eqref{eq:global_update_z} as the fast dynamics and the gradient-based part~\eqref{eq:global_update_x} as the slow one.

The proof of Theorem~\ref{th:convergence} thus builds upon five steps:

\emph{1. Bringing \eqref{eq:global_update} in the form of \eqref{eq:interconnected_system_generic}:} We introduce the coordinates $\bz \in \R^d$ and $\pz \in \R^{(N-1)d}$ defined as follows:
    %
    \begin{align}\label{eq:change_mean}
        \begin{bmatrix}
            \bz
            \\
            \pz
        \end{bmatrix} \coloneqq \begin{bmatrix}
            \tfrac{\oned\T}{N}\\
            \Rd\T
        \end{bmatrix}\z \implies \z = \oned\bz + \Rd\pz,
    \end{align}
    %
    where $\Rd \in \R^{Nd \times (N-1)d}$ with $\norm{\Rd} = 1$ is such that
    %
    \begin{align}
    \Rd \Rd\T = I_{Nd} - \tfrac{\oned\oned\T}{N}~\text{ and }~ \Rd\T\oned = 0. \label{eq:eq_Rd}
    \end{align}
    %
    By combining the definition of $\bz$ in~\eqref{eq:change_mean}, the update~\eqref{eq:global_update_z}, the identities in~\eqref{eq:eq_Rd}, and the fact that $\oned\T \Wd = \oned\T$ and $\oned\T (\Wd - I) = 0$ (cf. Standing Assumption~\ref{ass:network}), we get
    %
    \begin{align}
        \bztp = \bzt,\label{eq:barz_update}
    \end{align}
    %
    which, in turn, leads to $\bztp = \bz^0 = 0$ for all $\iter \ge 0$ by the initialization $\oned\T z^0 = 0$.
    %
    We are thus entitled to ignore the dynamics of $\bzt$ and, according to~\eqref{eq:change_mean}, we rewrite~\eqref{eq:global_update} as
    %
    \begin{subequations}\label{eq:global_update_mean}
        \begin{align}
            \xtp\!&=\!\xt \!+\! \delta\big(P_X[\xt \!-\! \gamma \tF(\xt,\phi(\xt) \!+\! \Rd\pzt)] \!-\! \xt\big),\label{eq:x_update_mean}
            \\
            \pztp &= \Rd\T \Wd\Rd\pzt + \Rd\T(\Wd - I)\phi(\xt).\label{eq:z_update_mean}
      \end{align}  
    \end{subequations}
    %
    For any $\iter \geq0$, the interconnected system~\eqref{eq:interconnected_system_generic} can thus be obtained from \eqref{eq:global_update_mean} by setting 
    \begin{align}\label{eq:assign}
        \begin{split}
            \chit &\coloneqq \xt, \quad w^t \coloneqq \pzt, 
            \\
            f(\chit,\wt) &\coloneqq \Px{\xt - \gamma \tF(\xt,\phi(\xt) + \Rd\pzt)} - \xt,
            \\
            g(\wt,\chit) &\coloneqq \Rd\T \Wd\Rd\wt + \Rd\T(\Wd - I)\phi(\xt). 
        \end{split}
    \end{align}
    %
    In particular, we refer to the subsystem~\eqref{eq:x_update_mean} as the slow system, while we refer to~\eqref{eq:z_update_mean} as the fast one. 


    \emph{2. Equilibrium function $h~$:} For any $\xt \in\R^n$, using~\eqref{eq:eq_Rd} and since $\cW$ is doubly stochastic (cf. Standing Assumption~\ref{ass:network}) notice that, for any $\xt = \x \in \R^n$, the point
    %
    \begin{equation}\label{eq:man_definition}
        \pz = h(\x) \coloneqq -\Rd\T\phi(\x)
    \end{equation}
    %
    constitutes an equilibrium of~\eqref{eq:z_update_mean}.
    %
    Since $\Rd\T \Wd\Rd$ is Schur in view of Standing Assumption~\ref{ass:network}, we interpret~\eqref{eq:z_update_mean} as a strictly stable linear system with nonlinear input $\Rd\T(\Wd - I)\phi(\xt)$ parametrizing the equilibrium of the subsystem. 
    %
    The role of $\gamma$ is to slow down the variation of $\xt$ so that the stability of $h(\xt)$ for~\eqref{eq:z_update_mean} is preserved.
    %

    \emph{3. Boundary layer system:} 
    %
    The so-called boundary layer system associated to~\eqref{eq:global_update_mean} can be constructed by fixing $\xt = x$ for all $\iter \geq0$, for some arbitrary $\x \in \mathbb{R}^n$ in \eqref{eq:z_update_mean}, and by rewriting it according to the error coordinates $\tzt := \pzt - h(\xt)$. 
    %
    Using~\eqref{eq:eq_Rd}, the definition of $h$ (cf.~\eqref{eq:man_definition}), and the fact that $\cW$ is doubly stochastic (cf. Standing Assumption~\ref{ass:network}), we get
    %
    \begin{equation}\label{eq:bl}
        \tztp = \Rd\T \Wd\Rd\tzt.
    \end{equation}
    %
    Notice that the obtained system is in the form of \eqref{eq:boundary_layer_system_generic} with $\psi =\tzt$, and $g(\psi  +  h(\x),\x) - h(\x) = \Rd\T \Wd\Rd\tz$.
    The next lemma provides a Lyapunov function for \eqref{eq:bl}.
    %
    \begin{lemma}[\textup{\cite[Lemma~III.4]{carnevale2022tracking}}]\label{lemma:bl}
        Consider system~\eqref{eq:bl}. 
        %
        Then, there exists a continuous function $U :\R^{(N-1)d} \to \R$ such that 
        %
        \begin{subequations}\label{eq:U_generic}
            \begin{align}
                &b_1 \norm{\tz}^2 \leq U(\tz) \leq b_2\norm{\tz}^2 \label{eq:U_first_bound_generic}
                \\
                &U(\Rd\T \Wd\Rd\tz) -  U(\tz)  \leq  -b_3\norm{\tz}^2\label{eq:U_minus_generic}
                \\
                &|U(\tz_1) \! - \! U(\tz_2)| \! \leq \! b_4 \! \norm{\tz_1 \! - \! \tz_2}\!\norm{\tz_1}
                \! + \! b_4\!\norm{\tz_1 \! - \! \tz_2}\!\norm{\tz_2}\!,\!
                \label{eq:U_bound_generic}
            \end{align}
        \end{subequations}
        %
        for all $\tz,  \tz_1,  \tz_2 \in \R^m$, and some $b_1, b_2, b_3, b_4 > 0$.\oprocend
    \end{lemma}
    %
    \emph{4. Reduced system:}
   The so-called reduced system can be obtained by plugging into \eqref{eq:x_update_mean} the fast state at its steady-state equilibrium, i.e., we consider $\pzt = h(\xt)$ for all $\iter \ge 0$. We thus have:
   %
   \begin{equation}\label{eq:rs}
        \xtp = \xt + \delta(P_X[\xt - \gamma \tF(\xt,\phi(\xt) + \Rd h(\xt))] - \xt).\!
   \end{equation}
    %
    Due to~\eqref{eq:eq_Rd} we have that $\tF(\xt,\phi(\xt) + \Rd h(\xt)) = \tF(\xt,\oned\agg(\xt)) = F(\xt)$, so~\eqref{eq:rs} is equivalent to 
    %
    \begin{equation}\label{eq:rs_explicit}
        \xtp = \xt + \delta\left(\Px{\xt - \gamma F(\xt)} - \xt\right).
    \end{equation}
    %
    The next lemma provides a Lyapunov function for \eqref{eq:rs}.
    %
    \begin{lemma}[\textup{\cite[Lemma~III.5]{carnevale2022tracking}}]\label{lemma:rs}
        Consider system~\eqref{eq:rs}. Then, there exist a continuous function $W: \R^n \to \R$ and $\bar{\delta}_2, \bar{\gamma} > 0$ such that, for any $\delta \in (0,\bar{\delta}_2)$ and $\gamma \in (0,\bar{\gamma})$, it holds 
        %
        \begin{subequations}\label{eq:W_generic}
            \begin{align}
                &c_1 \norm{\x - \xstar}^2 \leq W(\x) \leq c_2\norm{\x - \xstar}^2\label{eq:W_first_bound_generic}
                \\
                &W(\x + \delta  f(\x,h(\x)))  -  W(\x)  \leq  -\delta c_3\norm{\x - \xstar}^2\label{eq:W_minus_generic}
                \\
                &|W(\x_1)-W(\x_2)|\leq c_4\norm{\x_1-\x_2}\norm{\x_1 - \xstar}
                \notag\\
                &\hspace{3.1cm}
                + c_4\norm{\x_1-\x_2}\norm{\x_2 - \xstar},\label{eq:W_bound_generic}
            \end{align}
        \end{subequations}
        %
        for all $\x, \x_1, \x_2, \x_3 \in \X$ and some $c_1, c_2, c_3, c_4 > 0$.\oprocend
    \end{lemma}


\emph{5. Lipschitz continuity of $f$, $g$ and $h$:}
As we will be invoking~\cite[Th.~II.5]{carnevale2022tracking}, we need to ensure that the Lipschitz continuity assumptions required by that theorem are satisfied. In particular, we require $f$ and $g$ in \eqref{eq:assign} to be Lipschitz continuous w.r.t. both arguments and $h$ in \eqref{eq:man_definition} to be Lipschitz continuous w.r.t. $x$.
%
Since $g$ and $h$ are linear functions, then their Lipschitz property is trivially guaranteed.
%
As for $f$, the Lipschitz continuity follows by the one of $\nabla J_i$ (cf. Standing Assumption~\ref{ass:objective_function}).
%
By combining Lemma~\ref{lemma:bl} and \ref{lemma:rs} with the Lipschitz conditions expressed above,~\cite[Th.~II.5]{carnevale2022tracking} can therefore be applied. 
%
Thus, there exists $\bar{\delta} \in (0,\bar{\delta}_2)$ so that $(\xstar,h(\xstar))$ is an exponentially stable equilibrium for~\eqref{eq:global_update_mean}.



