\title{CMIE: Combining MLLM Insights with External Evidence for Explainable Out-of-Context Misinformation Detection}

\author{Fanxiao Li\textsuperscript{1,3}, Jiaying Wu\textsuperscript{2}, Canyuan He\textsuperscript{3}, Wei Zhou\textsuperscript{3} \thanks{\quad The corresponding author.}\\
