\section{Proof of Theorem \ref{theorem1}}\label{appa}
We first characterize the DP of releasing $\{\widetilde\muv_k,\widetilde\Sigmav_k\}$ using the following established results.

\lemma[Multivariant Gaussian mechanism \cite{9799519}]{Given $\mathcal{D}$, the mechanism for publishing $\widetilde{\muv}_k$ in \eqref{eq5} satisfies $(\epsilon_k,\delta)$-DP given that the following inequality holds for any adjacent dataset $\mathcal{D}^\prime_{n,k^\prime}$:
\begin{align}
    &\frac{\epsilon_k^2}{2\log (2/\delta)}\nonumber\\
    &\geq\sup_{n,k^\prime}\left\{ \muv_k(\mathcal{D})- \muv_k(\mathcal{D}^\prime_{n,k^\prime}))^T\Gammav_k( \muv_k(\mathcal{D})- \muv_k(\mathcal{D}^\prime_{n,k^\prime})\right\}.\nonumber
\end{align}
}
\begin{IEEEproof}
    See \cite[Theorem 3]{9799519}.
\end{IEEEproof}

\lemma[Wishart mechanism \cite{Jiang_Xie_Zhang_2016}]{The mechanism for publishing $\widetilde\Sigmav_k$ in \eqref{eq6} satisfies $(\epsilon_0,0)$-DP given that
\begin{align}
    3\gamma_k \leq 2N_k\epsilon_0.\nonumber
\end{align}
}
\begin{IEEEproof}
    See \cite[Theorem 4]{Jiang_Xie_Zhang_2016}.
\end{IEEEproof}
\lemma[Parallel composition]{Suppose publishing $\widetilde\muv_k$ and $\widetilde\Sigmav_k$ of an individual class $k$ satisfies $(\epsilon_k^\prime,\delta)$-DP. Then, publishing $\{\widetilde\muv_k,\widetilde\Sigmav_k\}_{k=1}^K$ of all the classes satisfies $(\max_{k=1}^K \epsilon_k^\prime,\delta)$-DP.
}
\begin{IEEEproof}
    The result directly follows from the standard parallel mechanism of DP; see, e.g., \cite{dwork2014algorithmic}.
\end{IEEEproof}

Combining the above lemmas, it follows that releasing $\{\widetilde\muv_k,\widetilde\Sigmav_k\}_{k=1}^K$ adheres to $(\max_{k=1}^K \left\{\epsilon_k+\frac{3\gamma_k}{2N_k}\right\},\delta)$-DP.

Next, we characterize the DP of releasing $\widetilde\piv$. From Definition \ref{DP_def}, it can be verified that $\widetilde\piv$ satisfies $(\epsilon_0,0)$-DP if the following holds for any adjacent dataset $D^\prime_{n,k^\prime}$:
\begin{align}\label{eq_appa01}
    e^{-\epsilon_0}\Pr(\widetilde\piv|\piv(\mathcal{D}^\prime_{n,k^\prime}))\leq \Pr(\widetilde\piv|\piv(\mathcal{D})) \leq e^{-\epsilon_0}\Pr(\widetilde\piv|\piv(\mathcal{D}^\prime_{n,k^\prime})).
\end{align}
Combining the definition of $f(\widetilde\piv|\piv)$, it follows that the condition in \eqref{eq_appa01} is equivalent to \eqref{eq11}.

Finally, the overall DP can be obtained by using the following well-know composition theorem:
\lemma[Sequential composition]{\label{lemma4}Let $M_1$ and $M_2$ be two randomized mechanisms that apply to an input dataset $\mathcal{D}$ and satisfy $(\epsilon_1,\delta)$-DP and $(\epsilon_2,0)$-DP, respectively. Then, the sequential
execution of them satisfies $(\epsilon_1+\epsilon_2,\delta)$-DP.
}
\begin{IEEEproof}
    See \cite{dwork2014algorithmic}.
\end{IEEEproof}
According to Lemma \ref{lemma4}, releasing $\{\tilde\pi_k,\widetilde\muv_k,\widetilde\Sigmav_k\}_{k=1}^K$ satisfies $( \max_{k=1}^K\left\{\epsilon_k+\frac{3\gamma_k}{2N_k}\right\}+\epsilon_0,\delta)$-DP.

