\section{Proof of Proposition \ref{theorem3}}\label{appc}
First, we prove by contradiction that the solution satisfies $F^\prime_{i,j^\star}>0$ for $\forall i$. Suppose there exist some $i^\prime$ such that $F^\prime_{i^\prime,j^\star}=0$. The corresponding constraint becomes $e^{-\epsilon_0} F_{i,j}^\prime\leq F_{i,j^\star}=0$ implies $F_{i,j}^\prime=0$ for any $j\neq j^\star$. This contradicts with the row-stochastic constraint of $\sum_j F_{i,j}^\prime=1>0$. 

Next, define an auxiliary variable $\theta_{i,j}=\frac{F^\prime_{i,j}}{F^\prime_{i,j^\star}}$ for $\forall j\neq j$ and $\forall i$. The optimization problem is equivalent to:
\begin{align}
    &\min_{\epsilon_0,\{\theta_{i,j}\},\{F^\prime_{i,j^\star}\}_{\forall i}}   \sum_{i}g_iF^\prime_{i,j^\star}\nonumber\\
    &~\text{s.t. }~~ 0\leq \epsilon_0\leq \epsilon-\max_k\{\epsilon_k+\frac{3\gamma_k}{2N_k}\},\nonumber\\
    &~~~~~~e^{-\epsilon_0} \leq \theta_{i,j^\star}\leq e^{\epsilon_0} ,\forall j\neq j^\star, \forall i.\nonumber\\
    &~~~~~~ F_{i,j^\star}^\prime\left(1+\sum_{j\neq j^\star}\theta_{i,j}\right)=1,\forall i.\nonumber
\end{align}
%\end{IEEEproof}

From the last two constraints, it follows that
\begin{align}
    F_{i,j^\star}^\prime=\frac{1}{1+\sum_{j\neq j^\star}\theta_{i,j}}\in\left[\frac{1}{1+|\mathcal{S}^\prime(\mathcal{D})|e^{\epsilon_0}},\frac{1}{1+|\mathcal{S}^\prime(\mathcal{D})|e^{-\epsilon_0}}\right].\nonumber
\end{align}
Consequently, for any given $\epsilon_0$, the minimization of the linear objective over $\{F_{i,j^\star}\}_{\forall i}$ depends on each sign of $g_i$. Specifically, for any $i$ we consider the following two subcases:
\begin{itemize}
    \item If $g_i\geq 0$, the optimal solution is achieved when $  F_{i,j^\star}^\prime=1/(1+|\mathcal{S}^\prime(\mathcal{D})|e^{\epsilon_0})$.
    \item If $g_i< 0$, the optimal solution is achieved when $  F_{i,j^\star}^\prime=1/(1+|\mathcal{S}^\prime(\mathcal{D})|e^{-\epsilon_0})$.
\end{itemize}
The final step is to find the optimal solution for $\epsilon_0$. Let $A=\sum_{i:g_i> 0} g_i$ and $B=\sum_{i:g_i> 0} g_i$. The problem can be recast as the minimization of a one-dimensional function $J(\epsilon_0)=\frac{A}{1+|\mathcal{S}^\prime(\mathcal{D})|e^{\epsilon_0}}+\frac{B}{1+|\mathcal{S}^\prime(\mathcal{D})|e^{-\epsilon_0}}$ over the range of $0<\epsilon_0\leq \epsilon-\max_k\{\epsilon_k+\frac{3\gamma_k}{2N_k}\}$. The first-order derivative of $J(\epsilon_0)$ is given by
\begin{align}
    J^\prime(\epsilon_0)=\frac{Be^{\epsilon_0}|\mathcal{S}^\prime(\mathcal{D})|}{(1+|\mathcal{S}^\prime(\mathcal{D})|e^{-\epsilon_0})^2}-\frac{Ae^{\epsilon_0}|\mathcal{S}^\prime(\mathcal{D})|}{(1+|\mathcal{S}^\prime(\mathcal{D})|e^{\epsilon_0})^2}\leq 0.\nonumber
\end{align}
Consequently, $J(\epsilon_0)$ is non-increasing in $\epsilon_0$, and the optimal solution is given by the upper bound of $\epsilon_0$.

To summarize, the optimal solution is given by
\begin{align*}
    \epsilon_0&=\epsilon-\max_k\{\epsilon_k+\frac{3\gamma_k}{2N_k}\},\\
    F_{i,j^\star}^\prime&=\left\{\begin{aligned}
        1/(1+|\mathcal{S}^\prime(\mathcal{D})|e^{\epsilon_0}), & \text{ if } g_i\geq 0\\
        1/(1+|\mathcal{S}^\prime(\mathcal{D})|e^{-\epsilon_0}), & \text{ otherwise}\\
    \end{aligned}\right.\\
        F_{i,j}^\prime&=\left\{\begin{aligned}
       e^{\epsilon_0}F_{i,j^\star}^\prime, & \text{ if } g_i\geq 0\\
       e^{-\epsilon_0}F_{i,j^\star}^\prime, & \text{ otherwise}\\
    \end{aligned}\right., \forall j\neq j^\star.
\end{align*}



