\section{Extract Category Similarity Function}

Let \( C_1 \) and \( C_2 \) be the category lists for nodes \( \text{node}_1 \) and \( \text{node}_2 \), respectively. The goal is to compute the category similarity for each pair of nodes \( (\text{node}_1, \text{node}_2) \).


\begin{algorithm}[htbp]
\caption{Extract Category Similarity}\label{alg:extract_category_similarity}
\begin{algorithmic}[1]
\State \textbf{Input:} $samples$, $category\_index$
\State \textbf{Output:} $category\_similarity$
\State Initialize $category\_similarity \gets []$
\For{each $(node1, node2)$ in $samples$}
    \State $max\_index \gets -\infty$
    \For{each $c1$ in $category\_index[node1]$}
        \For{each $c2$ in $category\_index[node2]$}
            \State $common\_categories \gets \text{compare}(c1, c2)$
            \If{any common categories}
                \State $index \gets \text{argmax}(common\_categories)$
                \If{$index > max\_index$}
                    \State $max\_index \gets index$
                \EndIf
            \EndIf
        \EndFor
    \EndFor
    \State Append similarity to $category\_similarity$
\EndFor
\State \Return $category\_similarity$
\end{algorithmic}
\end{algorithm}

