\subsection{Aggregation functions} \label{sec:agg}
Aggregation function convert an MOP into a single-objective optimization problem under a specific preference vector $\vlam$. Some popular aggregation functions are:

\begin{enumerate}
    \item \textbf{COSMOS}:
    \begin{equation}
        g^\mathrm{cosmos}_\vlam(\vtheta) = \vlam^\top \vL(\vtheta) - \mu \frac{\vlam^\top \vL(\vtheta)}{\|\vlam\| \|\vL(\vtheta)\|},
    \end{equation}
    where $\mu$ is a positive weight factor to align the objective vector $\vL(\vtheta)$ with the preference vector $\vlam$.

    \item \textbf{Linear scalarization (LS)}:
    \begin{equation}
        g^\mathrm{LS}_\vlam(\vtheta) = \sum_{i=1}^m \lambda_i L_i(\vtheta).
    \end{equation}

    \item \textbf{Tchebycheff (Tche)}:
    \begin{equation}
    g^\mathrm{Tche}_\vlam(\vtheta) = \max_{1 \leq i \leq m} \lbr{ \lambda_i (L_i(\vtheta) - z_i) },
    \end{equation}
    where $\vz$ is a reference point, usually set as the nadir point the minimal value in each objectives. 

    \item \textbf{Modified Tchebycheff (mTche)}:
    \begin{equation} \label{eqn:app:mtche}
        g^\mathrm{mTche}_\vlam(\vtheta) = \max_{1 \leq i \leq m} \left \{ \frac{L_i(\vtheta) - z_i}{\lambda_i} \right \},
    \end{equation}
    where $\vz$ is a reference point, the same as the point used in the Tchebycheff scalarization function. 
    \item \textbf{Smooth Tchebycheff (STche)}:
    \begin{equation}
        g^\mathrm{STche}_\vlam(\vtheta) = \frac{1}{h} \log \sbr{\sum_{i=1}^m \exp(h \cdot \lambda_i (L_i(\vtheta) - z_i))}.
    \end{equation}
    The Smooth Tchebycheff function uses a relaxed Smooth \(\max\) operator. The advantage of this approach is that \(g^\mathrm{STche}_\vlam(\vtheta)\) becomes a Smooth function if each objective function \(L_i(\vtheta)\) is Smooth, unlike the non-Smooth \(g^\mathrm{Tche}_\vlam(\vtheta)\). Smooth functions generally have faster convergence compared to non-Smooth ones. Similarly, we can define the Smooth modified Tchebycheff function. 

    \item \textbf{Penalty-Based Intersection (PBI):}
    \begin{equation}
        g^\mathrm{PBI}_\vlam(\vtheta) = 
        \underbrace{\frac{1}{\norm{\vlam}} \cdot \sum_{i=1}^m \lambda_i L_i(\vtheta)}_{d_1}
         + \mu \underbrace{\norm{\vL(\vtheta) - \frac{d_1}{\norm{\vlam}} \cdot \vlam}}_{d_2},
    \end{equation}
    where $\mu$ is a positive weight factor that encourage a objective to align with a preference vector $\vlam$.

    \item \textbf{$p$-norm}: 
    \begin{equation}
        g^\mathrm{pnorm}_\vlam(\vtheta) =
        {\norm{\vlam \odot \vL(\vtheta) - \vz}_p}.
    \end{equation}
    The symbol $\odot$ denotes the element-wise product between two vectors.
    \item \textbf{Augmented Achievement Scalarization Function (AASF)}:
    \begin{equation}
        g^\mathrm{AASF}_\vlam(\vtheta) = g^\mathrm{mTche}_\vlam(\vtheta) + \rho g^\mathrm{LS}_\vlam(\vtheta),
    \end{equation}
    where $\rho$ is small positive coefficient, which is usually set as 0.1. Contour curves for this functions for a bi-objective case can be found in the \href{https://libmoondocs.readthedocs.io/en/latest/gallery/aggfuns.html}{LibMOON Doc}~\footnote{\url{https://libmoondocs.readthedocs.io/en/latest/gallery/aggfuns.html}}. 
\end{enumerate}

