\subsection{Metrics} \label{sec:metrics}
Metrics used in \algoname~can be categorized into two groups. The first group evaluates the quality of a \emph{set} of solutions $\sY = \{ \vy^{(1)}, \ldots, \vy^{(N)} \}$, with specific metrics such as IGD and FD relying on the known Pareto front for accuracy.
The second group of metrics assesses the quality of \emph{individual} solutions $\vy$ when a preference vector $\vlam$ is provided.

Group 1: Metrics for a set of solutions.
\begin{enumerate}
    \item Hypervolume (HV) ($\uparrow$) \cite{guerreiro2020hypervolume}: This metric evaluates both the convergence to the Pareto Front (PF) and the diversity of solutions. A low HV value indicates poor convergence, while high HV values imply better performance. The hypervolume is calculated as the volume dominated by at least one solution in the set $\sS$ with respect to a reference point $\vr$:
    \begin{align*}
        \mathrm{HV}_\vr(\sS) = \mathrm{Vol}( {\vy \; | \; \exists \vy' \in \sS, \vy' \preceq \vy \preceq \vr } ).
    \end{align*}
    \item Inverted Generational Distance (IGD) \cite{ishibuchi2015modified}: IGD measures the average distance between points in a reference set $\sZ$ and the nearest solutions in the set $\sS$: \begin{align*}
        \operatorname{IGD}(\sS) = \frac{1}{|\sZ|}\left( \sum_{i=1}^{|\sZ|} \min_{\vy' \in \sS} \rho(\vy^{(i)}, \vy')^2 \right)^{1/2}.
    \end{align*}
    \item Fill Distance (FD) \cite{zhang2024umoea}: This metric calculates the covering radius of a set of solutions $\sS$, defined as the maximum minimum distance from any point in the reference set $\sZ$ to the nearest solution in $\sZ$:
    \begin{equation}
        \mathrm{FD}(\sS) = \max_{\vy' \in \sZ} \min_{\vy \in \sS} \rho(\vy, \vy').
    \end{equation}
    \item
    Minimal Distance ($\mathrm{l}_{\min}$): This metric captures the smallest pairwise distance among all objectives:
    \begin{align*}
        \mathrm{l}_{\min} = \min_{1 \leq i < j \leq N} \rho(\vy^{(i)}, \vy^{(j)})
    \end{align*}
    where $\rho()$ denotes the Euclidean distance.
    \item Smooth Minimal Distance ($\mathrm{sl}_{\min}$): This metric is a ``smooth-min" version of the minimal distance function, defined as:
    \begin{equation}
        \mathrm{sl}_{\min} = -\frac{1}{h \cdot k(k-1)} \log \left( \sum_{1 \leq i < j \leq N} \exp\left(-h \rho\left(\vy^{(i)}, \vy^{(j)} \right)\right) \right). 
    \end{equation}

    \item Spacing: This metric measures the standard deviation of the minimal distances from one solution to others, with lower values indicating a more uniform distribution of objective vectors: \begin{equation}
        \mathrm{spacing} = \frac{1}{N} \sum_{i=1}^N (d_i - \bar{d})^2, \qquad \bar{d} = \frac{1}{N} \sum_{i=1}^N d_i, \qquad d_i = \min_{1 \leq i \neq j \leq N} \rho(\vy^{(i)}, \vy^{(j)}).
    \end{equation}

    \item Span: This metric evaluates the range (span) of solutions in their minimal dimension, defined as: \begin{equation}
        \mathrm{Span} = \min_{1 \leq i \leq m} \max_{1 \leq k < l \leq N} | y_i^{(k)} - y_i^{(l)}|.
    \end{equation}
\end{enumerate}

Group 2: Metrics for individual solutions.
\begin{enumerate}
    \item Penalty-based Intersection (PBI): This metric is a weighted sum of two distance functions $d_1$ and $d_2$, given by $\mathrm{PBI} = d_1 + \mu d_2$, where \begin{equation}
        d_1 = \frac{\langle \vy - \vz, \vlam \rangle}{\norm{\vlam}}, \qquad d_2 = \norm{\vy - (d_1 \vlam + \vz)}.
    \end{equation}
    \item Inner Product (IP): This metric measures the alignment of the objective vector $\vy$ with the preference vector $\vlam$:
    \begin{equation}
        \mathrm{IP} = \langle \vy, \vlam \rangle.
    \end{equation}
    \item Cross Angle ($\vartheta$): For bi-objective problems, this metric measures the angular difference between the objective vector and the preference vector:
    \begin{equation}
        \vartheta = \norm{\arctan(y_2 / y_1) - \arctan(\lambda_2 / \lambda_1)}.
    \end{equation}
\end{enumerate}

Those metrics are summarized in \Cref{tab:metrics} and also can be found in the \href{https://libmoondocs.readthedocs.io/en/latest/apis/Libmoon_metric.html}{\algoname~document}. 

