\subsection{Exploration Process of $G(n,p)$}
In \cite{chinyaev2024er_eng} we studied the exploration process in the random graph $G(n,p)$. It is used to find the connected component containing a vertex $v$. We briefly review its construction. In this process, vertices can be in one of three states: active, neutral, or explored. Initially, the starting vertex $v_{0}$ is declared active, and all other vertices are neutral.
\begin{equation*}
\mathcal{A}_{1} =\{v_{0} \},\quad \mathcal{U}_{1} =V\setminus \{v_{0} \},\quad \mathcal{R}_{1} =\emptyset .
\end{equation*}
Then, at each step $t$, an active vertex $v_t$ is considered (at the first step the starting vertex is chosen), and all its neutral neighbors become active, while $v_t$ is reclassified as explored.
\begin{equation}\label{AUW}
\begin{gathered}
\mathcal{W}_{t} = \{w: (v_t,w) \in E\},\\[1mm]
\mathcal{A}_{t+1} = \Bigl(\mathcal{A}_{t} \setminus \{v_t\}\Bigr) \cup \mathcal{W}_{t},\quad \mathcal{U}_{t+1} = \mathcal{U}_{t} \setminus \mathcal{W}_{t},\quad \mathcal{R}_{t+1} = \mathcal{R}_{t} \cup \{v_t\}.
\end{gathered}
\end{equation}
The process continues until there are no active vertices left; the final set of explored vertices forms the connected component $\mathcal{C}(v_{0})$. The specific choice of the active vertex at each step is not crucial (for example, one may assume that the first vertex added to the active set is chosen).

Let $A_{t}$ denote the number of active vertices and $U_{t}$ the number of neutral vertices at the beginning of step $t$, and let $W_{t}$ be the number of vertices that become active at this step; the number of explored vertices coincides with the step number $t$.
\begin{equation*}
A_{t} = |\mathcal{A}_{t}|,\quad U_{t} = |\mathcal{U}_{t}|,\quad W_{t} = |\mathcal{W}_{t}|.
\end{equation*}
We assume that $A_{1} = 1$, $U_{1} = n-1$, and hence
\begin{equation*}
A_{t+1} = A_{t} + W_{t} - 1,\quad U_{t+1} = U_{t} - W_{t}.
\end{equation*}
Let us consider the trajectories of the process $\{W_{t}\}$ and denote
\begin{equation*}
\mathbf{j} = (j_{1}, \dotsc, j_{n}).
\end{equation*}
For the graph to be connected, it is necessary that at each step before $n$ there remains at least one active vertex, i.e., 
$$
A_{t} = 1 + \left(\sum_{\tau=1}^{t} W_{\tau}\right) - t > 0,\quad t < n.
$$ 
Consequently, the connectivity probability can be expressed in terms of this process as follows:
\begin{equation} \label{Pnp1}
\begin{gathered}
P_{n}(p) = \sum_{\mathbf{j} \in J_{n}} \mathbf{P}\Bigl( (W_{1}, \dotsc, W_{n}) = \mathbf{j} \Bigr),\\[1mm]
J_{n} = \left\{ \mathbf{j} : \sum_{i=1}^{k} j_{i} \geq k,\ k < n,\ \sum_{i=1}^{n} j_{i} = n-1 \right\}.
\end{gathered}
\end{equation}
Since the edges in the graph $G(n,p)$ are independent, we get
\begin{equation*}
\mathbf{P}\Bigl( W_{t} = k \mid A_{t} = l,\, U_{t} = m \Bigr) = \left\{
\begin{array}{ll}
\binom{m}{k} p^{k} (1-p)^{m-k}, & \text{if } A_{t} > 0,\\[1mm]
0, & \text{if } A_{t} = 0.
\end{array}
\right.
\end{equation*}
Therefore,
\begin{equation}\label{Pnp2}
\mathbf{P}\Bigl( (W_{1}, \dotsc, W_{n}) = \mathbf{j} \Bigr)
= \prod_{t=1}^{n} \left( \binom{n-1 - j_{1} - \dotsb - j_{t-1}}{j_{t}} p^{j_{t}} (1-p)^{j_{t+1} + \dotsb + j_{n}} \right).
\end{equation}

\subsection{Connection with an Inhomogeneous Poisson Random Walk}

In \cite{chinyaev2024e_eng} we have transformed expression (\ref{Pnp2}) into the form
\begin{equation}
\mathbf{P}\Bigl( (W_{1}, \dotsc, W_{n}) = \mathbf{j} \Bigr)
= \frac{n! \exp(n)}{n^{n}} \left( 1 - (1-p)^{n} \right)^{n-1} \prod_{t=1}^{n} \left( \exp(-\lambda_{t}) \frac{\lambda_{t}^{j_{t}}}{j_{t}!} \right),
\end{equation}
where
\begin{equation}\label{lambda_i}
\lambda_{i} = \frac{np}{1-(1-p)^{n}} (1-p)^{(i-1)}, \quad \sum_{i=1}^{n} \lambda_{i} = n.
\end{equation}
Hence, the following relation holds:
\begin{equation}\label{PW=j}
\mathbf{P}\Bigl( (W_{1}, \dotsc, W_{n}) = \mathbf{j} \Bigr)
= \frac{n! \exp(n)}{n^{n}} \left( 1 - (1-p)^{n} \right)^{n-1} \ \mathbf{P}\Bigl( (X_{1}, \dotsc, X_{n}) = \mathbf{j} \Bigr),
\end{equation}
where the $X_{i}$ are independent random variables with $X_{i} \sim \mathrm{Poiss}(\lambda_{i})$.
Then, by summing expression (\ref{PW=j}) over $\mathbf{j} \in J_{n}$, we obtain
\begin{equation}\label{PnpJX}
\begin{gathered}
P_{n}(p) = \mathbf{P}\Bigl( (W_{1}, \dotsc, W_{n}) \in J_{n} \Bigr) = \\
= \mathbf{P}\Bigl(\sum_{i=1}^{n} X_{i} = n-1\Bigr)^{-1} \left( 1 - (1-p)^{n} \right)^{n-1} \mathbf{P}\Bigl( (X_{1}, \dotsc, X_{n}) \in J_{n} \Bigr).
\end{gathered}
\end{equation}
Thus, we obtain the following lemma.
\begin{Lemm}[\cite{chinyaev2024er_eng}]\label{connect}
Let $G(n,p)$ be an Erdős–Rényi graph. Then the connectivity probability is given by
$$
P_n(p) = \left( 1 - (1-p)^{n} \right)^{n-1} \mathbf{P}\Bigl( S_k \geq 0,\ 0 < k < n \mid S_{n} = -1 \Bigr),
$$
where $S_k = \sum_{i=1}^{k} (X_i - 1)$, and the $X_i$ are independent random variables with $X_i \sim \mathrm{Poiss}(\lambda_i)$, with the parameters $\lambda_i$ defined by (\ref{lambda_i}).
\end{Lemm}

From the above reasoning, it follows that one can obtain the distribution of the trajectory of the process $\{W_{k}\}$ in a connected graph, or more precisely, deduce how it is expressed in terms of the trajectory distribution of the random walk $\{X_{k}\}$. To do this, we obtain the conditional distributions of the trajectories by dividing expression (\ref{PW=j}) by (\ref{PnpJX}), from which we derive the following corollary.

\begin{Co}\label{connect_co}
Under the conditions of Lemma \ref{connect}, the following relations hold:
\begin{equation}
\begin{gathered}
\mathbf{P}\Bigl( (W_{1}, \dotsc, W_{n}) = \mathbf{j} \mid G\text{ is connected} \Bigr) = \\
= \mathbf{P}\Bigl( (W_{1}, \dotsc, W_{n}) = \mathbf{j} \mid (W_{1}, \dotsc, W_{n}) \in J_{n} \Bigr) = \\
= \mathbf{P}\Bigl( (X_{1}, \dotsc, X_{n}) = \mathbf{j} \mid (X_{1}, \dotsc, X_{n}) \in J_{n} \Bigr).
\end{gathered}
\end{equation}
\end{Co}

This corollary is crucial for developing an algorithm for generating connected graphs. Since there is an exact equality between the distributions of the processes $\{W_{k}\}$ and $\{X_{k}\}$ on the conditional spaces, we can generate their trajectories using the space of Poisson random variables $\{X_{k}\}$.

In this space, in the case $p=c/n$, the event that the trajectory remains non-negative occurs with a certain positive probability (asymptotically independent of $n$). We discuss this probability in Section \ref{Complexity1} for the analysis of the algorithm's complexity.

