\section{Generation of Connected $G(n,p)$}
\subsection{Generation Algorithm}\label{section:alg1}

Based on the discussion above, we propose the following generation scheme. First, we generate the exploration trajectory of the graph. Then, given a fixed exploration, we construct the graph. The overall procedure is described in Algorithm~\ref{alg:connected-gnp}.
\par
\vspace{0.5em}

\LinesNumbered
\begin{algorithm}[H]
\DontPrintSemicolon
\caption{Generation of a Connected $G(n,p)$ Graph}
\label{alg:connected-gnp}
\vspace{0.3em}
\KwIn{Number of vertices $n \ge 1$, edge probability $0<p\leq1$}
\KwOut{Connected graph $G$ from $G(n, p)$}
\vspace{0.3em}

\textbf{Step 1. Generation of the exploration trajectory} 

$\displaystyle \lambda_i \gets \frac{np}{1 - (1 - p)^n} (1 - p)^{i - 1}, \quad i = 1, \dots, n$

% \Repeat{condition: $\displaystyle S_k \ge 0$ for $k < n$, $S_n = -1$}
% {
% Generate $\displaystyle X_i \sim \text{Poiss}(\lambda_i), \quad i = 1, \dots, n$
%
% $\displaystyle S_k \gets \sum_{i=1}^k (X_i - 1), \quad k = 1, \dots, n$
% }

\Repeat{until $\displaystyle S_k \ge 0$ for all $k < n$}
{
Generate $\displaystyle (X_1, \dots, X_n) 
\sim 
\mathrm{Multinomial}\left(n-1; \,\tfrac{\lambda_1}{n}, \dots, \tfrac{\lambda_n}{n}\right)$

$\displaystyle S_k \gets \sum_{i=1}^k (X_i - 1), \quad k = 1, \dots, n$
}
\vspace{0.3em}

\textbf{Step 2. Construction of the exploration tree} 

$\displaystyle \mathcal{A}_1 \gets \{v_0\}, \quad \mathcal{U}_1 \gets V \setminus \{v_0\}$

\For{$t = 1$ \KwTo $n$}{
Select $\displaystyle v_t \in \mathcal{A}_t$

Select uniformly at random $\displaystyle \mathcal{W}_t \subset \mathcal{U}_t$, \ $|\mathcal{W}_t| = X_t$ (with probability $1/\binom{|\mathcal{U}_t|}{X_t}$)

Add edges $\displaystyle (v_t, w)$ to $E(G)$ for all $\displaystyle w \in \mathcal{W}_t$

Update $\displaystyle \mathcal{A}_{t+1}, \ \mathcal{U}_{t+1}$ according to (\ref{AUW})

}
\vspace{0.3em}

\textbf{Step 3. Addition of the remaining edges} 

$\displaystyle \mathcal{P} \gets \bigcup_{t} \{ (v_t, w) : w \in \mathcal{A}_t \setminus v_t \}$

\For{each pair $\displaystyle (u,v) \in \mathcal{P}$}{
    Add the edge $\displaystyle (u,v)$ to $E(G)$ with probability $p$
}
\vspace{0.2em}
\Return{graph $\displaystyle G$}
\end{algorithm}


