\subsection{Generation of the Graph for a Fixed Exploration}
Now, consider the probability of obtaining a specific graph $g$ given a fixed trajectory of the process $\{W_k\}$, that is, the distribution
\begin{equation*}
\mathbf{P}\Bigl( G = g \ \Bigl| \ (W_1,\dots,W_n) = \mathbf{j} \Bigr).
\end{equation*}
Next, we will show that this measure coincides with the measure obtained by the following procedure (Steps 2 and 3 of Algorithm~\ref{alg:connected-gnp}).

\paragraph{1) Reconstruction of the Tree from the Trajectory.}
Let the exploration trajectory of the graph be given by $\mathbf{j} = (j_1, j_2, \dots, j_n)$. We construct an exploration tree that is consistent with this trajectory. Considering the steps $t = 1, \dots, n$, we build the sets $\mathcal{A}_t$ and $\mathcal{U}_t$ according to (\ref{AUW}). The set $\mathcal{W}_t$ is constructed as follows:
\begin{enumerate}[1.]
    \item At step $t$, an active vertex $v_t \in \mathcal{A}_t$ is selected according to a fixed selection rule.
    \item Then, from the current set of unexplored vertices $\mathcal{U}_t$, a subset $\mathcal{W}_t$ of size $j_t$ is selected uniformly at random, i.e., every subset $\mathcal{W}_t \subseteq \mathcal{U}_t$ with $|\mathcal{W}_t| = j_t$ is chosen with probability $1/\binom{|\mathcal{U}_t|}{j_t}$.
    \item For each vertex $w \in \mathcal{W}_t$, the edge $(v_t, w)$ is added to the exploration tree under construction. These edges form the set $\mathcal{T}$.
\end{enumerate}

\newpage

Once the exploration tree is fully constructed, every pair of vertices can be classified into one of the following three disjoint sets:

\begin{enumerate}[\textbullet]
\item $\mathcal{T}$: pairs of vertices connected by the edges of the constructed exploration tree. These are exactly the edges used to discover new vertices during the exploration:
\begin{equation*}
\mathcal{T} = \bigcup_{t} \{ (v_t, w) : w \in \mathcal{W}_t \}.
\end{equation*}

\item $\mathcal{F}$: pairs $(v, w)$ such that, at the moment when $v$ was selected as an active vertex, $w$ was still unexplored (i.e., in the neutral set $\mathcal{U}_t$), but the edge $(v, w)$ was not selected to be part of the exploration tree:
\begin{equation*}
\mathcal{F} = \bigcup_{t} \{ (v_t, w) : w \in \mathcal{U}_t \setminus \mathcal{W}_t \}.
\end{equation*}

\item $\mathcal{P}$: all remaining unordered pairs of vertices, which were not considered during the exploration process. The presence of edges between these pairs has not yet been determined:
\begin{equation*}
\mathcal{P} = \{ (v, w) : (v, w) \notin \mathcal{T},\ (v, w) \notin \mathcal{F} \}
= \bigcup_{t} \{ (v_t, w) : w \in \mathcal{A}_t \setminus \{v_t\} \}.
\end{equation*}
\end{enumerate}

\paragraph{2) Generation of the Remaining Edges.}
Thus, we have constructed the exploration tree and partitioned all pairs of vertices into the disjoint sets $\mathcal{T}$, $\mathcal{F}$, and $\mathcal{P}$. Then, for all pairs belonging to the set $\mathcal{P}$, each edge is sampled independently with inclusion probability $p$. Therefore, the set of edges of the final graph $g$ is given by
$$
E(g) = \mathcal{T} \cup \{\, (u,v) \in \mathcal{P} : \xi_{u,v} = 1 \,\},
$$
where $\xi_{u,v} \sim \mathrm{Bernoulli}(p)$ are independent for all $(u,v) \in \mathcal{P}$.

\paragraph{Correctness.} The correctness of this procedure is based on the following reasoning. Indeed, the sequence of sets $\mathbf{w} = (\mathcal{W}_1, \dots, \mathcal{W}_n)$ determines only the presence in the graph $g$ of edges from the set $\mathcal{T}$ and the absence of edges from the set $\mathcal{F}$. Formally, the following relation holds:
\begin{equation*}
\left\{ g : (\mathcal{W}_1, \dots, \mathcal{W}_n) = \mathbf{w} \right\} \Leftrightarrow \left\{ g : \left\{ \bigcap_{e \in \mathcal{T}(\mathbf{w})} e \in E(g) \right\} \cap \left\{ \bigcap_{e \in \mathcal{F}(\mathbf{w})} e \notin E(g) \right\} \right\}.
\end{equation*}
This relation holds in one direction by construction. Moreover, $\mathbf{w}$ can be uniquely recovered from $\mathcal{T}(\mathbf{w})$ and $\mathcal{F}(\mathbf{w})$. Hence, due to the overall independence of the edges in the $G(n,p)$ model, we obtain
\begin{equation*}
\mathbf{P}\Bigl( (\mathcal{W}_1, \dots, \mathcal{W}_n) = \mathbf{w} \Bigr) = p^{|\mathcal{T}(\mathbf{w})|} (1-p)^{|\mathcal{F}(\mathbf{w})|}.
\end{equation*}
Similarly, by the definition of the $G(n,p)$ model, for the remaining pairs of vertices (from the set $\mathcal{P}$) the state of an edge is determined by an independent trial with probability $p$. Therefore, we obtain
\begin{gather*}
\mathbf{P}\Bigl( G = g \ \Bigl| \ (\mathcal{W}_1, \dots, \mathcal{W}_n) = \mathbf{w} \Bigr) = \\
\prod_{e \in \mathcal{T}(\mathbf{w})} \mathds{1}\{e \in g\} \; \prod_{e \in \mathcal{F}(\mathbf{w})} \mathds{1}\{e \notin g\} \; \prod_{e \in \mathcal{P}(\mathbf{w})} p^{\mathds{1}\{e \in g\}} (1-p)^{\mathds{1}\{e \notin g\}}.
\end{gather*}

In our procedure, at step $t$, a subset of $j_t$ vertices is selected uniformly at random without replacement from the set $\mathcal{U}_t$ (with probability $1/\binom{|\mathcal{U}_t|}{j_t}$). This is consistent with the desired distribution due to the symmetry of the model. Indeed, $|\mathcal{T}(\mathbf{w})|$ and $|\mathcal{F}(\mathbf{w})|$ depend only on $|\mathbf{w}| = (|\mathcal{W}_1|, \dots, |\mathcal{W}_n|)$:
\begin{equation*}
|\mathcal{T}(\mathbf{w})| = \sum_{t=1}^{n} |\mathcal{W}_t|,\quad |\mathcal{F}(\mathbf{w})| = \sum_{t=1}^{n} \left( n-1 - \sum_{\tau=1}^{t} |\mathcal{W}_{\tau}| \right).
\end{equation*}
Hence,
\begin{gather*}
\mathbf{P}\Bigl( (\mathcal{W}_1, \dots, \mathcal{W}_n) = \mathbf{w} \ \Bigl| \ (W_1, \dots, W_n) = \mathbf{j} \Bigr) \\
= \mathds{1}\{|\mathbf{w}| = \mathbf{j}\} \frac{p^{|\mathcal{T}(\mathbf{w})|} (1-p)^{|\mathcal{F}(\mathbf{w})|}}{\sum\limits_{\tilde{\mathbf{w}} :\, |\tilde{\mathbf{w}}| = \mathbf{j}} p^{|\mathcal{T}(\tilde{\mathbf{w}})|} (1-p)^{|\mathcal{F}(\tilde{\mathbf{w}})|} } 
= \mathds{1}\{|\mathbf{w}| = \mathbf{j}\} \frac{j_1! \dots j_n!}{n!}.
\end{gather*}
This indeed corresponds to our procedure.

\subsection{Complexity Analysis}\label{Complexity1}

Let us estimate the running time of the three stages of Algorithm~\ref{alg:connected-gnp}:
\begin{enumerate}[1.]
\item \emph{Generation of the exploration trajectory (Step~1)}. An acceptance-rejection scheme is used here; according to the results of \cite{chinyaev2024er_eng}, two key estimates hold for the probability that the random walk $\{S_k\}$ remains non-negative:
\begin{enumerate}[\textbullet]
    \item \emph{Non-asymptotic lower bound}:
    $$
    \mathbf{P}(S_k \geq 0, \ 0 < k < n \mid S_{n} = -1) \ge 1/n.
    $$
    It follows that when generating $\{X_i\}$, even for arbitrarily small $p$, on average no more than $n$ restarts are required.
    \item \emph{Asymptotic expression} as $n \to \infty$ and $p = c/n$:
    \begin{equation}\label{positivity_asympt}
    \mathbf{P}(S_k \geq 0, \ 0< k < n| S_{n} = -1 )
    \sim
    \bigl(1 - e^{-c}\bigr)\,\bigl(1 - \tfrac{c\,e^{-c}}{1 - e^{-c}} \bigr).
    \end{equation}
    In this case, the probability of a ``positive'' walk does not decrease with increasing $n$, and the number of restarts remains $O(1)$.
\end{enumerate}
Each generation of the multinomial vector $\{X_i\}$ takes $O(n)$ operations, so the overall contribution of Step~1 is at most $O(n^2)$. For $p = c/n$ with fixed $c$, the above asymptotics reduce this part to $O(n)$.

\item \emph{Construction of the exploration tree (Step~2).}  
Here, $n$ iterations are performed, in each of which $X_t$ vertices are selected uniformly from $\mathcal{U}_t$. The total complexity of these actions does not exceed $O(n^2)$.

\item \emph{Addition of the remaining edges (Step~3).}  
In the worst case, the number of unchecked vertex pairs is of order $n^2$. For all pairs, independent Bernoulli trials with probability $p$ are performed. Accordingly, this results in an additional $O(n^2)$ operations.
\end{enumerate}

Therefore, the total complexity of Algorithm~\ref{alg:connected-gnp} remains within $O(n^2)$ In the case $p = c/n$, the fraction of "positive" walks is asymptotically constant, so Step~1 takes $O(n)$; however, the total time still remains of order $O(n^2)$ due to Steps~2 and~3. Therefore, the final algorithm is almost as efficient in complexity as generating graphs without the connectivity condition.

