    \includegraphics[width=0.95\linewidth, height=0.55\linewidth]{Generation/fig_gen/edges_distribution_Gnm.pdf}
    \caption{Distribution of the number of edges when generating $G(n,m)$ via $G(n,p)$}
    \label{fig:gnm-ru}
\end{figure}

